window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[9] = [{"id":1164,"category_id":9,"category_code":"s9","source_id":1,"title":"موشک جواب موشک","content":"مثل این که اولین بارش بود پا به منطقه عملیاتی می گذاشت. از آن آدم هایی بود که فکر می کرد مأمور شده است که انسان های گناهکار، به خصوص عراقی های فریب خورده را به راه راست هدایت کرده، کلید بهشت را دستشان بدهد.\r\nشده بود مسؤول تبلیغات گردان. دیگر از دستش ذله شده بودیم. وقت و بی وقت بلندگوهای خط اول را به کار می انداخت و صدای نوحه و مارش عملیات تو آسمان پخش می شد و عراقی ها مگسی می شدند و هر چی مهمات داشتند سر مای بدبخت خالی می کردند. از رو هم نمی رفت. تا این که انگار طرف مقابل، یعنی عراقی ها هم دست به مقابله به مثل زدند و آن ها هم بلندگو آوردند و نمایش تکمیل شد. مسؤول تبلیغات برای این که روی آنها را کم کند، نوار \"کربلا، کربلا، ما داریم می آییم\" را گذاشت. لحظه ای بعد صدای نعره ای از بلندگوی عراقی ها پخش شد که: \"آمدی، آمدی، خوش آمدی جانم به قربان شما. قدمت روی چشام. صفا آوردی تو برام!\" تمام بچه ها از خنده ریسه رفتند و مسؤول تبلیغات رویش را کم کرد و کاسه کوزه اش را جمع کرد و رفت.\r\n"},{"id":1165,"category_id":9,"category_code":"s9","source_id":2,"title":"دشمن","content":"اولین عملیاتی بود که شرکت می کردم. بس که گفته بودند ممکن است موقع حرکت به سوی مواضع دشمن، در دل شب عراقی ها بپرند تو ستون و سرتان را با سیم مخصوص از جا بکنند، دچار وهم و ترس شده بودم. ساکت و بی صدا در یک ستون طولانی که مثل مار در دشتی صاف می خزید، جلو می رفتیم. جایی نشستیم. یک موقع دیدم که یک نفر کنار دستم نشسته و نفس نفس میزند. کم مانده بود از ترس سکته کنم. فهمیدم که همان عراقی سر پران است. تا دست طرف، رفت بالا، معطل نکردم. با قنداق سلاحم محکم کوبیدم تو پهلویش و فرار را بر قرار ترجیح دادم. لحظاتی بعد عملیات شروع شد.\r\nروز بعد در خط بودیم که فرمانده گروهانمان گفت: \"دیشب اتفاق عجیبی افتاده، معلوم نیست که کدام شیر پاک خورده ای به پهلوی فرمانده کوبیده که همان اول بسم الله دنده هایش خرد و روانه عقب شده.\" از ترس صدایش را در نیاوردم که آن شیر پاک خورده من بوده ام!\r\n"},{"id":1166,"category_id":9,"category_code":"s9","source_id":3,"title":"موشک جواب موشک","content":"مثل این که اولین بارش بود پا به منطقه عملیاتی می گذاشت. از آن آدم هایی بود که فکر می کرد مأمور شده است که انسان های گناهکار، به خصوص عراقی های فریب خورده را به راه راست هدایت کرده، کلید بهشت را دستشان بدهد.\r\nشده بود مسؤول تبلیغات گردان. دیگر از دستش ذله شده بودیم. وقت و بی وقت بلندگوهای خط اول را به کار می انداخت و صدای نوحه و مارش عملیات تو آسمان پخش می شد و عراقی ها مگسی می شدند و هر چی مهمات داشتند سر مای بدبخت خالی می کردند. از رو هم نمی رفت. تا این که انگار طرف مقابل، یعنی عراقی ها هم دست به مقابله به مثل زدند و آن ها هم بلندگو آوردند و نمایش تکمیل شد. مسؤول تبلیغات برای این که روی آنها را کم کند، نوار \"کربلا، کربلا، ما داریم می آییم\" را گذاشت. لحظه ای بعد صدای نعره ای از بلندگوی عراقی ها پخش شد که: \"آمدی، آمدی، خوش آمدی جانم به قربان شما. قدمت روی چشام. صفا آوردی تو برام!\" تمام بچه ها از خنده ریسه رفتند و مسؤول تبلیغات رویش را کم کرد و کاسه کوزه اش را جمع کرد و رفت.\r\n"},{"id":1167,"category_id":9,"category_code":"s9","source_id":4,"title":"دشمن","content":"اولین عملیاتی بود که شرکت می کردم. بس که گفته بودند ممکن است موقع حرکت به سوی مواضع دشمن، در دل شب عراقی ها بپرند تو ستون و سرتان را با سیم مخصوص از جا بکنند، دچار وهم و ترس شده بودم. ساکت و بی صدا در یک ستون طولانی که مثل مار در دشتی صاف می خزید، جلو می رفتیم. جایی نشستیم. یک موقع دیدم که یک نفر کنار دستم نشسته و نفس نفس میزند. کم مانده بود از ترس سکته کنم. فهمیدم که همان عراقی سر پران است. تا دست طرف، رفت بالا، معطل نکردم. با قنداق سلاحم محکم کوبیدم تو پهلویش و فرار را بر قرار ترجیح دادم. لحظاتی بعد عملیات شروع شد.\r\nروز بعد در خط بودیم که فرمانده گروهانمان گفت: \"دیشب اتفاق عجیبی افتاده، معلوم نیست که کدام شیر پاک خورده ای به پهلوی فرمانده کوبیده که همان اول بسم الله دنده هایش خرد و روانه عقب شده.\" از ترس صدایش را در نیاوردم که آن شیر پاک خورده من بوده ام!\r\n"},{"id":1168,"category_id":9,"category_code":"s9","source_id":5,"title":"امدادگر","content":"بار اولم بود که مجروح می‌شدم و زیاد بی‌تابی می‌کردم یکی از برادران امدادگر بالاخره آمد بالای سرم و با خونسردی گفت:«چیه، چه خبره؟»تو که چیزیت نشده بابا!\r\nتو الان باید به بچه‌های دیگر هم روحیه بدهی آن وقت داری گریه می‌کنی؟! تو فقط یک پایت قطع شده! ببین بغل دستی است سر نداره هیچی هم نمی‌گه، این را که گفت بی‌اختیار برگشتم و چشمم افتاد به بنده خدایی که شهید شده بود!\r\nبعد توی همان حال که درد مجال نفس‌کشیدن هم نمی‌داد کلی خندیدم و با خودم گفتم عجب عتیقه‌هایی هستند این امدادگرا.\r\n"},{"id":1169,"category_id":9,"category_code":"s9","source_id":6,"title":"اللهم الرزقنا توفیق الپارتی","content":"وقتی آشپز مراعات حال برادران سنگین وزن- هیكلی تداركاتی- را می‌كرد و غذایشان را یك كم چربتر می‌كشید، یا میوه درشت‌تری برایشان می‌گذاشت، هر كس این صحنه را می‌دید، به تنهایی یا دسته جمعی و با صدای بلند و شمرده شمرده شروع می‌كردند به گفتن: «اللهم الرزقنا توفیق الپارتی فی الدنیا و الاخره!» یعنی دارید پارتی بازی می‌كنید حواستان جمع باشد!"},{"id":1170,"category_id":9,"category_code":"s9","source_id":7,"title":"زندگی یك ساعته","content":"در عملیات كربلای 4 به یكی از برادران سپاهی كه بنه(پسته كوهی) را با پوست سخت می جوید گفتم:\r\nاصغری دندان هایت خراب می شود.\r\nیك ساعت بیشتر با آنها كار ندارم. بعد از آن چه خراب، چه درست!!\r\n"},{"id":1171,"category_id":9,"category_code":"s9","source_id":8,"title":"آفتاب نیمه شب","content":"وقتی بی خوابی می افتاد سرمان،دلمان نمی آمد كه بگذاریم دیگران راحت بخوابند، خصوصا دوستان نزدیك.به هر بهانه ای بود بالا سرشان می رفتیم و آنها را از جا بلند می كردیم.رفیقی داشتیم،خیلی آدم رك و بی رودربایستی بود.\r\nیك شب حوالی اذان صبح رفتم به بالینش،شانه اش را چند بار تكان دادم و آهسته به نحوی كه دیگران متوجه نشوند گفتم:هی هی،بلند شو آفتاب زد. آقا چشمت روز بد نبیند،یك مرتبه پتو را كنار زد، و با صدای بلند گفت:مرد حسابی بگذار بخوابم، به من چه كه آفتاب می زند، شاید آفتاب بخواهد نیمه شب در بیاید،من هم باید نیمه شب بلند بشوم. عجب گیری افتادیم ها!!\r\n"},{"id":1172,"category_id":9,"category_code":"s9","source_id":9,"title":"بیت المال","content":"خمپاره که می زدند طبیعتاً اگر در سنگر نبودیم خیز می رفتیم تا از ترکش آن محفوظ بمانیم. بعضی صاف صاف می ایستادند و جنب نمی خوردند و اگر تذکر می دادی که دراز بکش، می گفتند: بیت المال است. حالا که این بنده خدا به خرج افتاده نباید جاخالی داد. حیف است، این همه راه آمده خوبیت ندارد."},{"id":1173,"category_id":9,"category_code":"s9","source_id":10,"title":"ورود كلیه بردران ممنوع","content":"شیشه در وردی ناهار خوری شكسته بود. این عبارت را با ماژیك قرمز روی كاغذی نوشته و به دیوار چسبانده بودنند:«ورود كلیه برادران ممنوع». موقع ناهار بود. سالن هم در دیگری نداشت. یعنی چه؟ هیچ كس تصور نمی كرد در بسته نباشد یا این كه قضیه شوخی باشد چند نفری رفتند پیش مسئول مربوط و داد و فریاد راه انداختند:«این چه وضعشه، در چرا بسته است، این كاغذ چیه كه نوشته اید؟» و از این حرف ها. بعد راه افتادند رفتند آشپزخانه. البته از در پشتی كه مخصوص مسئولان بود. جریان را كه تعریف كردند سر آشپز خندید و گفت:«اولاً در بسته نیست باز است. ثانیاً ما نگفتیم كلیه. گفتیم كلیه، برای همین روی لام تشدید نگذاشتیم».حسابی كفری شدیم. فكر همه چیز را می كردیم الا این كه آشپزها هم با ما بله!"},{"id":1174,"category_id":9,"category_code":"s9","source_id":11,"title":"جوان چهارده ساله","content":"پیرمردی بود از تك و تا افتاده اما در قبول مسئولیت به كم تر از حضور در خط مقدم و منطقه عملیاتی رضا نمی داد.\r\nـ تو بااین سن و سال می خواهی بیایی جلو كه چه بشود؟\r\nـ من دیگر آدم قبل نیستم بعد از این مدت كه جبهه بوده ام دیگر مثل پسرهای چهارده ساله جوان شده ام!\r\n"},{"id":1175,"category_id":9,"category_code":"s9","source_id":12,"title":"لا اضحك","content":"ساعت های 1 و 2 نیمه شب بود كه در میان همهمه و شلیك توپ و تانك و مسلسل و آرپی چی و غرش هواپیماهای دشمن در عملیات بزرگ كربلای 5 ، فرمانده تخریب بعد از چندین بار صدا زدن اسم من ، بالاخره پیدایم كرد و گفت : حمید هرچه سریعتر این اسرا را به عقب ببر و تحویل كمپ اسرا بده . سریع آماده شدم.\r\nسی و دو نفر اسیر عراقی كه بیشترشان مجروح بودند ، سوار بر پشت دو دستگاه خودروی تویوتا شدند و من با یك قبضه كلاش تاشو با نشستن بر پنجره خودرو دستور حركت خودروها را به سمت كمپ اسرا صادر كردم مسافتی طی نكرده بودیم كه متوجه شدم چند اسیر عراقی به من نگریسته و اسمم را صدا زده و با هم میخندند. اول تعجب كردم كه اینها اسم مرا از كجا میدانند . زود به خاطر آوردم صدا زدن های فرمانده مان را كه به دنبال من میگشت و عراقیها نیز یاد گرفته بودند . من با 18 سال سنی كه داشتم از لحاظ سن و هیكل از همه آنها كوچكتر بودم. بگی نگی كمی ترس برم داشت . گفتم نكند در این نیمه شب ، اسرا با هم یكی شوند و من و راننده بی سلاح را بكشند و فرار كنند.\r\nدنبال واژه ای گشتم كه به زبان عربی معنای نخندید یا ساكت باشید ، بدهد . كلمه « ضحك » به خاطرم آمد كه به معنای خنده بود. با خودم گفتم : خوب اگر به عربی بگویم نخندید ، آنها می ترسند و ساكت می شوند . لذا با تحكم و بلند داد زدم «لا اضحك». با گفتن این حرف علاوه بر چند نفری كه می خندیدند ، بقیه هم كه ساكت بودند شروع به خنده كردند . چند بار دیگر «لا اضحك» را تكرار كردم ولی توفیری نكرد.\r\nسكوت كردم و خودم نیز همصدا با آنها شروع به خنده كردم. چند كیلومتری كه طی كردیم به كمپ اسرای عراقی رسیدیم و بعد از تحویل دادن 32 اسیر به مسئولین كمپ ، دوباره با همان خودروها به خط مقدم برگشتیم . در خط مقدم به داخل سنگرمان كه بچه های تخریب حضور داشتند رفتم و بعد از چاق سلامتی قضیه را برایشان تعریف كردم. بعد از تعریف ماجرا ، دو سه نفر از برادران همسنگر كه دانشجویان دانشگاه امام صادق (ع) بودند و به زبان عربی نیز تسلط داشتند ، شروع به خنده كردند و گفتند فلانی می دانی به آنها چه می گفتی كه آنها بیشتر می خندیدند تو به عربی به آنها می گفتی « لا اضحك » كه معنی آن می شود « من نمیخندم» و برای اینكه به آنها بگویی نخند یا نخندید ، باید می گفتی « لا تضحك  ................. آنجا بود كه به راز خنده عراقیها پی بردم.\r\n"},{"id":1176,"category_id":9,"category_code":"s9","source_id":13,"title":"شوخی با نماینده صلیب سرخ","content":"یکی از بچّه‌ها، به خیال خودش می ‌خواست با نماینده‌ ی صلیب سرخ که آن روز در اردوگاه بود، مزاحی کرده باشد.\r\nپشت در مخفی شد و همین ‌که صلیبی می خواست وارد آسایشگاه شود، از جلویش درآمد و بلند گفت: \" پخ\" \r\nبنده‌ ی خدا در جا غش کرد و دراز به دراز افتاد کفِ آسایشگاه.\r\nهول هولکی آب آوردیم، زدیم به صورتش و آب قندی به خوردش دادیم تا کم ‌کم حال آمد. بعد هم کلّی ازش معذرت خواهی کردیم و قضیه به خیر و خوشی تمام شد.\r\n"},{"id":1177,"category_id":9,"category_code":"s9","source_id":14,"title":"وقتش رسیده","content":"شب بود. زیر چادر نشسته بودیم، حرف ازدواج شد. همه به هم تعارف می كردند، هر كس سعی می كرد دیگری را جلو بیندازد. یكی از برادران گفت:«ننه من قاعده ای دارد. می گوید هر وقت پایت از لحاف آمد بیرون، موقع زن گرفتن است». وقتی این حرف را می زد كه علی پروینی فرمانده دسته خوابیده بود و اتفاقاً پایش از زیر پتو بیرون افتاده بود. همه خندیدم و یك صدا گفتیم: با این حساب وقت ازدواج برادر پروینی است."},{"id":1178,"category_id":9,"category_code":"s9","source_id":15,"title":"من كاظم پول لازم","content":"تلگراف صلواتی بود، توصیه می كردند مختصر و مفید نوشته شود، البته به ندرت كسی پیام ضروری تلگرافی داشت. اغلب دوتا، سه تا برگه می گرفتند و همین طوری پر می كردند، مهم نبود چه بنویسند. مفت باشه خمپاره جفت جفت باشه! بعد می آمدند برای هم تعریف می كردند كه به عنوان چند كلمه فوری، فوتی و ضروری چه نوشته اند. دوستی داشتم كه وقتی از او پرسیدم :«كاظم چی نوشتی؟» گفت:«نوشتم بابا سلام. من كاظم پول لازم». گفتم:«همین؟» گفت:\"آره دیگر. مفهوم نیست؟\""},{"id":1179,"category_id":9,"category_code":"s9","source_id":16,"title":"من جاسم هستم","content":"در رودخانه نزدیك مقر آب تنی می كردیم. یكی از بچه ها كه شنا بلد نبود افتاد توی آب. چند بار رفت زیر آب و آمد بالا. شنا بلد نبود یا خودش را به نابلدی می زد خدا می داند، برادری پرید توی آب و او را گرفت، وقتی داشت او را با خودش می آورد بالا می گفت:«كاكا سالم هستی؟» و او نفس زنان می گفت: نه كاكا سالم خانه است من جاسم هستم!"},{"id":1180,"category_id":9,"category_code":"s9","source_id":17,"title":"قابلمه خورش","content":"فرمانده گروهانمان روزی ما را جمع كردند كه برایمان صحبت كند. معمولاً این قبیل جلسات با عملیات آینده بی ارتباط نبود. در انتهای سخنرانی، گفتند«قبل از جاكن شدن ببینید چیزی كم و كسری نداشته باشید، جلوتر نمی توانیم تهیه كنیم». منظور ایشان وسایل شخصی و رزمی و سلاح و مهمات و سایر تجهیزات بود. یكی، دو، سه نفر راجع به وسایلشان سۆال هایی كردند و نشستند. از آن میان، پیرمردی برخاست، سید ابراهیم بود، كمك تداركات چی گروهان. گفت: آقا ما قابلمه خورش نداریم!"},{"id":1181,"category_id":9,"category_code":"s9","source_id":18,"title":"شیخ محمد","content":"عراق قله شیخ محمد را تصرف كرده بود. در تبلیغات گردان برادری داشتیم به همین نام. وقتی كسی او را از دور می دید و صدایش می زد، هر كس می شنید می گفت:\"دست عراق است، داد و فریاد نكن!\""},{"id":1182,"category_id":9,"category_code":"s9","source_id":19,"title":"آب بخور","content":"موقع آموزش غواصی در آب بود و مثل خشكی، فرصت هایی هم برای رفع خستگی به شعار و شوخی می گذشت\r\nـ برادرا كی تشنه است؟(به جای شعار كی خسته است؟ كه جوابش می شد: دشمن)\r\nـ من\r\nـ آّب بخور.(منظور آب غیر قابل شرب! و آن هم با دهان پر از تجهیزات)\r\n"},{"id":1183,"category_id":9,"category_code":"s9","source_id":20,"title":"زبان سبز","content":"زبان چه سبز و چه سرخ، نرم یا تند و بی مهابا، صریح و با اشاره و كنایه وقتی از غلاف صبر و سكوت بیرون آمد نماینده منویات قلبی گوینده است \r\nـ شما تا به حال عصبانی شده ای؟\r\nـ كم نه\r\nـ وقتی از كوره در بروی بدهانی هم می كنی؟\r\nـ تا دلت بخواد.\r\nـ مثلاً چه می گویی؟\r\nـ مرگ بر آمریكا!\r\n"},{"id":1184,"category_id":9,"category_code":"s9","source_id":21,"title":"كمی پایین تر","content":"از مسئولات ستاد پشتیبانی آموزش و پرورش بود و با مسئول بسیج، كه از برادران سپاهی بود، صحبت می كرد. \r\nـ ما خاك كف پای بچه های بسیج هستیم. \r\nـ ما كمی پایین تر!(كنایه از این كه ما از خاك هم كم تریم. شعر سعدی : گفتی ز خاك بیش ترند اهل عشق من از خاك بیشتر نه كه از خاك كم ترین)\r\n"},{"id":1185,"category_id":9,"category_code":"s9","source_id":22,"title":"فکر کردم مغزم ریخته کف دستم!","content":"مدت زیادی بود که خبری از عملیات نبود، گرمای هوا همه را کلافه کرده بود؛ بر و بچه‌های تیپ 25 کربلا،‌ هر کدام خودشان را مشغول می‌کردند تا گرما رو کمتر حس کنند، یک عده نامه می‌نوشتن، یک عده فوتبال و والیبال بازی می‌کردن عده‌ای هم به کارهای دیگر سرگرم بودند؛ یک عده هم طبق معمول مشغول راز و نیاز بودند؛ سید عبدالرضا جزو این دسته بود؛ عابدین (شهید سیدعابدین حسینی) همیشه به‌ همین خاطر سر به سر عبدالرضا می‌گذاشت و می‌گفت :عبدالرضا! این همه نماز نخون یک وقت نورانی میشی بعدش شهید میشی‌ها؛ من حوصله گریه برای تو رو ندارم. اصلاً وقتی شهید بشی یادت که بیفتم به جای گریه خنده‌ام می‌گیره.\r\nمعمولاً سید عابدین به اینجاهای صحبتش که می‌رسید بقیه هم با او هم‌صدا می‌شدند و سر به سر عبدالرضا می‌گذاشتند ولی عبدالرضا دست‌بردار نبود.\r\nیکی از این روزها سید عابدین داخل سنگر آمد و دید که عبدالرضا مشغول نماز خواندن است؛ یک لحظه مکث کرد فکری به ذهنش رسید و سریع از سنگر خارج شد؛ هندوانه‌های زیادی که کمک‌های مردمی بود یک قسمت از محوطه تیپ جمع شده بود و از بس زیاد بود بعضی از آنها تو این گرمای زیاد پلاسیده و لزج شده بودند.\r\nعابدین به طرف هندوانه رفت و نگاهی به هندوانه‌ها انداخت؛ جلوتر رفت و یکی از هندوانه‌ها را که کاملاً پلاسیده و لزج بود را برداشت و خیلی آرام داخل سنگر آمد و رفت پشت عبدالرضا ایستاد؛ به بچه‌ها اشاره کرد که صداتان درنیاید، عبدالرضا در این لحظه به قنوت نماز رسیده بود؛ چشهایش را بست و شروع کرد به خواندن یک قنوت جانانه.\r\nسید عابدین هم معطل نکرد و با هندوانه پلاسیده محکم کوبید پشت سر عبدالرضا و فرار کرد؛ هندوانه پشت سر عبدالرضا پخش شد و کمی از آن هم ریخت تو دستای عبدالرضا؛ بچه‌ها که صدای خنده‌شان توی سنگر پیچید، دیدند که عبدالرضا نقش زمین شد؛ همه ترسیدند و به طرف عبدالرضا رفتند؛ عبدالرضا بیهوش شده بود، عابدین هم که نگران شده بود آهسته داخل سنگر سرک می‌کشید؛ سریع آب آوردن و عبدالرضا را به‌هوش آوردن، به هوش که آمد دستی به سرش کشید و گفت «من زنده‌ام!!، من شهید نشدم؟ چطور من زنده‌ام؟ مگه ترکش به سرم نخورد؟ حال عبدالرضا که بهتر شد»،‌ همسنگرا گفتند :عبدالرضا خجالت نمی‌کشی؟ با یه هندوانه به این روز افتادی؟ چرا غش کردی؟ عابدین با یه هندونه تو رو به این روز انداخت؟!\r\nعبدالرضا که تازه ماجرا رو فهمیده بود زد زیر خنده و گفت «خدا بگم عابدین رو چی کار نکنه؛ من بارها در مورد کسانی که شهید می‌شدند، شنیدم که وقتی تیری به اون‌ها می‌خوره اصلاً دردی احساس نمی‌کنن و سریع شهید می‌شن؛ وقتی اون ضربه به سرم خورد و هندونه ریخت تو دستام،‌ چون خیلی لزج بود، یه لحظه خیال کردم که مغزم ریخته کف دستم و دارم شهید می‌شم.\r\nبا این جمله بود که شلیک خنده بچه‌ها فضا را پر کرد؛ یک لحظه نگاه عابدین که داشت داخل سنگر سرک می‌کشید با نگاه عبدالرضا تلاقی کرد؛‌ عبدالرضا،‌ خنده عابدین رو که دید جستی زد و افتاد دنبال عابدین، جیغ و داد عابدین و کمک‌ خواستن او در هیاهو و خنده‌های بچه‌ها گم شد.\r\n"},{"id":1186,"category_id":9,"category_code":"s9","source_id":23,"title":"آب دندون","content":"شلمچه بودیم.از بس که آتش سنگین شد، دیگه نمی تونستیم خاکریز بزنیم. حاجی گفت: بلدوزرها رو خاموش کنید بزارید داخل سنگرها تا بریم مقّر.\r\nهوا داغ بود و ترکش کُلمَن آب رو سوراخ کرده بود. تشنه و خسته و کوفته، سوار آمبولانس شدیم و رفتیم.\r\nبه مقر که رسیدیم ساعت دو نصفه شب بود. از آمبولانس پیاده شدیم و دویدیم طرف یخچال. یخچال نبود. گلوله‌ی خمپاره صاف روش خورده بود و برده بودش تو هوا. دویدیم داخل سنگر. سنگر تاریک بود، فقط یه فانوس کم نور آخر سنگر می‌سوخت.\r\nدنبال آب می‌گشتیم که پیر مرادی داد زد: «پیدا کردم!» و بعد پارچ آبی رو برداشت و تکون داد.\r\nانگار یخی داخلش باشه صدای تَلق تَلق کرد. گفت: «آخ جون».و بعد آب رو سرازیر گلوش کرد. می‌خورد که حاج مسلم- پیر مرد مقر- از زیر پتو چیزی گفت: «کسی به حرفش گوش نداد. مرتضی پارچ رو کشید و چند قُلُپ خورد.».به ردیف همه چند قُلُپ خوردیم. خلیلیان آخری بود. تَهِ آب رو سر کشید.پارچ آب رو تکون داد و گفت: «این که یخ نیست. این چیه؟\r\nحاج مسلم آشپز، سرشو از زیر پتو بیرون کرد و گفت: «من که گفتم اینا دندونای مصنوعی منه! یخ نیست، اما کسی گوش نکرد، منم گفتم گناه دارن بزار بخورن!» هنوز حرفش تموم نشده بود که همه با هم داد زدیم:وای!\r\nاز سنگر دویدیم بیرون. هر کسی یه گوشه‌ای سرشو پایین گرفته بود تا...\r\nکه احمد داد زد: مگه چیه! چیز بدی نبود! آب دندونه! اونم از نوعِ حاج مسلمش! مثل آب‌نبات\r\nاصلاً فکر کنید آب انجیر خوردید.\r\n"},{"id":1187,"category_id":9,"category_code":"s9","source_id":24,"title":"خیز قاطر","content":"هنگامه عملیات بود و آتش خمپاره. تدارکات لشکر، برای انتقال مهمات‌ و آذوقه نیروها، تعدادی «قاطر» به خدمت گرفته بود. هنگامی که درارتفاعات، در کنار ستون نیروها بالا می‌رفتیم، تا سوت خمپاره می‌آمد قاطرها زودتر از ما خیز می‌رفتند روی زمین تا ترکش نخورند! چند بار که شاهد خیزرفتن قاطرها بودیم، بچه‌ها متعجب از یکدیگر علت این را که چرا آنها زودتراز ما خیز می‌روند، سۆال می‌کردند.\r\nدقایقی گذشت و ما به راه خود ادامه دادیم. ناگهان سوت خمپاره آمد وقاطری که در کنارم بود سریع خیز رفت. من هم که روی جاده دراز کشیدم، نگاهم افتاد به شکم و ران قاطر. خوب که توجه کردم، دیدم جای چند زخم ‌بزرگ که خوب شده بود، روی بدنش وجود دارد.\r\nدیگر نتوانستم جلوی خنده‌ام را بگیرم. بچه‌ها پرسیدند که چرا می‌خندم،گفتم:\r\nـ شماها می‌دونین چرا قاطرها زودتر از شما خیز میرن؟\r\nجواب همه منفی بود. با خنده گفتم:\r\nـ خب معلومه. این بیچاره‌ها توی عملیات قبلی ترکش خوردن و اعزام ‌مجددی هستن و دیگه می‌دونن با سوت خمپاره باید خیز برن که دوباره‌ زخمی نشن\r\n"},{"id":1188,"category_id":9,"category_code":"s9","source_id":25,"title":"الاغی كه عملیات را لو داد!","content":"بعد از عملیات محرم، دشمن به خاطر بازپس گیری مناطقی كه از دست داده بود، چند بار پاتك كرد كه با مقاومت خوب و جانانه بچه‌ها روبرو شد و عقب نشینی كرد. \r\nبعد از این‌ كه آتش دشمن كمی فروكش كرد بچه‌ها از این فرصت استفاده كردند و روبروی پل زبیدات مشغول استراحت شدند. من هم به اتفاق یكی از برادرهای آر‌پی‌جی زن مشغول استراحت شدم. همین‌طور كه استراحت می‌كردم چشمم به آر‌پی‌جی ‌اش افتاد. با دیدن آر‌پی‌جی تصمیم گرفتم كه تیراندازی با آن را یاد بگیرم. برای همین به دوستم گفتم: خیلی دوست دارم با آر‌پی‌جی كار كنم و با آن تیر اندازی كنم.\r\n از او خواستم كه كار با آن را به من بیاموزد. ایشان با آن ‌كه خیلی خسته بود دست رد به سینه‌ام نزد و قبول كرد، كار با آر‌پی‌جی را برایم توضیح دهد... وقتی نحوه كار با آرپی‌جی را یاد گرفتم، دل تو دلم نبود. موشك آر‌پی‌جی را روی آن نصب كرد و توضیحات لازم را به من متذكر شد و آر‌پی‌جی را به من داد. آرپی‌جی را توی دستم گرفتم و برای تمرین تیراندازی كمی از بچه‌ها فاصله گرفتیم. با هم دنبال چیزی می‌گشتیم تا آن را مورد هدف قرار دهیم. همین طور كه می‌گشتیم چشمم به یك الاغ افتاد. خندیدم و گفتم: بیا ببین چی پیدا كردم. وقتی ایشان الاغ را دید زد زیر خنده و گفت: محمد حسابش را بگذار كف دستش تا دیگر این طرف‌ها پیدایش نشود. \r\nمن هم الاغ را نشانه گرفتم و ماشه را چكاندم. موشك شلیك شد. موشك نرسیده به الاغ داخل شیار افتاد و منفجر شد. با انفجار موشك آر‌پی‌جی متوجه شدم یك عده از نیروهای عراقی پا به فرار گذاشتند. با دیدن نیروهای عراقی فهمیدم كه آن‌ها قصد غافلگیر كردن بچه‌ها را داشتند كه به خواست خداوند الاغ نقشه‌های آنان را برملا كرد.\r\n"},{"id":1189,"category_id":9,"category_code":"s9","source_id":26,"title":"اعزام غواص ممنوع","content":"فروردین سال 1365در مقر شهید محمد منتظری، از مقرهای تیپ 44قمربنی هاشم (ع) در نزدیکی سوسنگرد بودیم. هواپیماهای جنگی دشمن برای حمله به عقبه جبهه ایران به پروازدرآمده بودند.وضعیت قرمز اعلام شد وتمام چراغها وروشنایی ها خاموش شد تاهواپیماهای دشمن نتوانند دید داشته باشند وجایی را بزنند. \r\nمشغول غذاخوردن بودیم . غذا آبگوشت بود.آن را در یک سینی بزرگی ریخته بودیم وهمگی دور آن نشسته بودیم ومیخوردیم.\r\nبرق که قطع شد، شیطنتها شروع شد .هرکس کاری می کرد ودر آن تاریکی سربه سردیگری می گذاشت. \r\nباهماهنگی قبلی قرارشد یکی از بچه ها از حوزه استحفاظی آقای خدادادی (بزرگترین عضو رزمندگان اعزامی از شهر طاقانک که در آن زمان حدود27سال داشتند) لقمه ای را بردارد، که ایشان با لحن خاصی گفتند:\r\nلطفا غواص اعزام نفرمایید ،منطقه دردید کامل رادار قراردارد!! \r\nبا این حرف او یک دفعه چادر از خنده بچه ها منفجر شد. اینقدر فضا شاد شده بود که کسی به فکر حمله هوایی دشمن نبود!\r\n"},{"id":1190,"category_id":9,"category_code":"s9","source_id":27,"title":"تحریک دشمن با کارهای شتابزده","content":"در سرپُل‏ذهاب كوههای بزرگ نظیر 1100 و 1150 و تمام رشته كوه بازی دراز در دست دشمن بود و كاملا بر تمامی دشت سرپل‏ذهاب مسلط بود. منطقه، كوهستانی بود و آنها بالای‏كوه قرار داشتند. برای دشمن تصور این كه ما در زیر كوه نیرو مستقر كرده باشیم، بسیار دشوار بود؛ به همین دلیل اگر نیرویی را می‏دیدند، می‏گفتند: برای شناسایی آمده و یا از مردمان همان منطقه است. اما اگر ماشین مخصوص جنگ مثل تویوتا را می‏دیدند، آن قدر به طرف او آتش می‏ریختند تا نابود شود. معمولا روز اگر كسی می‏رفت، او را زیر آتش می‏گرفتند.\r\nروز قبل از عملیات مسۆول ما كه شخصی به نام حاج بابا بود، همه فرماند‏هان و دیده‏بانان را خواست تا هماهنگی لازم را انجام دهد. من هم كه دیده بان بودم، رفتم. ساعت سه بعد از ظهر قرار بود جلسه تشكیل بشود. فرماندة یك گروهان نیامد. تا ساعت 4 به انتظار او نشستیم حاج بابا عصبانی شد و با احساسات كامل ماشین تویوتا را برداشت تا او را در خط مقدم جبهه پیدا كند. به هر حال با تویوتا در روز روشن مقابل دشمن از این طرف به آن طرف می‏رفت تا بالاخره او را پیدا كرد و آورد. من در مدت سه ماه كه آن‏جا بودم یك بار هم چنین كار خطرناكی را از كسی ندیدم. قطعا این كار موجب شد تا دشمن حساستر شود و شب نیروهای بیشتری را برای نگهبانی بگذارد. پیدا كردن آن فرمانده گروهان شاید آن اندازه هم ارزش نداشت كه به واسطة آن، دشمن هوشیار شود. اساسا اگر همة كارها بر مبنای عقل بود بسیاری از اتفاقها نمی‏افتاد.\r\n"},{"id":1191,"category_id":9,"category_code":"s9","source_id":28,"title":"اصطلاحات جبهه ای","content":"زره پوش: پوتین\r\nدر مقابل کفش و دمپایی می گویند که برای راحتی به پا می کنند و به کار زمان صلح می آیند نه جنگ.\r\nیعنی کفش مسلح و آماده مقابله با هر شرایطی، پست و بلند راه و آب و گل و آهن و آتش و ناملایمات دیگر مقتضی منطقه.\r\nذوالفقار: قایقهای دو موتوره\r\nنوع پیشرفته قایق موتوریهایی که در جنگ مورد استفاده قرار گرفت – قایق های عاشورا – و از حیث عقب بودن موتورهایشان، «ری جندر» خوانده می شوند در اصطلاح نظامی انگلیسی. اینکه در نگاه به این قایق از پشت سر، دو موتور آن مثل دو شمشیر تیز به نظر می آید وجه تسمیه ای بوده است تا در کنار عشق و ارادت بچه ها به اهل بیت خصوصاً صاحب ذوالفقار، این نوع قایقها را ذوالفقار بنامد.\r\nزوروی دسته: نیرویی که دور از چشم دیگران و بچه های دسته ظروف غذا را می شوید، ظروف آب را آب می کند و سنگر و چادر را نظافت می کند ؛ به نحوی که هیچ وقت هیچ کس نمی داند که این کارها به وسیله چه کسی انجام شده است. کنایه از اینکه مثل زورو سر بزنگاه حاضر می شود، کارش را می کند و بعد دوباره غیبش می زند.\r\nزیر پاسپورتتان را آقا امضا نکرده:نمی توانید داخل خاک عراق شوید.\r\nوقتی برای عملیات یا گشت و شناسایی بچه ها ناگزیر بودند به داخل خاک عراق بروند و بعضی از سر مزاح یا بنا به عللی نمی آمدند به آنها می گفتند: زیر پاسپورتتان...\r\nضریب زاویه صفر شده: شهید شده است.\r\nوقتی زاویه توپ صفر شود، لوله آن افقی و موازی افق و سطح زمین قرار می گیرد. این حالت، چون قبلاً «افقی برگشتن» به معنی شهادت، و شهید برگشتن فرد را داشته اند، وجه شبه یا تسمیه ای شده تا در مورد برادری که شهید شده بگویند: ضریب زاویه...\r\nآب بیاور نَفَس تازه کن\r\nخسته شدی. از پا افتادی از بس با عجله خوردی. بلند شو آب بیاور بخور، نفسی تازه کن بقیه اش را بعداً بخور.\r\n"},{"id":1192,"category_id":9,"category_code":"s9","source_id":29,"title":"آبگرمکن نفتی","content":"موشک ساخت ایران. کنایه از موشکهای 9 متری و 12 متری است که در جنگ شهرها و برای زدن تأسیسات نظامی و اقتصادی دشمن استفاده می شد. و اشاره دارد به خوش هیکلی! آن؛ درست مثل آبگرمکن نفتی در مقایسه با نوع گازی و کم حجم آن، این موشکها را بچه ها با راکتهای گرد و جمع و کوچولوی دشمن می سنجیدند و نتیجتاً به چنین تعبیر طنز آمیزی می رسیدند."},{"id":1193,"category_id":9,"category_code":"s9","source_id":30,"title":"تشنج","content":"سال 61 در عملیات والفجر مقدماتی (فکه) از واحد تخریب لشگر 27 به گردان ها مأمور شده بودیم و محل حضورم در گردان حنظله بود، یکشب که در گردان خواب بودم متوجه شدم شخصی که در کنار من خوابیده، به نام عباس شیخ عطار به شدت در حال لرزیدن است و به حال تشنج افتاده بود. دندانهایش به شدت چفت شده بود، من که یکباره از خواب پریدم او دست و پای خودش را گم کرد و بعد از یک ربع ساعت بالاخره به حالت اولیه برگشت وهمین که متوجه شد من بالای سرش بوده ام خیلی ناراحت شد که من این قضیه را فهمیده ام، لذا مرا قسم داد تا به کسی چیزی نگویم تا احیانا این مسأله باعث نشود که به عملیات نرود."},{"id":1194,"category_id":9,"category_code":"s9","source_id":31,"title":"گل شقایق","content":"جنگ تمام شده بود و بسیاری از شهدا جا مانده بودند . دلمان پیش آنها بود . باید می رفتیم و بر می گرداندیمشان ؛ اما منطقه حساس بود و موافقت نمی کردند . بالاخره یک فرصت ده روزه گرفتیم . گذشته از دوری راه ، دور و برمان پر از میدانهای گسترده مین بود . چند روزی کارمان جستجو ، سوختن زیر آفتاب و دست خالی برگشتن بود . فرصت ما روز نیمه شعبان به پایان می رسید . بعضی بچه ها پیشنهاد کردند کار را تعطیل کنیم و روز عید ، به خودمان برسیم . اما شهید غلامی گفت : (( نه ، تازه امروز ، روز کار است و باید عیدی خود را امروز از آقا بگیریم .)) همه به این امید حرکت کردیم ، ناامیدتر شدیم . آفتاب داشت غروب می کرد که صدای ناله و توسل شهید غلامی بلند شد : « آقا جون دیگه خجالت می کشیم تو روی مادرای شهدا نگاه کنیم ... » باید وداع می کردیم و بر می گشتیم بغض توی گلوی بچه ها ترکید و به گریه افتادند.. \r\nچند لحظه بعد ، فریاد شهید غلامی که رفته بود شاخه شقایقی را برای معراج شهدا از ریشه بیرون بیاورد ، میخکوبمان کرد . به سویش دویدیم ... شقایق درست روی جمجمه شهیدی سبز شده بود!\r\n"},{"id":1195,"category_id":9,"category_code":"s9","source_id":32,"title":"اصحاب قتلگاه","content":"یکی دو روزی می شد که شهیدی پیدا نکرده بودیم؛یعنی راستش،شهدا ما را پیدا نکرده بودند.گرفته و خسته بودیم.گرما هم بد جوری اذیتمان می کرد.همراه یکی از بچه ها داشتیم از کنار گودال قتلگاه شهدای فکه،که زمانی در زمستان سال 61 عملیات والفجر مقدماتی انجا رخ داده بود،رد می شدیم.ناگهان نیرویی ناخواسته مرا به خودش جذب کرد.متوجه نشدم چیست ولی احساس کردم چیزی مرا به سوی خود می خواند.ایستادم.نظرم به پشت بوته ای بزرگ جلب شد.همراهم تعجب کرد که کجا می روم.فقط گفتم:بیا تا بگویم.دست خودم نبود انگار مرا می بردند.پاهایم جلوتر می رفتند.به پشت بوته که رسیدیم،جا خوردم.صحنه خیلی تکان دهنده وعجیبی بود.همین بود که مرا به سوی خود خوانده بود.ارام بر زمین نشستم و ناخواسته زبانم به«سبحان الله»چرخید.همراهم که متوجه حالتم شد،سریع جلو امد،او هم در جا میخکوب شد.\r\nشخصی که لباس بسیجی به تن داشت،به کپه خاک کنار بوته تکیه داده و پاهایش را دراز کرده بود.یکی دیگر هم سرش را روی ران پای او گذاشته بود و دراز کشیده و خوابیده بود.پانزده سال بود که خوابیده بودند.ادم یاد اصحاب کهف می افتاد،ولی اینها«رمل»بودند.اصحاب فکه،اصحاب قتلگاه،اصحاب والفجرواصحاب روح الله.بدن دومی که سرش را روی پای دوستش گذاشته بود،تا کمر زیر خاک بود.باد و طوفان ماسه ها و رملها را اورده بود رویش.بدن هر دویشان کاملا اسکلت شده بود.ارام در کنار یکدیگر خفته بودند.ظواهر امر نشان می داد مجروح بودند و در کنار تپه خاکی پناه گرفته بودند و همان طور به شهادت رسیده بودند.\r\nارام و با احترام با ذکر صلوات پیکر مطهرشان را جمع کردیم و پلاکهایشان را هم کنارشان قرار دادیم.\r\n"},{"id":1196,"category_id":9,"category_code":"s9","source_id":33,"title":"فکه دیگر جای من نیست!","content":"یکی از روزها که شهید پیدا نکرده بودیم، به طرف «عباس صابری» هجوم بردیم و بنا بر رسمی که داشتیم، دست و پایش را گرفتیم و روی زمین خواباندیم تا بچه ها با بیل مکانیکی خاک رویش بریزند. کلافه شده بودیم. شهیدی پیدا نمی شد. بیل مکانیکی را کار انداختیم.\r\nناخنهای بیل که در زمین فرو رفت تا خاک بر روی عباس بریزد، متوجه استخوانی شدیم که سر آن پیدا شد. سریع کار را نگه داشتیم. درست همانجایی که می خواستیم خاکهایش راروی عباس بریزیم تا به شهدا التماس کند که خودشان را نشان بدهند، یک شهید پیدا کردیم.\r\nبچه ها در حالی که می خندیدند به عباس صابری گفتند: \r\nبیچاره شهیده تا دید می خواهیم تو رو کنارش خاک کنیم، گفت: فکه دیگه جای من نیست، باید برم جایی دیگه برای خودم پیدا کنم...\r\n"},{"id":1197,"category_id":9,"category_code":"s9","source_id":34,"title":"برپا برادار!","content":"بعد از ناهار ولو شده بودیم داخل سنگر. روزهای اولی بود که به خط مقدم اعزام شده بودیم. شیرینی خوابِ بعد از ناهار، پلک.ها را سنگین کرده بود. خط آرام بود. گاه.گاهی صدای خمپاره و تک تیراندازها به گوش می رسید. خُروپُف علی هم بلند شده بود. در فکر روزهای آموزشی بودم که پرده سنگر بالا رفت، نور بیرون پاشید داخل سنگر. از سایه درشت و کوتاهی که در دهانه سنگر بود، امیر را شناختم. نور چشم.ها را می.زد. صدای یکی ـ دو نفر بلند شد؛ \"پرده را بنداز.\"\r\nپرده که افتاد، سنگر دوباره تاریک شد. نورِ کم دریچه بالای سنگر، باز نمایان شد. امیر سراسر سنگر را نگاه کرد. بیشتر بچه.ها خوابشان برده بود. جلوتر آمد. چشمان سیاهش برق می.زد و لبخندی صورت گِرد و سفیدش را پُر کرده بود. صدایش را صاف کرد و گفت: «برادرا... یاالله... یاالله» عباس چفیه را روی صورتش کشید و گفت: \"زَهر مار... چشام تازه گرم شده بود.\"\r\nامیر بی.توجه به او، صدای دورگه.اش را بلندتر کرد: \"یاالله... برادرا... یاالله... اکرم داره می.یاد\"\r\nعباس چفیه.اش را پایین کشید و گفت: \"مگه مَرض داری بچه.ها رو اذیت می.کنی!... اینا شب شناسایی دارند\"\r\nامیر برعکس همیشه، آرام و سنگین گفت: «خودِ حاجی دستور دادند بیان سنگر ما... پاشید پشت سر من داشت می.اومد» از جایم بلند شدم و بلند گفتم: یه خانم... تو خطّ مقدم!؟\r\nبچه.ها خواب زده شده بودند و من و امیر را.هاج و واج نگاه می.کردند. امیر دستی به موهای مشکی و مجعدش کشید و گفت: «زود پاشید سنگر رو مرتب کنید. فکر می.کنم الان پشت پرده منتظره». علی که بیشتر از بقیه از خواب نصف و نیمه.اش عصبانی شده بود، با عجله پیراهنش را پوشید، بقیه هم غُرغُر کنان تندتند سنگر را مرتب کردند. امیر رفت و کنار دهانة سنگر ایستاد. از مرتب شدن چند دقیقه.ای سنگر سرش را به علامت رضایت تکانی داد. پرده سنگر را بالا زد و محترمانه گفت: «بفرمائید... خوش آمدید. » همه کنار هم ایستادیم. چند نفری که هنوز خمیازه می.کشیدند، لباس.هایشان را مرتب کردند. سایة بلندی در دهانة سنگر پشت به نور ظاهر شد. لباس نظامی داشت و چیزی روی سرش انداخته بود. با شانه به عباس زدم و آرام گفتم: «فکر کنم خارجیه!... از صلیب سرخ یا.... عباس پوزخندی زد و گفت: \r\nاسمش اکرمه، تو می.گی خارجیه! گفتم: «آخه... نگاه کن». عباس سرش را بلند کرد. نگاهش کرد و گفت: «نمی.دونم... شاید... »، صدای امیر حرفش را قطع کرد. «خواهش می.کنم بفرمائید، بچه.ها منتظرند»، او هم گردنش را خم کرد و داخل شد. با صدای کلفت و غلیظی گفت: «سلامٌ علیکم». بعد پرده افتاد. با تعجب به او خیره شدیم. از نگاه سنگین ما، سرش را پایین انداخت. سکوت سنگر با انفجار خندة امیر شکست. به یکدیگر نگاه کردیم و زدیم زیر خنده.\r\nاز خندة ما تعجب کرده بود، چفیة روی سرش را پایین کشید و روی گردنش مرتب کرد. عباس با چشم و ابرو، به علی اشاره کرد، علی هم چشمکی زد. چند دقیقه بعد، هر دو پتویی را از پشت سر انداختند روی امیر. ما هم که از امیر رودست خورده بودیم و خواب دلچسب بعد ازظهر را هم از دست داده بودیم، همراه آن دو ریختیم روی پتو. مُشت و لگد بود که بالا و پایین می.رفت. امیر زیر پتو داد و فریاد می.کرد، اما هیچ.کس کوتاه نمی.آمد و دست.بردار نبود. صدای بچه.ها سنگر را پُر کرده بود. بالاخره عباس دلش به رحم آمد و گفت: «بسشه... فکر کنم دیگه ادب شده باشه». پتو را بالا زدیم، امیر مثل پرندة اسیری پرید بیرون. چهار دست و پا گوشة سنگر نشست و شروع کرد به ناله کردن: «آی دستم... دیوانه.ها.... آی کمرم» اما نگاهش که به او افتاد، دوباره شروع کرد به خندیدن. او هنوز آرام و خجالت.زده همان گوشة راست سنگر ایستاده بود و ما را تماشا می.کرد.\r\nامیر قاه.قاه می.خندید و دستش را روی پایش می.زد. آرام که شد گفت: «فکر کردید من دروغ گفتم؟» بلند شد و پیش او رفت. به شانه.اش زد و گفت: این اکرمه... از برادرای نجف. تازه به این منطقه اعزام شده.\r\nاکرم هنوز نمی.دانست چه اتفاقی افتاده، اما لبخند زیبایی، صورت سبزه و کشیده.اش را جذاب.تر کرده بود...\r\n"},{"id":1198,"category_id":9,"category_code":"s9","source_id":35,"title":"الدخیل الخمینی","content":"فروردین 62 در عملیات «والفجر 1» در منطقه‌‌ی شمال فکّه، تك‌تیرانداز یکی از گردان‌های خط شکن لشكر «31 عاشورا» بودم. نیمه‌شب بعد از حماسه‌آفرینی بسیجی‌های عاشورایی، خط را شکستیم. در جنگ میان نفرات دشمن، افرادی غیر عراقی بودند؛ ازجمله: کماندوهای اُردنی، سودانی و حتی دیگر کشورهای عربی مانند، کویت، عربستان سعودی و... كه نیروهای رزمی‌شان را برای جنگ با ایران می‌فرستادند. این نیروها معمولا در خطی پشت خط عراقی‌ها سنگر می‌گرفتند تا هر وقت نیروهای ایرانی از خط اوّلشان عبور كردند، با آنان درگیر شوند و اگر نیروهای عراقی قصد فرار یا اسارت به دست نیروهای اسلام را داشتند، زیر آتش رگبار به هلاکت برسانندشان. \r\nدر یکی از عملیات‌ها که نزدیک بود خط را بشکنیم، بمب‌باران شیمیایی دشمن آغاز شد. همین کارهای دشمن و بی‌اهمیت بودن جان نیروهایشان، باعث شد بسیاری از اسیرهای عراقی، پس از دوران اسارت با ما بجنگند. این‌چنین بود که نیروهای عراقی از مهاجرین عراقی تا اسرا و شیعیانی که از ابتدا با صدام مبارزه می‌کردند، تیپ «بدر» را شكل دادند.\r\nپس از عملیات، وقتی هوا روشن شد، گردان ما با یکی از گردان‌های هوابرد شیراز ادغام شد، تا سنگرهای دشمن را پاک‌سازی كنیم. ابتدا عراقی‌ها را به اسارت فرا می‌خواندیم. اگر مقاومت می‌کردند، نارنجکی داخل سنگرشان می‌انداختیم؛ سپس سنگرها را پاک‌سازی می‌کردیم. \r\nبا این‌كه شانزده سالم بود، از ستون جلوتر افتاده بودم. به سنگری رسیدم و به عربی گفتم: قولوا لا اله الالله\r\nو... منظورم این بود که تسلیم شوید. كسی جواب نداد. خیلی تشنه‌ام بود. معمولا در سنگرهای دشمن آب خُنک و گوارا پیدا می‌شد. وقتی دیدم صدایی نمی‌آید و کسی خارج نمی‌شود، به سرعت وارد سنگر شدم. ناگهان لوله‌ی داغ اسلحه را پشت سرم احساس كردم. آرام‌آرام از سنگر بیرون آمدم. تا چشمم به هیکل بزرگ او افتاد، رنگم پرید. کماندویی اردنی یا سودانی بود، دقیقا یادم نیست. فقط می‌دانم عراقی نبود. \r\nاسرای عراقی تا به اسارت درمی‌آمدند، خیلی سریع این جمله را تكرار می‌كردند: «الدّخیل الخمینی و الموت لصدام. الدّخیل الخمینی و الموت لصدام.» كه ناخودآگاه ورد زبان ما هم شده بود. وقتی هیکل آن كماندو را دیدم که با غضب نگاهم می‌کرد، نزدیك بود كه قبض روح شوم. با خود گفتم، بهتر است اعلام اسارت کنم. ناخواسته و تند تند گفتم: الدخیل الخمینی و الموت لصدام.\r\nبدون آن‌که بدانم اصلا چه می‌گویم، این جمله را تکرار می‌کردم. او لبش را گزید و با چهره‌ی عصبانی گفت: الدخیل الخمینی، هان؟... الموت لصدام، هان؟\r\nو چند تا فحش عربی نثارم کرد. بدون آن‌که بدانم باید چیزی غیر این را بگویم، جواب دادم: نعم، نعم یا سیدی!\r\nبا پوتین‌های بزرگش لگد محكمی به من زد که دو متر به هوا پرت شدم و چند متر آن طرف‌تر افتادم. من هم میان ناله‌ام طوری كه متوجه نشود، به ترکی بهش گفتم: \"اِشَّگ آدام\"\r\nیک مرتبه گلنگدن را کشید و آمد بالای سرم. چشم‌هایش کاسه‌ی خون بود. شاید با خودش فکر می‌کرد که این بسیجی‌های نوجوان چه‌قدر شجاع و با ایمان‌اند كه مدام تکرار می‌کنند: الدخیل الخمینی...\r\nتازه دوزاری‌‌ام افتاده بود که ای دل غافل، من باید برعکس می‌گفتم، تا آمدم بگویم لا ...، به گمان این‌که دوباره می‌خواهم آن جمله را تکرار کنم، بر سرم فریاد زد و گفت: \"اُسکوت\"\r\nو انگشتش را به اشاره‌ی هیس مقابل لب‌هایش گرفت. آماده‌ی شلیک بود. چشم‌هایم را بسته بودم و داشتم اَشهدم را می‌خواندم و كم‌كم از او فاصله می‌گرفتم که ناگهان صدای تیری آمد. بلافاصله تیر دیگری به بازوی راستم خورد كه مرا به هوا بلند کرد و محکم به روی خاکریز کوبید. چشم که باز کردم دیدم بسیجی‌های لشكر «علی‌بن ابی‌طالب(ع)» قم با لبخند، بالای سرم هستند و آن غول بی‌شاخ و دم در گوشه‌ای به خاک افتاده و به درک واصل شده است. \r\nظاهراً آنان ماجرای مرا دیده بودند، هی با خنده می‌گفتند: الدخیل الخمینی، هان؟ الموت لصدام، هان؟\r\nو مدام تکرار می‌کردند. یکی از آنان که مسن‌تر بود، صورتم را بوسید و بازویم را بست. بعد مرا راهی عقب كرد. از فردای آن روز بچه‌های گردان تا به یكدیگر می‌رسیدند، می‌گفتند: الدخیل الخمینی، هان؟\r\nو دیگری جواب می‌داد: الموت لصدام، هان؟\r\nو این قضیه اسباب خنده و شادی بچه‌های گردان را تا مدت‌ها فراهم كرده بود.\r\n"},{"id":1199,"category_id":9,"category_code":"s9","source_id":36,"title":"الهی دستتان بشکند!","content":"یک‌بار در جبهه آقای «فخر الدین حجازی» آمده بود برای سخنرانی و روحیه دادن به رزمندگان. وسط‌های حرفش به یکباره با صدای بلند گفت: «آی بسیجی‌ها!» همه گوش‌ها تیز شد که چه می‌خواهد بگوید. ادامه داد: الهی دستتان بشکند...!\r\nعصبانی شدیم. می‌دانستیم منظور دیگری دارد اما آخه چرا این حرف رو زد؟\r\nیک لیوان آب خورد و گفت: «گردن صدام رو.\r\nاینجا بود که همه زدند زیر خنده!\r\n"},{"id":1200,"category_id":9,"category_code":"s9","source_id":37,"title":"بوی پتو یا بوی شیمیایی","content":"در عملیات خیبر یه روز شیمیایی زدند. یکی از بچه‌ها به نام «جواد زاد خوش» گفت: شنیده‌ام برای جلوگیری از شیمیایی شدن، پارچه‌ای را خیس کرده و مقابل دهان و بینی خود می‌گیرند.\r\nخیلی سریع برای یافتن دستمال خیس به سمت سنگر دویدیم. داخل سنگر، هرکس به دنبال آب و دستمال می‌گشت که جواد ظرف آبی را روی پتویی ریخت و گفت: بچه‌ها بیایید و هر یک گوشه‌ای از این پتو را جلوی دهان و بینیتان بگیرید.\r\nناگهان متوجه شدیم که بوی پتو از بوی شیمیایی هم بدتر است. چون ظهر همان روز مقداری آبگوشت روی آن ریخته بود و بچه‌ها آن را همان‌طور جمع کرده و در گوشه‌ای گذاشته بودند تا در فرصتی مناسب بشویند. خلاصه، جواد در این موقعیت با خنده گفت: اه اه! بوی این پتو از شیمیایی بد تره.\r\nشلیک خنده به هوا رفت!\r\n"},{"id":1201,"category_id":9,"category_code":"s9","source_id":38,"title":"ترسیدم روز بخورم ریا بشه","content":"توی بچه‌ها خواب من خیلی سبک بود. اگر کسی تکان می‌خورد، می‌فهمیدم. تقریباً دو سه ساعت از نیمه شب گذشته بود. خوروپف بچه‌هایی که خسته بودند، بلند شده بود؛ که صدایی توجهم را جلب کرد. اول خیال کردم دوباره موش رفته سراغ ظرف‌ها، اما خوب که دقت کردم، دیدم نه، مثل این که صدای چیز خوردن یک جانور دو پا است.\r\nیکی از بچه‌های دسته بود. خوب می‌شناختمش. مشغول جنگ هسته‌ای بود. آلبالو بود یا گیلاس، نمی‌دانم. آهسته طوری که فقط خودش بفهمد، گفتم: «اخوی، اخوی! مگه خدا روز را از دستت گرفته که نصف شب با نفست مبارزه می‌کنی؟\r\nاو هم بی‌معطلی پاسخ داد: ترسیدم روز بخورم ریا بشه!\r\n"},{"id":1202,"category_id":9,"category_code":"s9","source_id":39,"title":"کی بود گفت یا حسین (ع)؟","content":"مسجد تیپ در فاو سخنرانی برگزار می‌کرد. بعد از مراسم، یکی از بسیجیان بلند شد و ظرف آب را برداشت و افتاد وسط جمعیت برای سقایی! می‌گفت: هر که تشنه است، بگوید یا حسین (ع)\r\nعجیب بود، در آن گرما و ازدحام نیرو که جای سوزن انداختن نبود، حتی یک نفر آب نخواست. مگه می‌شد تشنه نباشند؟\r\nغیرممکن بود. من از همه جا بی‌خبر بلند شدم، گفتم: یا حسین (ع)\r\nبعد همان بسیجی برگشت پشت سرش و گفت: کی بود گفت یا حسین (ع)؟\r\nدستم را بلند کردم و گفتم: من بودم اخوی\r\nگفت: بلند شو. بلند شو بیا. این لیوان و این هم پارچ، امام حسین (ع) شاگرد تنبل نمی‌خواهد.\r\n"},{"id":1203,"category_id":9,"category_code":"s9","source_id":40,"title":"ملائکه دارند قلقلکش می‌دهند ","content":"الله اکبر، سر نماز هم بعضی دست بردار نبودند. به محض این که قامت می‌بستی، دستت از دنیا! کوتاه می‌شد و نه راه پس داشتی نه راه پیش، پچ پچ کردن‌ها شروع می‌شد. مثلاً می‌خواستند طوری حرف بزنند که معصیت هم نکرده باشند و اگر بعد از نماز اعتراض کردی بگویند ما که با تو نبودیم!\r\nاما مگر می‌شد با آن تکه‌ها که می‌آمدند آدم حواسش جمع نماز باشد؟ مثلاً یکی می‌گفت: واقعاً این که می‌گویند نماز معراج مؤمن است این نمازها را می‌گویند نه نماز من و تو را. دیگری پی حرفش را می‌گرفت که : من حاضرم هر چی عملیات رفتم بدهم دو رکعت نماز او را بگیرم؛ و سومی: مگر می‌دهد پسر؟ و از این قماش حرف‌ها؛ و اگر تبسمی گوشه لبمان می‌نشست بنا می‌کردند به تفسیر کردن: ببین! ببین! الان ملائکه دارند غلغلکش می‌دهند؛ و این جا بود که دیگر نمی‌توانستیم جلوی خودمان را بگیریم و لبخند تبدیل به خنده می‌شد، خصوصاً آن جا که می‌گفتند: مگرملائکه نا محرم نیستند؟ و خودشان جواب می‌دادند: خوب با دستکش غلغلک می‌دهند.\r\n"},{"id":1204,"category_id":9,"category_code":"s9","source_id":41,"title":"سلمانی صلواتی","content":"نزدیک عملیات بود و موهای سرم بلند شده بود. باید کوتاهش می کردم. مانده بودم معطل تو آن برهوت که جز خودمان کسی نیست، سلمانی از کجا پیدا کنم. تا این که خبردار شدم که یکی از پیرمردهای گردان یک ماشین سلمانی دارد و صلواتی موها را اصلاح می کند. رفتم سراغش. دیدم کسی زیر دستش نیست. طمع کردم و جلدی با چرب زبانی، قربان صدقه اش رفتم و نشستم زیر دستش. اما کاش نمی نشستم. چشمتان روز بد نبیند. با هر حرکت ماشین بی اختیار از زور درد از جا می پریدم. ماشین نگو تراکتور بگو! به جای بریدن مو ها، غِلفتی از ریشه و پیاز می کندشان!\r\nاز بار چهارم، هر بار که از جا می پریدم، با چشمان پر از اشک سلام می کردم. پیرمرد دو سه بار جواب سلامم را داد. اما بار آخر کفری شد و گفت:\"تو چت شده سلام می کنی.یک بار سلام می کنند.\"\r\nگفتم :\"راستش به پدرم سلام می کنم. \"پیرمرد دست از کار کشید و با حیرت گفت:\"چی؟ به پدرت سلام میکنی؟ کو پدرت؟\" \r\nاشک چشمانم را گرفتم و گفتم: \"هر بار که شما با ماشینتان موهایم را می کنید، پدرم جلوی چشمم میاد و من به احترام بزرگتر بودنش سلام می کنم!\"\r\nپیرمرد اول چیزی نگفت. اما بعد پس گردنی جانانه ای خرجم کرد و گفت:\"بشکنه این دست که نمک ندارد...\"\r\nمجبوری نشستم و سیصد، چهارصد بار دیگر به آقاجانم سلام کردم تا کارم تمام شد.\r\n"},{"id":1205,"category_id":9,"category_code":"s9","source_id":42,"title":"پل! ","content":"ـ پل تصرف نشه، نیروها تو محاصره دشمن می افتن!\r\nنیمه شب باید پل تصرف می شد. محل عبور افراد گردان جاده ی بود به عرض پنج، شش متر که شب قبل تصرف کرده بودیم و تمام گلوله های توپخانه و خمپاره های دشمن دقیق می ریخت روی همین جاده باریک! با هر انفجار و موج، دست و پا بود که به هوا پرتاب می شد. خطی از آتش تیربار هم افراد را درو می کرد. عقب نشینی هم متصور نبود. \r\nـ تاریکی شب از بین دشمن عبور می کنید! با شروع حمله، عقب نشینی یعنی خودکشی! \r\nبا پیشروی پنجاه متری، نیمی از گردان کشته و زخمی شدند! از شدت آتش معدودی خود را به نی زار و باتلاق غیر قابل عبور دو سمت جاده انداختند. توی آن آتش توپ و خمپاره، جوانی از واحد تبلیغات خونسرد با بلندگوی دستی شعار حماسی و پیروزی می داد و افراد را تشویق به پیشروی می کرد: « به پیش...پیروزی نزدیک...درود بر شما...»\r\nخمپاره ی نزدیکم زمین خورد و آرنج دست چپم حالت برق گرفتگی پیدا کرد. بی اختیار اسلحه کلاش از دستم افتاد. سرم مثل کوه سنگین شد و گوشم غیر از سوت ممتد، چیزی نمی شنید و انفجار آدم ها را مثل فیلم صامت می دیدم. زیر نور منورهای که توی آسمان می ترکید. به دستم نگاه کردم، دست از کتف به پوست و آستین آویزان بود و انگار تاب می رفت و می آمد. و خونی که فواره می زد بیرون! دلم ریش ریش شد و جلو چشمم سیاهی رفت. \r\nـ تنها راه نجات، تصرف پل... \r\nبا دست دیگر، محل زخم دست آویزان از پوست را گرفتم. فشار دادم و لت و لو پیش رفتم به سمت پُل. چند متر دورتر پایم خورد به بلندگوی دستی جوانی که شعار حماسی می داد. کمی دورتر خودش هم غرق در خون افتاده بود. با خود گفتم: « باید برسم به پل!» \r\nزیر آتش شدید به قدری پیش رفتم تا جلو چشمم سیاه شد و زمین خوردم.\r\nچشم که باز کردم، هوا روشن، روی پل نشسته بودم و سرباز دشمن بالای سرم ایستاده بود!\r\n"},{"id":1206,"category_id":9,"category_code":"s9","source_id":43,"title":"جای خالی یک لبخند","content":"هنوز چشمان درخشان عسلي رنگ يحيي را كه از خاك و دود به خون نشسته بود مي توانست به خوبي مجسم كند. \r\nسه روز بود كه در محاصره بود كه در همان خانه نيم سوخته از شهري كه ديگر ويران شده بود گير افتاده بودند و آخرين تيرهاي شان را شليك مي كردند.  \r\nنمي دانست كخ بعد از چندين بار تلاش بي ثمر چرا يحيي تصميم گرفت دوباره به كوچه پشتي نزديك شود تا راه فراري پيدا كند . وقتي مي رفت شانه هاي پهن اش فرو افتاده بود و روي گونه هاي خوش رنگش قشري از خاك نشسته بود و حتي براي لحظه اي گره از ابروانش باز نمي شد . چند تا زخمي جلوي چشمش جان داد بودند كه دو تا از بهترين دوستانش بودند.  \r\nقبل از رفتن كنارش نشست و به ديوار تكيه داد . لب هايش را كه به هم نزديك مي كرد پوست ها يي كه در حال از دست دادن رطوبت شان بودند به هم مي چسبيدند و از زير آن ها خون بيرون مي زد. \r\nگفت كه \r\n-\" اگه گير افتادم . منو بزن . اگه گرفتنم منو بكش ! باشه رضا . نمي خوام دست اينا بيافتم  \r\nمي خواست بخندد ، مي خواست دلداري بدهد . اما رمق ها رفته بود و حرفي كه زده مي شد مهم ترين حرف ها بود . حرف ها هم مثل آخرين گلوله ها سرنوشت ساز بود.  \r\nيحيي رفت در حالي كه او تنها يك گلوله در تفنگ داشت.  \r\nبه آجرها چنگ زد و از لاي شكاف ، كوچه را با سرعت از نظر گذراند . ديدش ؛ به بالا نگاه مي كرد. به سمت همان خانه ي نيم سوخته و او را صدا مي زد .دست هايش را بسته بودند و او با تمام قوا خودش رابه سمت خانه ي نيم سوخته مي كشيد و او را صدا مي زد.\r\n\r\n رضا ، تو رو خدا منو بزن ... رضا تو رو به حسين منو بزن. دارم به ات مي گم منو بزن مرد ، مگه كري؟ چي به ات گفتم ، منو بزن! \r\nترسيده و گريان اسلحه را نشانه رفت . سينه اش در تيررس گذاشت . نفسش سنگين شده بود.  دستش لرزيد و اسلحه را به زمين انداخت و سرش را به ديوار كوبيد. سرباز عراقي با قنداق تفنگ يحيي را محكم به جلو پرت كرد و بعد ناگهان همه جا تيره و سياه شد و او ديگر هيچ چيز نفهميد.  \r\nهزاران هزار بار آن لحظه را مرور كرده بود . همه ي جوانب را سنجيده بود. حتي فكر كرده بود شايد راهي بوده كه نجاتش بدهد و چون خيلي گيج . هيجان زده بود ، متوجه نشده  \r\nوقتي اين طور فكر مي كرد ديگر زندگي برايش غير قابل تحمل مي شد . همه چيز زندگي زهرش مي شد.  \r\nآرامشش ، شيطنت بچه ها و حتي لبخند هاي پروانه زنش . مقابل آيينه ايستاد . داشت به موهاي خاكستري و اندام جا افتاده و كو تاهش نگاه مي كرد كه تصوير پروانه در آيينه ظاهر شد و بدون اين كه به او نگاه كند روسري را روي موهاي بلوطي رنگش بست و گفت: \r\n\" بريم رضا ! دير مي شه \" \r\nهمان طور به نيم رخ و چشمان درشت و مودب پروانه چشم دوخته بود و ذهنش در هزار توي ترديدهايش گرفتار بود. پروانه به سمتش برگشت و با صدايي كه نمي دانست چرا آهسته بود گفت: \r\n-\" خواهش مي كنم ديگر فكر نكن ! تو اين سيزده سال تو هر روز خودت رو تا مرز جنون پيش بردي . من هم ديگه خسته شدم . هر كس ديگه هم جاي تو بود اون كار رو نمي كرد . آخه كي برادر خودش رو با تير مي زنه ؟! ... اين خيلي واضحه اما من تعجب مي كنم ، كه تو هنوز به اين مسئله فكر مي كني. \r\nروي صندلي نشست و آهي كشيد: \r\nتو نمي دوني پروانه . اون جا نبودي . نمي دوني . فقط من مي دونم و يحي كه به ما چه گذشت. \r\nاما در راه گاهي به پروانه نگاه مي كرد و وقتي لبخند اطمينان بخش او را مي ديد دلش گرم مي شد. \r\nعضلاتش را جمع مي كرد و پايش را بيش تر روي پدال گار مي فشرد. يك جور انرژي در رگ هايش مي دويد و سعي مي كرد بيش تر به حرف هاي زنش فكر كند تا شايد اين حال نسبتا خوب مدتي ادامه يابد: \r\n حالا كه برمي گرده ، حتما خوش حال مي شه كه بين خونوادشه و \r\nدرسته كه سختي كشيده اما با ديدن پسرش كه حالا مهندسي قبول شده تمام سختي كشيده اما با ديدن پسرش كه حالا مهندسي قبول شده تمام سختي ها از يادش مي ره و روزهاي زيادي رو پيش هم مي شينيد و از خاطرات تون تعريف مي كنيد. \r\nپاي اتوبوس كه ايستاده بود ديگر هيچ اثري از دل خوشي چند دقيقه قبل نبود . دلش در يك خلا بي انتها مي تپيد . سرهاي قهوه اي رنگ تراشيده ، صورت هاي تكيده و لب هايي كه انگار تازه براي لبخند زدن جا باز مي كرد ، خودشان را از پنجره ي اتوبوس ها به او نشان مي دادند . هر چند لحضه كسي از ميان جمعيت جيغي مي كشيد كه با شعف شروع مي شد و با ناله اي دردآور و كش دار به پايان مي رسيد.  \r\nنگاهي به زهره كه كمي آن طرف تر ايستاده بود انداخت . زهره حواسش به هيچ كجا نبود و فقط به رو به رو نگاه مي كرد . اسراي آزاد شده را مي پاييد و مهدي كه دست هايش را روي شانه هاي مادر گذاشته بود و در حالي كه سرش را به او نزديك كرده بود ، جمعيت را نگاه مي كرد . انگار مي خواست از پشت چشمان مادرش ، پدرش را بشناسد. مگر آن موقع چند سالش بود ، فقط پنج سال. اما او محال بود اشتباه كند . چشمان عسلي درخشان او، اين سال ها لحظه اي ازمقابلش دور نشده بود. بلند قامت تر از خودش بود . اما موهايش حتما خاكستري شده بود ، مثل خودش.  \r\nنور آفتاب چشمانش را به اشك نشانده بود . قدري از پروانه و زهره فاصله گرفت . نگاهش را پايين انداخت و به پاهاي جمعيت چشم دوخت.او را حتي از پاهاش مي توانست بشناسد . زيرا زميان هاي زيادي پيش مي آمد كه با شوخي و خنده به رسم كشتي گيران پاهاي او را مي گرفت تا زمينش بزند. اما هر چه تلاش مي كرد انگار پاها توي زمين ريشه دوانده بودند  حتي يك ميلي متر از جاي شان حركت نمي كردند و او خنده كنان و عرق ريزان خودش را جلوي پاي او را زمين ولو مي كرد.  \r\nاز ياد آوري خاطرات گذشته لبخني كم رنگ روي لب هايش نشسته بود و متوجه نبود مدتي است پاهاي با دمپاي پلاستيكي رنگ و رو رفته در مقابلش ايستاده . وقتي پاها كمي طولاني تر ايستادند ناگهان توجه اش جلب شد . پاهايش تكيده و لاغر با جاي سوخته گي هاي عميق كه سفيد شده بود و انگشتاني كه يكي در ميان قطع شده بود . يك لحظه وحشت كرد و نگاهش را از روي صاحب پاها سراند و نيم نفسي كشيد . با چشماني مات و ريز به اوخيره شده بود . پوست آفتاب سوخته اش روي استخوان پيشاني چسبيده بود و مو نداشت. \r\nشقيقه اش تير كشيد. پاهايش مال خودش نبودند . برگشت تا با آخرين توان به سمت زهره و مهدي و پروانه برگردد . اما صدايش كه كرد ديگر نتوانست باور نكند . به آرامي سرش را برگرداند . انگار تمام رگ هايش به يك باره از خون خالي شد. زهره و مهدي هم پشت سرش بودند . يحيي غبار ايستاده بود . انگار در طول اين سيزده سال هنوز از پشت غبار بيرون نيامده بود.  \r\nچشمان خودش مدت ها بود كه با دود و آتش غريبه شده بودند . اما چشمان او هنوز از دود و آتش به خون نشسته بودند توي حفره ها . خسته شده و عقب رفته بودند توي حفره ها شايد قدري آرام شوند ، اما خيلي زود مي شد فهميد كه مرده اند.  \r\n***\r\n\r\nبدون اين كه به خودش نگاه كند. از مقابل آيينه گذشت . به پيچ دستگيره ي در ور مي رفت  اما گوشش به پروانه بود كه روي صندلي گوشه هال نشسته بود و در حالي كه دست هاي پسر كوچكش را كه بخ او آويزان شده بود و مدام وول مي خورد ، گرفته بود با خودش نجوا مي كرد:\r\n-\" زهره وقتي فهميد يحيي داره برمي گرده چه قدر خوش حال بود . چه قدر با وسواس همه چيز را تغيير داد. همون شب وقتي پيراهن پوست پيازش رو كه خيلي به اش ميومد ، پوشيده بود فهميدم كه زياد به يحيي نزديك نمي شه . نمي خواست با اون سروضع مرتب كنار يحيي بياسته ، يحيي جلو من و بچه ها ضعيف ترو خسته تر نشون بده . بي چاره آقا يحيي يك مشت پوست و استخوان ، توي صندلي فرو رفته بود و نگاهش كف اتاق دودو مي زد. \r\nظاهرا فقط يك پيچ را سفت مي كرد اما تمام صورتش عرق كرده بود . لب پايين اش را گاز گرفت و حرفي نزد. پروانه بچه را قدري از روي زمين بلند كرد و به خود فشرد \r\n از زندگي ساقط ده ، از عصر تا شب توي دست شويي عق مي زنه و غذاهاي خوشمزه اي رو كه زهره براش پخته بالا مي ياره و دست شويي شب هم هم گوشه ي تخت دو نفره ي قشنگي كه زهره خريده مچاله مي شه و تا صبح ناله مي كنه. \r\nآهي كشيد و گفت: \r\n\" بي چاره زهره، بي چاره مهدي \"\r\nپسرك دستش را دور گردن پروانه حلقه كرد:  \r\n\" مامان \"\r\n\" جان \"\r\nلبان سرخش را جمع كرد و به جايي بالاي سر مادرش خيره شد:  \r\n بابا بايد همه ي دشمنا رو مي كشت و عمو يحيي رو آزاد مي كرد . من اگه جاي عمو يحيي بودم تفنگ رو برمي داشتم و همه شونو مي كشتم و فرارمي كردم.\r\nو همان طور از هيجان جستي زد و دوباره خودش را توي دامن مادرش رها كرد. پروانه او را به خود چسباند: \r\nقربون پسر شجاعم برم \" صورتش را توي موهاي نرم پسرك فرو برد . \" تو كجا اين چيزا رو مي دوني مادر ... ما كجا مي دونيم به اون چي گذشته... \r\nپيچ با يك تكه چوب و جيرنگي روي زمين افتاد . در آرام باز شد و پشت در زهره را ديد، دست يحيي را گرفته بود . لب هاي بي رنگ يحيي به او لبخند زد.\r\n"},{"id":1207,"category_id":9,"category_code":"s9","source_id":44,"title":"دشت شقایق","content":"در یکی از عملیات‌های نامنظم در شبی مهتابی وقتی با همرزمانش در حال طی مسیر برای شبیخون زدن به متجاوزین بعثی بودند، ایشان یک لحظه می‌ایستد و به همراهانشان می‌گوید به زیر پاهای خود بنگرید، می‌بینند زیر پایشان پر از گل‌های شقایق است و به همین خاطر آن دشت را دور می‌زنند و سپس اقدام به عملیات می‌کنند. در حالی که یاران ایشان می‌گفتند بعد از عملیات عراقی‌ها آنجا را با تیربار و خمپاره شخم خواهند زد، ولی او گفت ما آنها را زیر پا له نخواهیم کرد. وقتی این جریان به استحضار امام می‌رسد امام می‌گوید: من چمران را دوست داشتم ولی الان بیشتر دوست دارم."},{"id":1208,"category_id":9,"category_code":"s9","source_id":45,"title":"جهان شیر","content":"مرتضي گفت: «جهان‌شير! تعدادي رو با خودت ببر ميدان فرمانداري، دشمن نفوذ كرده تو شهر!»ـ عمو مرتضي، به منطقه آشنا نيستيم!ـ يه راهنماي بومي باهاتون مي‌آد!جهان‌شير نيمي از افراد دسته‌اش را برداشت و پشت سر راهنما حركت كرد. از قسمت پُل نو عبور كردند و وارد ساختمان‌هاي درهم كوبيده فياضيه شدند. نگاه جهان شير رفت به دود غليظ پالايشگاه آبادان كه روي شهر چتر انداخته بود! همه گروه جوان و كم‌تجربه بودند و شوق داشتند تا زودتر توي خط جبهه مستقر بشوند و با دشمن متجاوز بجنگند. يكي دو خيابان بعد راهنما ايستاد.ـ كا! اينم فرمانداري كـ...تا آمد بقيه‌ حرفش را بزند، توپ و خمپاره مجال نداد و روي سرشان فرو ريخت. دود و خاك فضا را پُر كرد. آتش كه سبك شد، راهنما تركش خورده، روي زمين افتاده بود. جهان شيركسي را مأمور كرد تا راهنما را به عقب منتقل كند. تا اين جا دور كه شدند از همه طرف ما را زير آتش گرفتند. زمين‌گير شديم. بايد به عنوان فرمانده كاري مي‌كردم. چشمم به ديواره‌ سيماني افتاد كه به نظر خط دفاعي مناسبي بود، داد زدم: ـ‌ موضع بگيريد ديوار سيماني! آتيش كنيد طرفشون! از پشت ديواره‌ي سيماني به سمت دشمن آتش ريختيم. چهار چشمي مراقب جلو بوديم و با كوچك‌ترين آتشي پاسخ مي‌داديم. تا شب دو ـ سه زخمي روي دستمان ماند. شب كمي آرامش برقرار شد. جاي وضو تيمم كرديم و نماز خوانديم. با سرنيزه كنسرو لوبيا باز كرديم و با نان كارتوني خورديم. تا صبح چهار چشمي مراقب جلو بوديم و خواب به چشممان نرفت.صبح دوباره به طرف ما تيراندازي شد. هم بي‌تجربه بودم و هم گيچ و منگ! شناختي از موقعيت دشمن نداشتم و منتظر بودم تا كسي از راه برسد و ما توجيح كند. فكرم از زور آتش مقابل كار نمي‌كرد. به زمين چسبيده بوديم و جرات بالا آوردن سر را هم نداشتيم. مهمات هم داشت ته مي‌كشيد. حدود ساعت ده صبح راهنمايي كه ديروز زخمي شده بود، زير آتش دو طرف خودش را رساند به ما. از خوشحالي انگار دنيا را به ما داده بودند. حال كساني را داشتيم كه از جنگل انبوه و بي‌انتهايي نجات پيدا كرده باشند. راهنما جلو آمد. نگاهي به ديوار سيماني كرد و نگاهي به من، گفت:ـ اين‌جا موضع گرفتيد؟ ـ‌ بله ـ تير هم انداختيد؟ ـ‌ تا دلت بخواد، مهماتمون ته كشيده. ـ دشمن رو هم ديديد؟ ـ‌ مرد حسابي ما خودمون رو هم زوركي مي‌بينيم چه برسه به دشمن!ـ‌ بارك‌الله! آفرين!به نظرم، چشم بسته دست به كار بزرگي زده بوديم. خودم را جمع و جور كردم. ايستادم مقابلش. سينه‌ صاف كردم و گفتم:ـ چي شده؟ خنديد و گفت:ـ شما ديروز تا حالا، رو به ميهن، پشت به دشمن، بچه‌هاي خودمون رو زير آتيش گرفتيد! قربنتون بشم، دشمن پشت سرتونه. همراه من بيايد! راه كه افتاد، ادامه داد: ـ‌ بچه‌ها ديروز گفتن عراقيا دارن بدجوري دفاع مي‌كن، نگو اينا بودن! "},{"id":1209,"category_id":9,"category_code":"s9","source_id":46,"title":"آش فروش!","content":"پشت دیوار خانه ی مخروبه‌ای به عربی نوشته بود: «عاش الصدام.» یک‌دفعه راننده زد روی ترمز و گفت: پس این مرتیکه آش فروشه! آن وقت به ما می‌گویند جانی و خائن و متجاوزه!"},{"id":1210,"category_id":9,"category_code":"s9","source_id":47,"title":"دشت","content":"دشت\r\n\r\nشب . توی سنگر نشسته بودیم و چرت می زدیم . آن شب ، مهتاب عجیبی بود . فرمانده آمد داخل سنگر . گفت : این قدر چرت نزنید تنبل می شوید . به جای این کار بروید اول خط، یک سری به بچه های بسیجی بزنید .\r\n\r\nنمی توانستیم دستور را اطاعت نکنیم . بلند شدیم و رفتیم به طرف خاک ریزهای بلندی که در خط مقدم بود . بچه های بسیجی ابتکار خوبی به خرج داده بودند. آنها مقدار زیادی سنگ و کلوخ به اندازه ی کله آدمیزاد روی خاک ریز گذاشته بودند که وقتی کسی سرش را از خاک ریز بالا می آورد، بعثی ها آن را با سنگ و کلوخ اشتباه بگیرند و آنها را نزنند !\r\n\r\nمهتاب از آن طرف افتاده بود و ما، بی خبر از همه جا بر عکس، خیال می کردیم که اینها همه کله ی رزمنده هاست که پشت خاک ریز کمین کرده اند و کله هایشان پیداست . یک ساعت تمام با سنگ ها و کلوخ ها سلام و علیک و احوالپرسی کردیم و به آنها حسابی خسته نباشید گفتیم و بر گشتیم ! صبح وقتی بچه ها متوجه ماجرا شدند تا چند روز، نقل مجلس آنها شده بودیم . هی ماجرا را برای هم تعریف می کردند و می خندیدند !\r\n"},{"id":1211,"category_id":9,"category_code":"s9","source_id":48,"title":"تانک ","content":"یکی فریاد زد : آنجا را نگاه کنید ... !\r\n\r\nیکدفعه دیدیم یک تانک عراقی از دور چرخید و دور زد و یک راست آمد طرف ما . هر کسی به سویی دوید . آماده شدیم که تانک را بزنیم .\r\n\r\nتانک، وقتی که به نزدیک رسید، ناگهان ایستاد . دریچه بالایی اش آرام باز شد . فکر کردیم راننده اش می خواهد تسلیم شود . همه، اسلحه ها را آماده کردیم .\r\n\r\nاحمد، از بچه های نترس و شجاع ما بود . سرش را از داخل تانک بیرون آورد، می خندید. \r\n\r\nداد زدم : احمد !\r\n\r\nگفت : نترسید، اون پشت بود . بعثی ها ولش کرده بودند به امان خدا ! من هم اون قدر باهاش ور رفتم تا روشن شد و آوردمش اینجا . حتماً به دردمان می خورد !\r\n"},{"id":1212,"category_id":9,"category_code":"s9","source_id":49,"title":"النظافة من الایمان :","content":"بیچاره پیرمرد تازه ‌وارد بود. می‌دانست بچه‌ها برای هر کاری آیه یا حدیثی می‌خوانند. وقتی داشت غذا تقسیم می‌کرد، گفت: «بچه‌ها من معنی عربیش را بلد نیستم، اما خود قرآن می‌گوید: «النظافة من الایمان» یعنی هیچ‌کس بیشتر از سهم خودش ورنداره! بچه‌ها با هم زدند زیر خنده، پیردمرد گفت: «مگه غلط خواندم» یکی از بچه‌ها گفت: «نه پدرجان کاملاً درست است، النظافة من الایمان. یعنی «هرکس سهم خودش را فقط بگیرد» و باز خنده‌ی بچه‌ها بود که مثل توپ در فضای چادر می‌ترکید."},{"id":1213,"category_id":9,"category_code":"s9","source_id":50,"title":"شفاعت یادت نره ","content":"مثلا آموزش آبی خاکی می دیدیم. یکبار آمدیم بلایی را که دیگران سر ما آورده بودند سر بچه ها بیاوریم ولی نشد. فکر می کردم لابد همین که خودم را مثل آن بنده خدا زدم به مردن و غرق شدن، از چپ و راست وارد و ناوارد می ریزند توی آب با عجله و التهاب من را می کشند بیرون و کلی تر و خشکم می کنند و بعد می فهمند که با همه زرنگی کلاه سرشان رفته است. کلاه سرشان این بود که در یک نقطه ای از سد بنا کردم الکی زیر آب رفتن. بالا آمدن. دستم را به علامت کمک بالا بردن. و خلاصه نقش بازی کردن. نخیر هیچکس گوشش بدهکار نیست. جز یکی دو نفر که نزدیکم بودند. آنها هم مرا که با این وضع دیدند، شروع کردند دست تکان دادن: خداحافظ! اخوی اگه شهید شدی شفاعت یادت نره!"},{"id":1214,"category_id":9,"category_code":"s9","source_id":51,"title":"احساسات در جبهه‏","content":"شهادت رزمنده‏ها در جنگ هميشه به دلیل قدرت و توانمندي دشمن نبود. خیلی وقتها نپختگي و عدم تجربه يا احساساتي شدن نيروهاي خودي باعث مي‏شد که يكي از نيروهاي خوب از دست برود و خانواده‏اي را داغدار كند. به هر حال چون تجربه جنگ نداشتيم و از بسياري از فنون و تاكتيك‏هاي نظامي بي‏اطلاع بوديم گاهي احساساتي مي‏شديم.\r\nبه ياد دارم در نبرد شكنندة بازي دراز كه به دشمن حمله كرديم و ‏زمين گير شديم و هيچ پيشرفتي نداشتيم، يكی از طلبه‏هاي رزمنده در پشت خاكريزهاي خودمان احساساتي و نيمه موجي شده بود. نارنجك تفنگي را بر سر اسلحه‏اش گذاشت و خواست به طرف دشمن ‏كه چند كيلومتری ما بود، شليك كند، امّا از آن جا كه نارنجك تفنگي صد و پنجاه متر بيشتر نمي‏رفت، آن نارنجك در پشت تپّه به شهيد مجتبي كاظمي اصابت کرد و او را به شهادت رساند. به بالين او كه رسيدم دیدم همه با تعجب به وی نگاه مي كردند؛ چون توپ ‏و خمپاره يا تانك دشمن به آن قسمت نمي‏توانست راه يابد. من هم چيزي از آنچه ديده بودم به زبان نياوردم؛ چون اولا يقيين و اثباتش مشكل بود، ثانيا نيرو يا نيروهای ديگر از دستمان مي‏رفت. ولي پيوسته اين غصّه در دلم ماند كه طلبه بسيار خوبي به دلیل احساسي شدن و موجي شدن طلبه ديگري، از دستمان رفت.\r\n"},{"id":1215,"category_id":9,"category_code":"s9","source_id":52,"title":"عبور از ميدان مين و تأثير آيه \"وَ جَعَلْنا\"","content":"معمولا در جبهه گروههايي را به عنوان گشتي يا گشت شناسايي به قسمت‏هايي كه دست دشمن است، مي‏فرستند. يك روز من و يكي دو تن از دوستان براي شناسايي به روستاي داربلوط رفتيم. براي برگشتن، دو راه بود؛ يكي از كنار رودخانه كه مارپيچ بود و چند ساعت طول مي‏كشيد و ديگري از دشت كه چند ساعت نزديكتر بود، اما در ديد دشمن بود و خطر گم شدن هم وجود داشت. من چون خسته بودم، تصميم گرفتم از وسط دشت بيايم. شروع به دويدن كردم. البته گاهي مجبور مي‏شدم كمرم را خم كنم تا دوربين‏دار مستقر بر ارتفاع 1150 من را نبيند. مدام آية «وجعلنا» را مي‏خواندم تا از گزند دشمن مصون باشم. رسيدم به زميني كه در آن «مين» كار گذاشته بودند و با سيم آنها را به هم متصل كرده بودند. من تا آن زمان، انواع مختلفی از مين ضد نفر و ضد تانك ديده بودم، اما اينها مثل آنچه که قبلا ديده بودم، نبود. گمان كردم زمين كشاورزي است و مالك آن حدود، زمين را اين گونه مشخص كرده. با خود گفتم از روي آنها مي‏روم فقط دقت مي‏كنم كه پا روي سيمها نگذارم تا ضربه‏اي به كشاورز بيچاره وارد نیاید. همان طوري كه مي‏دويدم از زمين پر از مين هم عبور كردم. وقتي به مقر رسيدم و آن مكان را براي دوستانم توضيح دادم، آنان گفتند كه تو از وسط ميدان مين رد شدی. با تعجب به آنها نگاه كردم و از اين كه آية «وجعلنا» من را هم از دشمن و هم از ميدان مين نجات داد، خداوند را شكرگزاري‏كردم."},{"id":1216,"category_id":9,"category_code":"s9","source_id":53,"title":"تعهّد براي آوردن جنازه يكديگر","content":"در جبهه دو نفر بودند که با هم دوست شدند. از آنجا که يكي از آنها جوان خوش سيمايي به نام شرفي بود و ديگري رزمنده‏اي بود كه چهرة زيبايي نداشت، اين مايه تعجب رزمنده‏ها شده بود. اين دو با هم عهد كردند كه هر كدام شهيد شد، ديگري پيكرش را بياورد. شرفي به شهادت رسيد و آن رزمندة ديگر با تمام سختي‏ها و خطراتي كه داشت پيكر او را به پشت خط مقدم رساند."},{"id":1217,"category_id":9,"category_code":"s9","source_id":54,"title":"مَرْدِه خداحافظ","content":"طلبة ساده و كشاورززاده‏اي به نام يداللّه ديده‏بان بود. او از خانوادة بسيار ساده و فقيري بود، امّا سرشار از معرفت و محبت. تكيه‏كلام او هميشه «مَرْدِه» بود. سلام مَرْدِه چطوری مَرْدِه؟ در حوزه نیز به هر طلبه‏اي مي‏رسيد، مي‏گفت: مرده\r\nقبل از رفتن به خط آتش مستقيم، در جبهه متداول بود كه رزمندگان با هم خداحافظي مي‏كردند و حلاليت مي‏طلبيدند؛ چون احتمال شهادت، زياد بود.\r\nقبل از خط آتش مستقيم در خط مقدم روي زمين دراز كشيده بودم. آقاي ديده‏بان كنارم آمد و گفت: خداحافظ مَرْدِه. من هم همان طور كه دراز كشيده بودم از روي شوخي گفتم اگر مُرْدي التماس دعا. او رفت و همان روز شهيد شد.\r\nاين خاطره جبهه هميشه براي من رنج‏آور است. با خود مي‏گويم اي كاش حداقل ايستاده بودم و با او خداحافظي كرده بودم.\r\n"},{"id":1218,"category_id":9,"category_code":"s9","source_id":55,"title":"اسارت","content":"یکی از کارهایم توی جبهه، خنداندن بچه ها بود.\r\n ادای پیرمردها را درمی آوردم، تقلید صدا می کردم، بدم نمی آمد اسیر شوم. فکر می کردم اسارت یک جور زندان در بسته است.\r\nگفتم برم بچه ها را بخندانم تا اسارت بگذرد.\r\n وقتی دست هایم را بردم بالا، گفتم «الحمدلله رب العالمین» به چیزی که می خواستم رسیدم.\r\nتا دم آخر هم بچه ها را می خنداندم.\r\n"},{"id":1219,"category_id":9,"category_code":"s9","source_id":56,"title":"مسلمان","content":"تا نماز ظهرم را بخوانم، هفت هشت بار خوابم برد.\r\nضعف کرده بودم. بدنم پر از تیر و ترکش بود.\r\n به نماز عصر نرسیده، گرفتندم.\r\n توی سنگرهای انفرادی خودشان کارت بسیج و پلاکم را قایم کرده بودم لای دیوار سنگر.\r\nگفت: «سربازی یا پاسدار؟»\r\nگفتم : «سرباز.»\r\nگفت : «چرا حمله کردید؟»\r\nگفتم : «ما هم عین شما دستور رو اجرا کردیم.»\r\nگفت : «قراره باز هم عملیات بشه؟ »\r\nگفتم : «حتماً»\r\nگفت : « چرا به شما دستور داده اند اسرا را بکُشید؟»\r\nگفتم : «نه، همچین حرفی نیست! اون ها وضعشون از ما هم بهتره.»\r\nقرآنش رادرآورد و گفت «ما مسلمونیم. شما چرا با ما جنگ می کنید؟»\r\nقرآن را از دستش گرفتم و گفتم «خب ما هم مسلمونیم. ما هم به قرآن اعتقاد داریم . شما می گید فارس ها مجوسن، شما می گید ما نامسلمونیم»\r\n"},{"id":1220,"category_id":9,"category_code":"s9","source_id":57,"title":"چفیه","content":"پایم تیر خورده بود.\r\n خون توی پوتینم جمع شده بود و سنگینی می کرد.\r\nلنگه ی پوتین را در آوردم. چفیه ام را بستم روی زخم.\r\n آمدند پایم را پانسمان کنند. چفیه ام را که پاره می کردند، انگار قلب مرا تکه تکه می کردند.\r\nدلم می خواست داد می زدم\r\n«بی عرضه ها چفیه ام رو نبرید».\r\n"},{"id":1221,"category_id":9,"category_code":"s9","source_id":58,"title":"آنها می دوختند...","content":"جای ترکش ها توی بدنم دهان باز کرده بود و چرک و خون ازش می ریخت بیرون.\r\n پرستارها و دکترها می آمدند نگاهی می کردند و می رفتند.\r\nانگار نه انگار.\r\n آخر یک دکتر آمد و دستور داد زخم هایم را بخیه بزنند.\r\n نه بی حس کردند، نه چیزی.\r\nمن« یا زهرا» می گفتم و آنها می دوختندم.\r\n"},{"id":1222,"category_id":9,"category_code":"s9","source_id":59,"title":"حلالیت","content":"اول های اسارت ، شب ها می آمدند در آسایشگاه را باز می کردند و ردیفمان می کردند توی محوطه، از هم حلالیت می گرفتیم .\r\n می گفتیم می خواهند اعداممان کنند.\r\n یک ربع، بیست دقیقه که می گذشت ، برمان می گرداندند داخل.\r\n"},{"id":1223,"category_id":9,"category_code":"s9","source_id":60,"title":"تونل وحشت","content":"ما بهش می گفتیم « تونل وحشت»\r\nخودشان می گفتند« یوم القیامه»\r\nیک ردیف راست، یک ردیف چپ ، می ایستادند  کابل به دست.\r\n باید از بینشان می گذشتیم. سر و صورتمان را با دست می گرفتیم و می رفتیم. کمی که گذشت، فهمیدیم اگر فقط از یک طرف برویم ، راست یا چپ، کم تر کتک می خوریم.\r\nاین طوری اگر آن طرفی می خواست بزند این طرف، می خورد توی سرو صورت رفقای خودش.\r\n"},{"id":1224,"category_id":9,"category_code":"s9","source_id":61,"title":"نماز جماعت","content":"همه را زدند. حتی بچه های آسایشگاه اطفال.\r\n می گفتند« چرا نماز جماعت می خونید؟»\r\nما را که زدند، تفرقه افتاد بینمان. یکی می خواند، یکی نمی خواند . اما در آسایشگاه اطفال بعد از این که یکی یکیشان را به فلک بسته بودند و پنجاه نفر که اکثرا مست بودند، با چوب و کابل کتکشان زده بودند، همه شان ایستاده بودند، نماز خوانده بودند،  \r\nآنهم جماعت.\r\n"},{"id":1225,"category_id":9,"category_code":"s9","source_id":62,"title":"پرده ی گوش","content":"چند تا از عراقی ها بودند که عاشق پرده ی گوش بودند.\r\n بچه ها را می بردند توی حمام، می زدند.\r\nدستشان سنگین بود.\r\nآن قدر می زدند که پرده ی گوششان پاره شود.\r\n"},{"id":1226,"category_id":9,"category_code":"s9","source_id":63,"title":"پتوها...","content":"زمستان بود .\r\n آمده بودند آسایشگاه را بگردند .\r\n هفته ای یک بار کارشان همین بود.\r\nوقتی برگشتیم توی آسایشگاه مثل همیشه همه چیز به هم ریخته بود.\r\n اما این بار پتوها را هم خیس کرده بودند،     آب ریخته بودند رویشان.\r\n"},{"id":1227,"category_id":9,"category_code":"s9","source_id":64,"title":"دزدها","content":"آمدند اسمم را صدا زدند و فرستادنم انفرادی. می گفتند گفته «ای عراقی ها دزدند»\r\nانفرادی تنبیه زیاد داشت . فلک می کردند. می بستند به پنکه، توی کیسه می کردند و می زدند.\r\n دو ساعت به دو ساعت هم که نگه بان عوض می شد، باز همه ی این ها. باید یک هفته آن تو می ماندم.\r\n روز چهارم امانم برید. از حضرت زهرا خواستم بیاوردم بیرون. کمی بعد آمدند و در سلول را باز کردند.\r\n"},{"id":1228,"category_id":9,"category_code":"s9","source_id":65,"title":"دمپایی","content":"دم پایی هایمان را می زدیم زیر بغل مان و دور میدان وسط اردوگاه راه می رفتیم، پا برهنه. \r\n کف پایمان پینه بسته بود.\r\n این طوری می کردیم که هروقت با کابل زدندمان، کم تر اذیت شویم.\r\n"},{"id":1229,"category_id":9,"category_code":"s9","source_id":66,"title":"صلیب سرخ","content":"مطب دکتر برای نشان دادن به صلیب سرخی ها بود.\r\nسهمیه ی دارو هم داشت ؛ ولی چیزیش به ما نمی رسید. همه اش را خودشان بر می داشتند.\r\n از ما هر کسی می رفت جلوی مطب ، چند تا کپسول اسهال بهش می دادند .\r\nفرق نمی کرد چه ش باشد. کپسول ها را باز می کردیم، می دیدیم توی بعضیشان تاید ریخته اند.\r\n"},{"id":1230,"category_id":9,"category_code":"s9","source_id":67,"title":"نهج البلاغه","content":"توی اردوگاه هر اتاقی یک قرآن داشت.\r\n نفهمیدیم چی شد که یک نهج البلاغه بین قرآن ها پیدا شد. گفتیم می آیند و می برندش. قرار بر این شد که حفظش کنیم.\r\nورق ورقش  کردیم و پخشش کردیم بین بچه ها. به هر نقر چهار پنج خط می رسید که حفظ کند . سهم من چند خط از صفحه ی دویست و پنجاه و چهار بود. یک شب تا صبح توانستیم هرچه حفظ کرده بودیم را بنویسیم.\r\n روی کاغذهایی که از مقوای تاید درست کرده بودیم. بعدها هر کس صفحه ی خودش را به دیگران یاد داد. چند نفر حافظ نهج البلاغه شدند.\r\n"},{"id":1231,"category_id":9,"category_code":"s9","source_id":68,"title":"دعا","content":"نمی گذاشتند دعا بخوانیم ، به خصوص شب های  جمعه بیش تر مراقبمان بودند.\r\n یکی با آیینه عراقی ها را می پایید و بقیه رو به قبله دعا می خواندند.\r\nوضعیت که قرمز می شد، یکی می خوابید، یکی راه می رفت، یکی می گفت «آخرین نفر توالت کیه؟»\r\nگاهی می شد وسط دعای کمیل چندین بار وضعیت قرمز می زدیم.\r\n"},{"id":1232,"category_id":9,"category_code":"s9","source_id":69,"title":"حسین جان","content":"داشت می گفت« حسین جان چه کنیم که این جا نمی تونیم برات عزاداری کنیم ؟ توی زندونیم. دست کفریم»\r\nاین را که گفت، زانوهایش را گرفت توی بغل و سرش را گذاشت روش.\r\n شروع کرد نوحه خواندن، آهسته. می خواند و گریه می کرد. گریه ام گرفت.\r\n با هم گریه می کردیم.\r\n او سنی بود. من شیعه.\r\n"},{"id":1233,"category_id":9,"category_code":"s9","source_id":70,"title":"عزاداری","content":"عزاداری ممنوع بود، به خصوص توی محرم، اما ما انگار نه انگار. عزاداریمان را می کردیم. یکی می خواند، بقیه سینه می زدند. چنان سینه می زدند که ساختمان اردوگاه می لرزید.\r\nآماده باش می دادند.\r\nمی ریختند پشت در آسایشگاه . می آمدند آن جا آسایشگاه ما را ساکت کنند؛ آسایشگاه دیگر شروع می کرد.\r\n می رفتند سراغ آن یکی ، باز یکی دیگر. نمی توانستند کاری بکنند. بچه ها هم کار خودشان را می کردند.\r\n"},{"id":1234,"category_id":9,"category_code":"s9","source_id":71,"title":"شپش","content":"تنمان می خارید. به خاطر شپش بود. فکر می کردیم اگر در بزنیم و بگوییم، می آیند سلول را ضد عفونی می کنند. در زدیم، نگهبان آمد. عربی که بلد نبودیم.\r\nگفتیم« جانور، حیوان.»\r\nگفت:« کو؟»\r\nگذاشتیم کف دستش. گفت« کمه. کمه.»\r\nغش غش خندید و رفت.\r\n"},{"id":1235,"category_id":9,"category_code":"s9","source_id":72,"title":"آزادی","content":"می آمدم توی محله. خیابان، کوچه، خانه. می گفتم« دارم خواب می بینم؟»\r\nمی گفتند « نه بابا! تو آزادی. ببین این خونتونه، این خیابونتونه، این کوچه تونه.»\r\nمی گفتم« خب اگه من خواب نمی بینم، بذار ببینم ماشین می آد بوق بزنه، من می رم کنار یا نه؟»\r\nعراقی ها که سوت می زدند، می فهمیدم هنوز همان جایم.\r\n"},{"id":1236,"category_id":9,"category_code":"s9","source_id":73,"title":"آش آخر","content":"هر روز صبح موقع تقسیم آش می گفتم« برادرها، بیاید آخرین آشتون رو ببرید.»\r\nمی گفتند « تو هر روز داری همین رو می گی و ما هنوز این جاییم.»\r\nمی گفتم« آقا آخرین آشتونه دیگه، تا فردا از آش خبری نیست.»\r\nآخر یک روز بچه ها گفتند« دیگه این رو نگو. خسته شدیم از بس گفتی.»\r\nهمان موقع بلند گوی اردوگاه اعلام کرد که قرار است بیست و ششم مرداد تعویض اسرا شروع شود. با گریه گفتم« آخرین آشتون رو بخورید که داریم تعویض می شیم.»\r\n"},{"id":1237,"category_id":9,"category_code":"s9","source_id":74,"title":"اردوگاه پنجم","content":"موصل، چهارتا اردوگاه داشت.\r\n پنجمیش قبرستان بود.\r\n از پانصد شهیدی که از آن جا آوردند. پیکر چهارتایشان سالم بود.\r\n نپوسیده بود.\r\n"},{"id":1238,"category_id":9,"category_code":"s9","source_id":75,"title":"به دنبال ما می دوید و از ما پوزش می خواست","content":"یک روز که در کلاس هشتم درس می خواندیم. هنگام عبور از محله «چگینی» که از توابع شهرستان قزوین است، یکی از نوجوانان آنجا بی جهت به ما ناسزا گفت و این باعث شد تا با او گلاویز شویم.\r\n ما با عباس(شهید عباس بابایی) سه نفر بودیم و در برابرمان یک نفر. عباس پیش آمد و برخلاف انتظار ما، که توقع داشتیم او به یاریمان بیاید. سعی کرد تا ما را از یکدیگر جدا کند و به درگیری پایان دهد.\r\n وقتی تلاش خود را بی نتیجه دید، ناگهان قیافه ای بسیار جدی گرفت و در جانبداری از طرف مقابل با ما درگیر شد.\r\nمن و دوستم که از حرکت عباس به خشم آمده بودیم،به درگیری خاتمه دادیم و به نشانه اعتراض، از او قهر کردیم.\r\nسپس بی آنکه به او اعتنا کنیم، راهمان را در پیش گرفتیم، اما او در طول راه به دنبال ما می دوید و فریاد می زد:\r\n-مرا ببخشید آخر شما دو نفر بودید و این انصاف نبود که یک نفر را کتک بزنید.\r\n(پرویز سعیدی)\r\n"},{"id":1239,"category_id":9,"category_code":"s9","source_id":76,"title":"او هیچ وقت پپسی نمی خورد","content":"او هیچ وقت پپسی نمی خورد\r\nدر طول مدتی که من با عباس(شهید عباس بابایی) در آمریکا هم اتاق بودم او همیشه روزانه دو وعده غذا می خورد، صبحانه و شام. هیچ وقت ندیدم که ظهرها ناهار بخورد. من فکر می کنم عباس از این عمل دو هدف را دنبال می کرد. یکی خودسازی و تزکیه نفس و دیگری صرفه جویی در مخارج و فرستادن پول برای دوستانش که بیشتر در جاهای دوردست کشور بودند.\r\nبعضی وقت ها عباس همراه با شام نوشابه می خورد، اما نه نوشابه هایی مثل پپسی و ... که در آن زمان موجود بود ...\r\n چند بار به او گفتم که برای من پپسی بگیرد ولی دوباره می دیدم که فانتا خرید است. یک بار به او اعتراض کردم که چرا پپسی نمی خری؟ مگر چه فرقی می کند و از نظر قیمت که با فانتا تفاوتی ندارد، آرام و متین گفت:\r\n-حالا نمی شود شما فانتا بخورید؟\r\nگفتم : خوب عباس جان آخر برای چه؟\r\nسرانجام با اصرار من آهسته گفت :\r\n-کارخانه پپسی متعلق به اسرائیلی هاست به همین خاطر مراجع تقلید مصرف آن را تحریم کرده اند\r\nبه او خیره شدم و دانستم که او تا چه حد از شعور سیاسی بالایی برخوردار است و دردل به عمق نگرش او به مسایل ، آفرین گفتم.\r\nنکته دیگر این که همه تفریح عباس در آمریکا در سه چیز خلاصه می شد: ورزش، عکاسی و دیدن مناظر طبیعی.\r\nخلبان آزاده تیسمار اکبر صیاد بورانی))\r\n"},{"id":1240,"category_id":9,"category_code":"s9","source_id":77,"title":"خمس مال را داده اید؟","content":"عباس(شهید عباس بابایی) نسبت به احکام شرع بسیار پایبند بود. وقتی به منزل ما می آمد. می پرسید؟\r\n-خمس مالتان را داده اید یا نه؟\r\nو می گفت :\r\n-گرچه من می دانم به شما خمس تعلق نمی گیرد چرا که یک فرش دارید و آن هم مورد استفاده است. برنج و روغن هم از مصرف سالتان کم می آید. ولی با تمام این وجود باید از یک روحانی آگاه بخواهد تا خمس مالتان را حساب کند ممکن است هیچ چیز هم به شما تعلق نگیرد، ولی این وظیفه همه ماست.\r\nاو می گفت:\r\n-چنانچه خمس مالتان را نپردازید مالتان پاک نیست و از نظر شرع هم اشکال داد و از این گذشته مالتان برکت ندارد.\r\n(خانم اقدس بابایی)\r\n"},{"id":1241,"category_id":9,"category_code":"s9","source_id":78,"title":" النگوها را که می دید ناراحت می شد","content":"من معمولا چند النگوی طلا در دست داشتم و عباس(شهید عباس بابایی) هر وقت النگوهای طلا را می دید ناراحت می شد و می گفت:\r\n-ممکن است زنان یا دخترانی باشند که این طلاها را در دست تو ببینند و توان خرید آن را نداشته باشند؛ آنگاه طلاهای تو آنان را به حسرت وامی دارد و در نتیجه تو مرتکب گناه بزرگی می شوی. این کار یعنی فخر فروشی.\r\nمی گفت:\r\n-در جامعه ما فقیر زیاد است؛ مگر حضرت زینب (ع) النگو به دست می کردند و یا... .\r\nحقیقت این است که روحیه زنانه و علاقه ای که به طلا داشتم باعث شده بود نتوانم از آنها دل بکنم؛ تا اینکه یک روز بیمار بودم و النگوها در دستم بود. عباس به عیادتم آمده بود. عباس را که دیدم، دستم را در زیر بالش پنهان کردم تا النگوها را نبیند. او گفت:\r\n-چرا بالش را از زیر سرت برداشته ای و روی دستت گذاشته ای؟\r\nچیزی نگفتم و فقط لبخندی زدم. او بالش رابرداشت و ناگهان متوجه النگوهای من شد و نگاه معنی داری به من کرد. از این که به سفارش او توجهی نکرده بودم، خجالت کشیدم.\r\nبعد از شهادت عباس به یاد گفته های او در آن روزها افتادم و تمام طلاهایم را به رزمندگان اسلام هدیه کردم.\r\n\r\n(خانم زهرا بابایی)\r\n"},{"id":1242,"category_id":9,"category_code":"s9","source_id":79,"title":"رعایت حق بیت المال","content":"حضرت آیت ا... شهید صدوقی یک دستگاه پیکان به شهید بابایی اهدا کرده بودند؛ ولی ایشان آن خودرو را متعلق به خود نمی دانشت و با آن کارهای اداری انجام می داد.\r\nروزی جهت انجام کاری اضطراری ماشین را به امانت گرفتم و به منزل پدرم در اصفهان رفتم. ماشین را جلو خانه پارک کردم. ساعتی بعد وقتی خواستم حرکت کنم، متوجه شدم که قفل صندق عقب ماشین شکسته و در آن بازاست. در را بالا زدم. زاپاس،آچار چرخ و جک به سرقت رفته بود.\r\n از اینکه ماشین امانتی بود خیلی ناراحت شدم. آمدم و جریان را برای عباس (شهید عباس بابایی)توضیح دادم. پیش خود فکر کردم. با رابطه رفاقتی که بین من و او وجود دارد، او خواهد گفت که اشکال ندارد و برو یک زاپاس و جک از انبار بگیر؛ ولی بر خلاف آنچه که من تصور می کردم او گفت:\r\n-خوب حالا چیزی نیست. برو یک زاپاس و یک جک بخر و سرجایش بگذار.\r\nاول فکر کردم شوخی می کند؛ ولی آقای صادقی که بیشتر از من با خصوصیات اخلاقی او آشنا بود گفت:\r\n-او جدی می گوید. برو تهیه کن. چون تو از ماشین بیت المال به درستی حفاظت نکرده ای.\r\nحقوق ماهیانه من در آن زمان سه هزار و دویست تومان بود و اگر می خواستم فقط یک زاپاس بخرم می بایستی حدود دو هزار تومان پول می پرداختم. سرانجام با هر زحمتی که بود آنها را تهیه کردم.\r\nآن روز و درآن شرایط از برخورد خشک شهید بابایی ناراحت شدم؛ ولی قدری که اندیشیدم؛ بر بزرگی و تقوای او آفرین گفتم: چرا که حاضر نشد حتی در مورد دوست صمیمی اش هم از اموال بیت المال کمترین گذشتی را بنماید.\r\n(کمال میرمجربیان)\r\n"},{"id":1243,"category_id":9,"category_code":"s9","source_id":80,"title":"به اشتباه خود معترفم","content":"برابر مقررات فنی نیروی هوایی، خلبانان می باید هر ساله مورد معاینات پزشکی قرار بگیرند و از نظر توان مهارتهای پروازی، همراه با یک استاد خلبان، پرواز کنند و چنانچه در این دو مورد قبول شدند، مجاز خواهند بود به پرواز خود ادامه بدهند.\r\n مسئولیت کنترل این موضوع با «افسر امنیت پرواز» است.\r\nیک سال، شهید بابایی که فرماندهی پایگاه را نیز به عهده داشت، به علت مشکلات کاری، موفق به انجام معاینات سالانه نشده بود؛ به همین خاطر در یکی از پروازهایی که داشتند، سروان عقبائی، که افسر امنیت پرواز بودند، لیست پروازی را چک می کنند و متوجه می شوند که سرهنگ بابایی معاینات لازم را انجام نداده اند؛ به همین خاطر به ایشان می گویند:\r\n-پرواز شما خارج از مقررات بوده است.\r\nشهید بابایی با کمال شجاعت به اشتباه خود اعتراف می کند و می گوید:\r\n-بنده برای هرگونه تنبیهی که شما بگوئید آماده هستم؛ و چناچه برگه بازداشت و یا هر تنبیه دیگری را بنویسید من خودم آن را امضا می کنم.\r\n(تیمسار محمد پیراسته)\r\n"},{"id":1244,"category_id":9,"category_code":"s9","source_id":81,"title":"یک نوع خورشت","content":"شبی از شبهای ماه مبارک رمضان، سرهنگ بابایی، همراه با خانواده در منزل ما بودند.\r\nهنگام افطار در سفره، خرما، الویه و خورشت قیمه بود. ایشان به بنده اعتراض کردند و گفتند:\r\n-آقای رحیمی! شما که الویه درست کرده اید دیگر چه نیازی به خورشت بود؟\r\nآنگاه با ذکر حدیثی تذکر دادند که یک نوع خورشت بیشتر سر سفره نباشد.\r\n(ستوان محمد علی رجبی)\r\n"},{"id":1245,"category_id":9,"category_code":"s9","source_id":82,"title":"او دیگر دعا نخواند","content":"حدود سالهای 61و62، زمانی که شهید بابایی فرمانده پایگاه اصفهان بود، یکی از پرسنل نقل کرد:\r\nدر شب جمعه ای به طور اتفاقی به مسجد حسین آباد اصفهان رفتم. در تاریکی متوجه شدم صدایی که از بلندگو به گوش می آید خیلی آشناست.\r\n پس از پایان دعا که چراغها روشن شد، دیدم که حدسم درست بوده. کسی که دعای کمیل می خوانده است سرهنگ بابایی است. خوشحال شدم و جلو رفتم. سلام کردم و گفتم:\r\n-جناب سرهنگ! قبول باشد ان شاءالله.\r\nاطرافیان با شنیدن کلمه«سرهنگ»، به شهید بابایی نگاه کردند. بعد از احوالپرسی که با هم کردیم، از چهره او دریافتم که ناراحت است. وقتی علت را جویا شدم، پاسخ دادند:\r\n-کاش واژه سرهنگ را نمی گفتی.\r\nفهمیدم که تا آن لحظه کسی از اهالی آن منطقه شهید بابایی را نمی شناخته و ایشان هرشب جمعه به عنوان شخص عادی به آن مسجد می رفته و دعای کمیل می خوانده است.\r\nپس از این ماجرا او دیگر در آن مسجد دعای کمیل نخواند: زیرا همیشه دوست می داشت تا ناشناس بماند.\r\n(ستوان موسی صادقی)\r\n"},{"id":1246,"category_id":9,"category_code":"s9","source_id":83,"title":"لباس ساده","content":"از زمان دانشجویی نوع لباس پوشیدن عباس، که همیشه ساده و بی پیرایه بود، برای من شگفتی داشت و همواره در جست و جوی پاسخی مناسب برای آن بودم.\r\nروزی به همراه عباس در جلو گردان پروازی قدم میزدیم. پس از صحبتهای زیادی که داشتیم در مورد فلسفه پوشیدن لباس ساده و بی پیرایه اش از او سوال کردم. او در حالی که صمیمانه دستش را روی شانه ام گذاشته بود گفت:\r\n-هیچ دلم نمی خواست راجع به این قضیه صحبت کنم؛ ولی چون اصرار داری تا بدانی؛ برایت می گویم.\r\nپس از مکثی کوتاه گفت:\r\n-انسان باید غرور و منیتهای خود را از میان بردارد و نفسش را تنبیه کند واز هر چیزی که او را به رفاه و آسایش مضر می کشاند و عادت می دهد پرهیز کند، تا نفس او تزکیه و پاک شود. ما نباید فراموش کنیم که هر چه در این دنیا به انسان سخت بگذرد در آن دنیا راحت تر است. دیگر اینکه تزکیه و سرکوبی هوای نفس موجب خواهد شد تا انسان برای کارهای سخت تر و بالاتر آمادگی پیدا کند.\r\n(تیمسار خلبان عباس حزین)\r\n"},{"id":1247,"category_id":9,"category_code":"s9","source_id":84,"title":"یاور درماندگان بود","content":"عباس همیشه در فکر مردم بی بضاعت بود.\r\nدر فصل تابستان به سراغ کشاورزان و باغبانان پیری که ناتوان بودند و وضع مالی خوبی نداشتند می رفت و آنان را در برداشت محصولشان یاری می کرد.\r\n زمستانها وقتی برف می بارید پارویی برمی داشت و پشت بامهای خانه های درماندگان و کسانی را که به هر دلیل توانایی انجام کار نداشتند، پارو می کرد.\r\nبه خاطر دارم مدتی قبل از شهادتش، در حال عبور از خیابان سعدی قزوین بودم که ناگهان عباس را دیدم. او معلولی را که هر دو پا عاجز بود و توان حرکت نداشت، بر دوش گرفته بود و برای اینکه شناخته نشود، پارچه ای نازک بر سر کشیده بود. من او را شناختم و با این گمان که خدای ناکرده برای بستگانش حادثه ای رخ داده است، پیش رفتم. سلام کردم و با شگفتی پرسیدم:\r\n-چه اتفاقی افتاده عباس؟ به کجا می روی؟\r\nاو که با دیدن من غافلگیر شده بود، اندکی ایستاد و گفت:\r\n-پیرمرد را برای استحمام به گرمابه می برم. او کسی را ندارد و مدتی است که به حمام نرفته.\r\nبا دیدن این صحنه، تکانی خوردم و در دل روح بلند او را تحسین کردم.\r\n(میرزا کرم زمانی)\r\n"},{"id":1248,"category_id":9,"category_code":"s9","source_id":85,"title":"آیا به عباس الهام می شد؟","content":"سرهنگ خلبان حق شناس، نماینده نیروی هوایی در قرارگاه هویزه بودند. من به همراه سرهنگ بابایی که در آن زمان پست معاونت عملیات را به عهده داشتند. برای تحویل پست سرهنگ حق شناس به قرارگاه رفته بودیم. در برخوردهای گذشته، برخورد جناب حق شناس با عباس زیاد  دوستانه به نظر نمی رسید، ولی در آن روز ایشان خیلی گرم و صمیمانه با عباس برخورد کردند اورا در آغوش گرفت و بوسیدند. حق شناس گفت:\r\nجناب بابایی ! من نمی دانم چرا اینقدر شما را دوست دارم\r\n عباس هم گفت:\r\n-خدا را شکر . ما فکر می کردیم شما از ما ناراحت هستید ولی خدا شاهد است که من هم شما را دوست دارم.\r\nجناب حق شناس پس از سفارشات لازم به همراه سرباز راننده خداحافظی کردندو قرارگاه را به مقصد تهران ترک گفتند.\r\nعباس پس از رفتن سرهنگ حق شناس شروع کرد به خواندن قرآن. پانزده الی بیست دقیقه ای نگذشته بود که بی اختیار روی به من کرد و گفت:\r\n-خداوند او را بیامرزد . خدا رحمتش کند.\r\nگفتم : که را می گویی ؟\r\nیکباره به خود آمد و گفت :\r\nهمین طوری گفتم\r\nلحظه ای بعد باز زیر لب گفت :\r\nخدا رحمتش کند.\r\nسپس چهره اش در هم کشیده شد و غمگین و ناراحت به نظر می رسید.  علتش را از او پرسیدم؛ ولی چیزی نگفت.\r\nده دقیقه ای گذشت ناگهان خبر آوردند، سرهنگ حق شناس در جاده با تریلی تصادف کرده و به شهادت رسیده است. بی درنگ سوار ماشین شدیم و به محل حادثه رفتیم . هنگام برگشت ، عباس سرش را به شیشه ماشین چسبانده بود و به یاد شهید حق شناس قرآن می خواند و می گریست.\r\n(ستوان حسن دوشن)\r\n"},{"id":1249,"category_id":9,"category_code":"s9","source_id":86,"title":"غذای فرمانده","content":"زمانی که در قرارگاه رعد بودیم بنابر ضرورت های پروازی و موقعیت های ویژه جنگی تیمسار بابایی دستور دادند تا برای خلبانان شکاری غذای مخصوص پخته شود، ولی خود جناب بابایی با توجه به اینکه بیشترین پروازهای جنگی را انجام می دادند از غذای مخصوص خلبانان استفاده نمی کردند و همان غذای معمولی را می خوردند.\r\n در پاسخ به اعتراض ما در مورد این که گفته بودیم چرا شما از غذای خلبانان استفاده نمی کنید، گفتند :\r\n-یک فرمانده باید حتما از غذایی که همگان استفاده  می کنند بخورد تا آن سربازی که در خط مقدم است نگوید غذای من با فرمانده ام فرق دارد.\r\n«سرهنگ خلیل صراف»\r\n"},{"id":1250,"category_id":9,"category_code":"s9","source_id":87,"title":"دیدار در عرفات","content":"سال 1366 که به مکه مشرف شدم ، عضو کاروانی بودم که قرار بود شهید بابایی هم با آن کاروان اعزام شود. ولی ایشان نیامدند و شنیدم که به همسرشان گفته بودند: بودن من در جبهه ثوابش از حج بیشتر است .\r\nدر صحرای عرفات وقتی روحانی کاروان مشغول خواندن دعای روز عرفه بود و حجاج می گریستند من یک لحظه نگاهم به گوشه سمت راست چادر محل استقرارمان افتاد . ناگهان شهید بابایی را دیدم که با لباس احرام در حال گریستن است.\r\nاز خود پرسیدم که ایشان کی تشریف آوردند؟ کی مُحرم شده و خودشان را به عرفات رسانده اند. در این فکر بودم که نکند اشتباه کرده باشم. خواستم مطمئن شوم. دوباره نگاهم را به همان گوشه چادر انداختم تاایشان را ببینم. ولی این بار جای او را خالی دیدم.\r\nاین موضوع را به هیچ کس نگفتم چون می پنداشتم که اشتباه کرده ام .\r\nوقتی مناسک در عرفات و منا تمام شد و به مکه برگشتیم، از شهادت تیمسار بابایی باخبر شدم در روز سوم شهادت ایشان در کاروان ما مجلس بزرگداشتی برپا شد و در آنجا از زبان روحانی کاروان شنیدم که غیر از من تیمسار دادپی هم بابایی را در مکه دیده بود. همه دریافتیم که رتبه و مقام شهید بابایی باعث شده بود تا خداوند فرشته ای را به شکل آن شهید مامور کند تا به نیابت از او مناسک حج را به جا آورد.\r\n«سرهنگ عبدالمجید طیب »\r\n"},{"id":1251,"category_id":9,"category_code":"s9","source_id":88,"title":"آخوند واقعی","content":"خبر رسید که ضد انقلاب با حمله به روستایی نزدیک سنندج، دکتر جهاد سازندگی را به اسارت برده است.\r\nصبح اول وقت راه افتادیم. مصطفی، عمامه به سر، اما با بند حمایل و یک نوار فشنگ تیر بار دور کمر قوت قلب همه بود.\r\nپیش مرگ های کرد که در کنار ما با دشمن می جنگیدند، چپ چپ به مصطفی نگاه می کردند، باور نمی کردند او اهل رزم و درگیری باشد همان صبح زود، ضد انقلاب دکتر را به شهادت رسانده بود، امادرگیری تاعصر ادامه داشت، وقت برگشتن، پیش مرگ ها تحت تاثیر شجاعت مصطفی، ول کن او نبودند.\r\nیکی از آنها بلند، طوری که همه بشنوند گفت :\r\n- اینو می گن آخوند، اینو می گن آخوند!\r\nمصطفی می خندید. دستی کشید به سبیل های تا بناگوش آن کاک مسلح و گفت :\r\n-  اینو میگن سبیل. اینو می گن سبیل.\r\n"},{"id":1252,"category_id":9,"category_code":"s9","source_id":89,"title":"نفوذ معنوی","content":"بحران کردستان ادامه داشت و اعزام نیروهای داوطلب، به طور معمول 30، 40 نفره بود.\r\n یکی از شب ها که در ستاد مشترک پادگان سنندج جمع بودیم سرهنگ صیاد شیرازی ضن صحبت فهمید که آقا مصطفی در یاسوج و روستاهای آن دارای نفوذ معنوی است، به او گفت:\r\n-خوبه به یاسوج برید، شاید با آوردن نیروهای آن منطقه بتونیم از توان اونها در نبردهای کوهستانی استفاده کنیم.\r\nفردا صبح راه افتاد. با شکل و شمایل طلبگی. همان عمامه ی جمع و جور. قبا و عبای ساده و تر و تمیز.\r\nسه روز بعد برگشت. با یک گردان رزمنده های لر. همه مسلح، همه عاشق انقلاب\r\n"},{"id":1253,"category_id":9,"category_code":"s9","source_id":90,"title":"آب","content":"بچه ها یکی یکی شهید می شدند کار مصطفی شده بود سینه خیز رفتن میان مجروحان. آب می خواستند، آب نبود.\r\nبا یک کلمن آب برگشت میان بچه ها، به شوق آب رساندن.\r\n صدای یاران بلند بود.\r\nیا اباصالح المهدی ادرکنی\r\nآب مانده بود دست مصطفی. همه شهید، همه چاک چاک.\r\nعلی نوری، منصور موحدی، محمود پهلوان نژاد، همه تک تیرانداز، هر کدام برای خود یک گردان، یک لشکر.\r\nساعت 2 بعد از ظهر، اخبار به مردم گفت که عملیات فرمانده ی کل قوا با انهدام نیروهای عراقی در شمال آبادن، موفق بوده است.\r\n مردم خوشحال بودند از این پیروزی.\r\nما گریه می کردیم .\r\nشصت نفر از یاران ما مانده بودند زیر آفتاب داغ داغ.\r\n همه شهید. همه چاک چاک.\r\n"},{"id":1254,"category_id":9,"category_code":"s9","source_id":91,"title":"جبهه ی عجیب و غریب","content":"خبرنگاران خارجی را آورده بودند تا پیروزی ما در شکستن محاصره ی آبادان را ببینند.\r\n صدام گفته بود اگر بخواهند به آبادان بروند باید از او اجازه بگیرند. اما حالا ما سربلند بودیم. درخواست خبرنگاران مصاحبه با فرمانده ی منطقه بود. قبول کردیم و راه افتادیم.\r\nعراقی ها هنوز مقاومت می کردند و صدای بلند و پیوسته ی انفجارها و رگبار مسلسل ها حکایت از جنگی سخت داشت. مصطفی میان بچه ها در حال آرپیجی زدن بود. از پشت خاکریزی که موضع قبلی دشمن بود او را به خبرنگاران نشان دادم. بنده ی خدایی هم ترجمه می کرد.\r\n-  همون که لباس سبز پوشیده، فرمانده عملیاته! با اون مصاحبه کنید. بریم جلو، کنار تانکی که داره می سوزه؟\r\nخارجی ها با تعجب نگاه می کردند. مترجم گفت:\r\n-خبرنگار انگلیسی میگه مردم شما غیر عادی اند. فرماندهان و رزمندگان شما هم غیر عادی اند. همه چیز اینجا عجیب و غریبه!\r\n"},{"id":1255,"category_id":9,"category_code":"s9","source_id":92,"title":"قوت قلب","content":"صبح تا شب در منطقه رملی شمال دشت آزادگان راه رفتیم. هجده کیلومتر.\r\n در تنگه ی صعده، آقا مصطفی دعای کمیل با حالی خواند. ده دوازده نفری می شدیم، بجه ها صفا کردند:\r\n-خدایا ، تو دیدی که راه رفتن تو رمل ها مشکله. ما چطور هفت گردان رو بیاریم پشت سر عراقی ها. تازه خسته و کوفته بزنند به دشمن. تو ارحم الراحمینی. برای تو سفت کردن رمل ها زیر پای بچه ها کار ساده یی ست.\r\n***\r\nدو هفته بعد، یک ساعت قبل از شروع عملیات فتح بستان، باران شدیدی آمدو رمل ها سفت شد. گردان های خط شکن انگار توی هوا راه می رفتند.\r\nمصطفی کنار معبر ایستاده بود و گریه می گرد :\r\n-خدایا، گفتن که تو هر کاری که بخواهی می تونی بکنی...\r\nبچه های گردان امام حسین (علیه السلام) که با کماندوهای عراقی درگیر شدند و شروع به پاکسازی سنگرهای آنها کردند، در آن تاریکی مطلق که دهها شهید و مجروح داده بودیم، صدای مصطفی از بی سیم قوت قلب بود:\r\n-السلام علیک یا ابا عبدا... (علیه السلام)، السلام علیک و رحمه ا... و برکاته.\r\n"},{"id":1256,"category_id":9,"category_code":"s9","source_id":93,"title":"سوال شرعی","content":"در حساس ترین مرحله ی عملیات بیت المقدس که پیشروی برای تصرف خرمشهر ادامه داشت، آمد در عمق جبهه ی شلمچه و در زیر آتش بسیار سنگینی که نفس همه را بریده بود، دوربین کشید و شبکه ی برق منطقه ی عمومی بصره را نشان داد و گفت:\r\n-اگه هدف عملیات، خرمشهر نبود، می تونستیم بصره رو تصرف کنیم.\r\nهمان وقت یک بسیجی آمده بود و می پرسید که با لباس خون آلود می شود نماز خواند یا نه؟ با حوصله جواب او را داد و مقداری هم چرب تر و نرم تر از حد معمول، به او گفتم:\r\n-این بنده ی خدا هم فرصت گیر آورده، عاشق عمامه ی تو شده ، گفت :\r\n-وقتی او سوال شرعی می پرسه، مخصوصا از نماز، من دیگه فرمانده نیستم. این همون چیزیه که من می خوام.\r\n"},{"id":1257,"category_id":9,"category_code":"s9","source_id":94,"title":"اخلاص","content":"بعد از نماز صبح راهی خط دفاعی زید در شمال شلمچه شدیم.\r\nهوا گرگ و میش بود و بیشتر بچه ها که شبِ گرم و پُر پشه یی را گذرانده بودند در پناه نسیم خنک صبح، خواب بودند و فرصت خوبی بود برای کنترل نقاط ضعف خط دفاعی خودی و دشمن.\r\nکارمان که تمام شد مصطفی یک گونی برداشت و شروع به جمع کردن آشغال های پشت خاکریز کرد. به قرارگاه که برمی گشتیم عقب وانت پر بود از قوطی کنسرو و خرت و پرت.\r\n"},{"id":1258,"category_id":9,"category_code":"s9","source_id":95,"title":"تک تیر انداز","content":"پس از عملیات رمضان، از مسئولیت کنار کشید. هر چه اصرار کردند فایده ای نداشت. تصمیم گرفته بود تک تیر اندازي را ادامه دهد.\r\n-برادر عزیز، تو از فرماندهان رده ی اول جنگ هستی. نمی شه تک تیرانداز باشی. همه تو رو می شناسند.\r\nمصطفی تصمیم خود را گرفته بود. می خواست بار دیگر برود وسط بسیجی ها، برود انسان سازی کند. شور و هوای توسل در او تقویت شده بود. ایام محرم هم نزدیک بود و دیگر حال خودش را نمی فهمید. می گفت:\r\n-اگه بگید از خوزستان برو، می رم. ولی از جبهه که نمی تونید منو اخراج کنید. اگه مزاحمم می رم غرب. می رم کردستان.\r\n"},{"id":1259,"category_id":9,"category_code":"s9","source_id":96,"title":"یک بسیجی ساده","content":"حالا برای خودش شده بود یک بسیجی ساده و تک تیرانداز.\r\n حضور در گردان پیاده و آماده شدن برای شرکت در عملیات محرم، آرزویی بود که به آن رسیده بود. شاید این یکی از عجیب و غریب ترین نمادهای دوران دفاع مقدس باشد.\r\nدر شهریور ماه، فرمانده ی سپاه سوم و هدایت پنج لشکر در عملیات رمضان و دو ماه بعد، تک تیر انداز در گران پیاده.\r\nاین چیزی بود که مصطفی از خدا می خواست اما شرایط برای او به گونه ای دیگر رقم خورد، زیرا چند ساعت قبل از شروع عملیات، تکه کاغذی به دست او رسید که در آن نوشته شده بود:\r\n-آقای ردانی پور، شما شرعا مسئولید، اگر با گردان به عملیات بروید\r\nوقتی گردانها در زیر باران به طرف چم هندی حرکت می کردند، ایستاده بود کنار جاده و نگاه می کرد و هر چند لحظه ، قطره ی اشکی در محاسن پرپشت مردانه ی او محو می شد.\r\n"},{"id":1260,"category_id":9,"category_code":"s9","source_id":97,"title":"مردان بزرگ","content":"عالمان بزرگ هم حساب ویژه ای برای مصطفی باز کرده و احترام خاصی برای او قایل بودند.\r\n در اوایل سال 61، پس از دیدار علمای قم مانند آیت ا... بهاء الدینی و آیت ا... بهجت به دیدار آیت ا... مصباح یزدی رفتیم.\r\nآیت ا... مصباح به خاطر جایگاه ویژه ی علمی و مبارزاتی وحضور در چند مناظره ی ایدئولوژیک کمونیست ها، جایگاه بسیار محترم و ویژه ای در ذهن ما داشتند.\r\n وقتی به محضر ایشان رسیدیم، خیلی غافلگیرانه، خم شده و دست آقا مصطفی را بوسیدند .\r\n با دیدن آن صحنه، ضمن اینکه ما به عظمت روحی و افتادگی آیت الله مصباح یزدی پی بردیم، فهمیدیم، در وجود مصطفی چیزی است که مردان بزرگ آن را بهتر درک می کنند.\r\n"},{"id":1261,"category_id":9,"category_code":"s9","source_id":98,"title":"خبر شهادت","content":"عراقی ها نباید می فهمیدند که مصطفی شهید شده است. می گفتند، اگر اسیر شده باشد، برای او بد می شود، اما مصطفی کسی نبود که تن به اسارت دهد.\r\nبرای مصطفی هیچ کس اطلاعیه نداد. خبر شهادت او را از صدا و سیما که نگفتند هیچ، مراسمی هم برای او گرفته نشد.\r\nاگر کسی هم برای مصطفی گریه کرد، در تنهایی بود.\r\nدر سکوت و خلوت بود.\r\n"},{"id":1262,"category_id":9,"category_code":"s9","source_id":99,"title":"او روزي خواهد آمد ...","content":"ده سال بعد برای یافتن او به پیرانشهر و از آنجا به ارتفاعات 1924 در منطقه ی حاج عمران عراق رفتیم.\r\n این اولین گام بود تا بیش از چهارصد شهید از آن منطقه و اطراف آن به ایران اسلامی بازگردند، اما از مصطفی خبری نشد که نشد.\r\nیک شب در عالم رویا او را در آغوش گرفتم، سرحال و رزمنده، مثل روزهای دارخوین. با هیجان از او پرسیدم:\r\n-تو رجعت کرده ای؟ تو رجعت کرده ای؟\r\nمصطفی همانطور می خندید :\r\n-آری من رجعت کرده ام!\r\nو ما در انتظار رویت او در وعده ی رجعتیم.\r\n و او روزي خواهد آمد\r\n"},{"id":1263,"category_id":9,"category_code":"s9","source_id":100,"title":"مسئولیت","content":"دو روز قبل از شهادتش يعني  13/5/62 گفت :\r\nکسانی که با خون شهدا و ایثار و استقامت و تلاش سربازان گمنام، عنوانی پیدا کرده‌اند، مواظب خود باشند، اخلاق اسلامی را رعایت کنند و بدانند که هر که بامش بیش برفش بیشتر\r\n"},{"id":1264,"category_id":9,"category_code":"s9","source_id":101,"title":"قبولی","content":" مدیر دبستان با خودش فکر کرد و به این نتیجه رسید که حیف است مصطفی در آن جا بماند.\r\nخواستش و به ش گفت برود البرز و با دکتر مجتهدی نامی که مدیر آن جاست صحبت کند. البرز دبیرستان خوبی بود،ولی شهریه می گرفت.\r\nدکتر مجتهدی چند سؤال ازش پرسید. بعد یک ورقه داد که مسئله حل کند. هنوز مصطفی جواب ها را کامل ننوشته بود که دکتر مجتهدی گفت: \"پسر جان تو قبولی. شهریه هم لازم نیست بدهی.\"\r\n"},{"id":1265,"category_id":9,"category_code":"s9","source_id":102,"title":"کراوات","content":" سال دوم یک استاد داشتیم که گیرداده بود همه باید کراوات بزنند.\r\n سرامتحان، چمران کراوات نزد، استاد دونمره ازش کم کرد.\r\n شد هجده،\r\nبالاترین نمره.\r\n"},{"id":1266,"category_id":9,"category_code":"s9","source_id":103,"title":"پیشبند","content":" آن وقت ها که دفتر نخست وزیری بود، من تازه شناخته بودمش.\r\n ازش حساب می بردم. یک روز رفتم خانه شان ؛ دیدم پیش بند بسته، دارد ظرف می شوید.\r\nبا دخترم رفته بودم. بعد از این که ظرف ها را شست. آمد و با دخترم بازی کرد.\r\n با همان پیش بند.\r\n"},{"id":1267,"category_id":9,"category_code":"s9","source_id":104,"title":"جبهه","content":"وقتی جنگ شروع شد به فکر افتاد برود جبهه.\r\n نه توی مجلس بند می شد نه وزارت خانه. رفت پیش امام. گفت \"باید نامنظم با دشمن بجنگیم تا هم نیروها خودشان را آماده کنند، هم دشمن نتواند پیش بیاید.\"\r\nبرگشت و همه را جمع کرد. گفت:\r\n \"آماده شوید همین روزها راه می افتیم\".\r\n پرسیدیم \"امام؟\" گفت\r\n\"دعامان کردند.\"\r\n"},{"id":1268,"category_id":9,"category_code":"s9","source_id":105,"title":"یک ساعت خواب","content":"حدود یک ماه برنامه اش این بود؛\r\n صبح تا شب سپاه و برنامه ریزی،  شب ها شکار تانک.\r\nبعد از ظهرها، اگر کاری پیش نمی آمد، یک ساعتی می خوابید.\r\n"},{"id":1269,"category_id":9,"category_code":"s9","source_id":106,"title":"لات و لوتها","content":" تلفنی بهم گفتند:\r\n \"یه مشت لات و لوت اومده ن، می گن می خوایم بریم ستاد جنگ های نامنظم.\"\r\n رفتم و دیدم. ردشان کردم.\r\n چند روز بعد، اهواز، با موتورسیکلت ایستاده بودند کنار خیابان. یکیشان گفت\"آقای دکتر خودشون گفتن بیاین.\"\r\nمی پریدند؛ از روی گودال، رود، سنگر. آرپی جی زن ها را سوار می کردند ترک موتور، می پریدند. نصف بیشترشان همان وقت ها شهید شدند.\r\n"},{"id":1270,"category_id":9,"category_code":"s9","source_id":107,"title":"قوطی کنسرو","content":" وقتی کنسروها را پخش می کرد، گفت \"دکتر گفته قوطی ها شو سالم نگه دارین.\"\r\n بعد خودش پیداش شد، با کلی شمع.\r\nتوی هر قوطی یک شمع گذاشتیم و محکمش کردیم که نیفتد.\r\n شب قوطی ها را فرستادیم روی اروند.\r\nعراقی ها فکر کرده بودند غواص است، تا صبح آتش می ریختند.\r\n"},{"id":1271,"category_id":9,"category_code":"s9","source_id":108,"title":"کولر","content":"گفتم :\r\n\"دکتر جان، جلسه رو می ذاریم همین جا، فقط هواش خیلی گرمه. این پنکه هم جواب نمی ده. ما صد، صد و پنجاه تا کولر اطراف ستاد داریم، اگه یکیش را بذاریم این اتاق...\".\r\nگفت\r\n\"ببین اگه می شه برای همه ی سنگرا کولر بذارید، بسم ا... آخریش هم اتاق من.\"\r\n"},{"id":1272,"category_id":9,"category_code":"s9","source_id":109,"title":"روبوسی","content":"هر هفته می آمد، یا حداکثر ده روز یک بار.\r\n از اول خط سنگر به سنگر می رفت. بچه ها را بغل می کرد و می بوسید.\r\n دیگر عادت کرده بودیم.\r\nیک هفته که می گذشت، دلمان حسابی تنگ می شد.\r\n"},{"id":1273,"category_id":9,"category_code":"s9","source_id":110,"title":"خبردار","content":" برای نماز که می ایستاد، شانه هایش را باز می کرد و سینه ش را می داد جلو.\r\nیک بار به ش گفتم \"چرا سر نماز این طورمی کنی؟\"\r\n گفت:\r\n\"وقتی نماز می خوانی مقابل ارشد ترین ذات ایستاده ای. پس باید خبردار بایستی و سینه ت صاف باشد.\"\r\nبا خودم می خندیدم که دکتر فکر می کند خدا هم تیمسار است.\r\n"},{"id":1274,"category_id":9,"category_code":"s9","source_id":111,"title":"پل","content":"از فرمان دهی دستور دادند \"پل را بزنید.\"\r\n همه ی بچه ها جمع شدند، چند گروه داوطلب. دکتر به هیچ کدام اجازه نداد بروند. می گفت \"پل زیر دید مستقیم است.\"\r\n  \r\nصبحی خبر آوردند پل دیگر نیست. رفتیم آن جا. واقعا نبود. گزارش دادند دکتر و گروهش دیشب از کنار رود برمی گشتند\r\nمی خندیدند و برمی گشتند.\r\n"},{"id":1275,"category_id":9,"category_code":"s9","source_id":112,"title":"وزیر دفاع","content":"ناهار اشرافی داشتیم ؛ ماست.\r\nسفره را انداخته و نینداخته، دکتر رسید.\r\nدعوتش کردیم بماند. دست هاش را شست و نشست سر همان سفره.\r\nیکی می پرسید\r\n \"این وزیر دفاع که گفتن قراره بیاد سرکشی، چی شد پس؟\"\r\n"},{"id":1276,"category_id":9,"category_code":"s9","source_id":113,"title":"آرپی جی","content":"دکتر آرپی جی می خواست، نمی دادند.\r\nمی گفتند دستور از بنی صدر لازم است.\r\nتلفن کرده بود به مسئول توپ خانه. آن جا هم همان آش و همان کاسه. طرف پای تلفن نمی دید دکتر از عصبانیت قرمز شده.\r\n فقط می شنید که \"من از کجا بنی صدر رو گیر بیارم مجوز بگیرم؟\" رو کرد به من، گفت \"برو آن جا آرپی جی بگیر. ندادند به زور بگیر برو عزیز جان.\"\r\n"},{"id":1277,"category_id":9,"category_code":"s9","source_id":114,"title":"برگشت به تهران","content":"با خودش عهد کرده بود تا نیروی دشمن در خاک ایران است برنگردد تهران. نه مجلس می رفت، نه شورای عالی دفاع.\r\n یک روز از تهران زنگ زدند. حاج احمد آقا بود گفت \"به دکتر بگو بیا تهران.\" گفتم \"عهد کرده با خودش، نمی آد.\r\n\" گفت \"نه، بگو بیاد. امام دلش برای دکتر تنگ شده.\"\r\n به ش گفتم. گفت \"چشم. همین فردا می ریم.\"\r\n"},{"id":1278,"category_id":9,"category_code":"s9","source_id":115,"title":"خلبانی متعهد","content":"شهید شیرودی در سال 1351 وارد دوره مقدماتی آموزش خلبانی شد و پس از مدتی برای گذراندن دوره کامل به پادگان هوانیروز اصفهان منتقل شد. او با پایان دوره آموزش هلیکوپتر کبری به عنوان خلبان به استخدام ارتش درآمد. خلبانی متعهد، مسلمان، عاشق مردم مظلوم و ستمدیده، مقلد امام خمینی(ره) و طاغوت ستیز. یکبار در مانوری که قرار شده بود یکی از اعضاء خاندان طاغوت هم در آن شرکت کند، شهید شیرودی تصمیم گرفت با هیلکوپتر خود به جایگاه بزند تا با این عملش، ضمن شهید شدن، آن عضو ناپاک پهلوی را از روی زمین بردارد. اما این مانور هرگز برگزار نشد و شهید شیرودی نتوانست به مقصود خودش برسد."},{"id":1279,"category_id":9,"category_code":"s9","source_id":116,"title":"خلبانی جسور و فدارکار","content":"وقتی جنگ شروع شد، بنی‌صدر دستور تخلیه پادگانها را صادر کرد، شهید شیرودی آن موقع در پایگاه هوانیروز کرمانشاه بود. دستور داده شده بود که ضمن تخلیه پادگانها، زاغه مهمات را نیز با یک راکت از بین ببرند.\r\n اما شیرودی می‌گوید که حیف نیست این همه مهمات از بین رود. او با کمک چندتن از هم رزمانش با هیلکوپتر به صف مهاجمان عراقی هجوم برده و آنان را متوقف می‌سازند. و با این تزکه اگر بازداشتمان کردند که چرا پادگان را تخلیه نکردید، مهم نیست چون مملکت در خطر است، جلوی دشمن ایستادگی می‌کنند. شجاعت شیرودی در تمام خبرگزاریهای جهان منعکس می‌شود. بنی‌صدر هم برای حفظ ظاهر، چند درجه تشویقی برای شیرودی صادر می‌کند و درجه او را از ستوان‌یار سوم خلبان به درجه سروان ارتقاء می‌دهد.\r\n  اما شهید شیرودی این گونه پاسخ می دهد:\r\nاز: خلبان علی‌اکبر شیرودی\r\nبه: پایگاه هوانیروز کرمانشاه\r\nموضوع: گزارش\r\n     اینجانب که خلبان پایگاه هوانیروز کرمانشاه می‌باشم و تاکنون برای احیای اسلام و حفظ مملکت اسلامی در کلیه جنگها شرکت نمود‌ه‌ام، منظوری جز پیروزی اسلام نداشته و به دستور رهبر عزیزم به جنگ رفته ام.\r\nلذا تقاضا دارم درجه تشویقی که به اینجانب داده‌اند، پس گرفته و مرا به درجه ستوان‌یار سومی که قبلاً بوده‌ام برگردانید. در صورت امکان امر به رسیدگی این درخواست بفرمائید.\r\nباتقدیم احترامات نظامی\r\nخلبان علی‌اکبر شیرودی\r\n9/7/1359\r\n"},{"id":1280,"category_id":9,"category_code":"s9","source_id":117,"title":"شخصیتی والا","content":"هم رزمان شهید در خصوص شخصیت والای شیرودی می‌گویند:\r\n«روزی در تعقیب ضد انقلاب وقتی خواست راکتی شلیک کند، متوجه حضور بچه‌ای در آن حوالی شد. برگشت و ابتدا با بال هیلکوپتر بچه را ترساند که از آنجا برود و بعد از اینکه بچه از آنجا رفت، مجدداً حمله خود را آغاز نمود.»\r\nشهید شیرودی پس از دو سال مبارزه با ضد انقلاب در غرب کشور، به اصرار روحانیون و همرزمان پاسدارش در 20/6/1359 برای یکماه به مرخصی رفت، اما بیش ا زده روز در تنکابن نماند و به محض شنیدن حمله عراق به منطقه بازگشت. در آن چند روزی هم که در مرخصی بود اغلب با لباس کار به میان روستائیان می‌رفت و در گشتزارها به سالخوردگان کمک می‌کرد.\r\n"},{"id":1281,"category_id":9,"category_code":"s9","source_id":118,"title":"رکورد پرواز","content":"خود شیرودی می‌گوید:\r\n« اگر تعریف از خودم نباشد، فکر می‌کنم بالاترین پرواز جنگ در دنیا را داشته‌ام و تا به حال 360 بار از خطر گلوله‌های دشمن جان سالم به در برده‌ام. البته علت زنده ماندنم پس از چند هزار ماموریت هوایی و انجام بالاترین پروازهای جنگی، چیزی جز مشیت الهی نمی‌باشد.\r\nدر ضمن ، بیش از چهل هلیکوپتر که من خلبان آن بوده‌ام تیر خورده که البته همه آنها تعمیر شده و الان قابل استفاده می‌باشند.»\r\n"},{"id":1282,"category_id":9,"category_code":"s9","source_id":119,"title":"روحیه مثال زدنی","content":"شهید علی‌اکبر شیرودی به شدت خود را وقف جنگ و خدمت به اسلام کرده بود. او در جایی عنوان کرده بود:\r\n «من طاقت نمی‌آورم که دور از صحنه جنگ باشم و تا ثبات منطقه برقرار نشود، استراحت نمی‌خواهم.» این روحیه به حدی عجیب بود که یکبار وقتی فرزندش مریض می‌شود، در پاسخ همسرش که از او می‌خواهد به جبهه نرود می‌گوید: «جان یک بچه در مقابل جان این همه عزیزانی که در حال جنگ هستند، ارزشی ندارد.»\r\n"},{"id":1283,"category_id":9,"category_code":"s9","source_id":120,"title":"یه وانت گلوله","content":"در بهار 1358 خبری می‌رسد که عده‌ای ضد انقلاب در ارتفاعات «گهواره» در غرب تجمع کرده‌اند و قصد حمله به اسلام‌آباد را دارند.\r\n تیم آتشی مرکب از سه فروند هیلکوپتر کبری و یک فروند هیلکوپتر نجات به سمت منطقه موردنظر حرکتی می‌کنند. رهبری تیم آتش را شهید کشوری به عهده داشت. در حین عملیات ناگهان صدای شیرودی می‌آید که «آخ سوختم، آخ» همه هراسان از اینکه شیرودی را زدند، می خواستند منطقه را ترک کنند که صدای خنده شیرودی همه را میخکوب می‌کند. او در جواب سوالات خلبانان می گوید: «هیچی نشده، ناراحت نباشید، یه گلوله خورد بالای سرم و افتاد توی لباسم. خیلی داغه نمی‌تونم راحت بشینم.» عملیات با انهدام انبار مهمات و کشتن اشرار به پایان رسید. در بازگشت شهید کشوری به شیرودی می گوید: «راستی حالت چطوره، اون گلوله چی شد.»\r\n شیرودی می گوید: «فکر کنم دیگه غیب شده باشه.» کشوری می گوید: «پیدایش کند، یادگاری خوبیه» که شیرودی با خنده می گوید: «اگه می خواستم گلوله‌هایی را که به طرفم شلیک شده برای یادگاری جمع کنم، تا الان حداقل یه وانت گلوله باید داشته باشم.»\r\n"},{"id":1284,"category_id":9,"category_code":"s9","source_id":121,"title":"خاک","content":"تا قبل از جنگ، من برای خاک هیچ ارزش قائل نبودم و همیشه می‌گفتم هیچ وقت برای خاک نخواهم جنگید. اما حالا یک مشت خاک این منطقه، به خاطر حفظ اسلام برای من عزیزترین چیز است. خاک این مناطق با خون شهدایی مانند کشوری و امثال اینها آغشته شده است."},{"id":1285,"category_id":9,"category_code":"s9","source_id":122,"title":"مصاحبه و نماز","content":"شیرودی در کنار هیلکوپتر جنگی اش ایستاده بود و خبرنگاران هر کدام به نوبت از او سوال می‌کردند.\r\nخبرنگار ژاپنی پرسید: شما تا چه هنگام حاضرید بجنگید؟ شیرودی خندید. سرش را بالا گرفت و گفت: ما برای خاک نمی جنگیم ما برای اسلام می جنگیم. تا هر زمان که اسلام در خطر باشد این را گفت و به راه افتاد. خبرنگاران حیران ایستادند. شیرودی آستینهایش را بالا زد . چند نفر به زبانهای مختلف از هم پرسیدند: کجا؟ خلبان شیرودی کجا می‌رود؟ هنوز مصاحبه تمام نشده شیرودی همانطور که می رفت برگشت. لبخندی زد و بلند گفت: نماز! صدای اذان می آید وقت نماز است.\r\n"},{"id":1286,"category_id":9,"category_code":"s9","source_id":123,"title":"مبارزه جهانی","content":"وقتی در مصاحبه خبرنگاران خارجی، یک خبرنگار اروپایی از او علت وارد ساختن ضربات کوبنده به قوای دشمن را می پرسد، با انگشت دوازده تانک آتش گرفته عراقی و دو فروند هیلکوپتر سوارخ سوراخ شده دشمن را نشان می دهد و می گوید:\r\n«علت اینها فقط امداد الهی و کمک و فضل پروردگار می باشد که به ما این توانایی را می دهد.» شیرودی در پاسخ به سوال خبرنگار که آیا ممکن است محدوده جغرافیایی پروازهای آینده‌اش را برایشان ترسیم کند می گوید:\r\n«بهتر است نقشه دنیا را نگاه کنید زیرا اگر امام خمینی فرمان دهد، در هر نقطه جهان که مرکز کفر است  بجنگم، حتی اگر پایتخت ممالک شما باشد، آنجا را به آتش می‌کشم.»\r\n"},{"id":1287,"category_id":9,"category_code":"s9","source_id":124,"title":"عمارت زیبا","content":"این خاطره را رهبر معظم انقلاب نقل می کنند که شیرودی به یکی از برادران که از دوستان قدیمی‌اش بود، گفته بود:\r\n «فلانی! بیا یک خداحافظی از روی خاطر جمعی با تو بکنم زیرا می دانم که بزودی شهید می شوم.»\r\n این برادرمان گفته بود که خدا کند حفظ بشوی و خدمت کنی اما شهید شیرودی می گوید: «نه! من سرهنگ ،کشوری را در خواب دیدم. او به من گفت: شیرودی یک عمارت خیلی خوب برایت گرفته‌ام. باید بیایی توی این عمارت بنشینی.»\r\n به همین خاطر می‌دانم که رفتنی هستم.\r\n"},{"id":1288,"category_id":9,"category_code":"s9","source_id":125,"title":"قمقمه","content":"تمام شب را توى راه بوديم.  خسته و فرسوده رسيديم.\r\nهوا سرد بود.\r\nدست بردار نبود.  همين طور حرف مى زد;\r\n\"فردا چكار كنيد، چكار نكنيد، چند نفر بفرستيد آنجا، اين جا چند تا توپ بكاريد. اين دسته برگردد عقب، آن گروهان برود جلو.\"\r\nدقيق يادم نيست. يازده - دوازده شب بود كه چرتمان گرفت.\r\nزيلوى گوشه سنگر رابرداشتيم و پهن كرديم و دراز كشيديم.\r\nچيزى نداشتيم رويمان بيندازيم.\r\nپشت به پشت هم داديم و خوابيديم، كه مثلاً گرممان شود.\r\nدو ساعت كه گذشت، بلند شد.\r\nبا آب قمقمه اش وضو گرفت و ايستاد به نماز. حس نداشتم تكان بخورم، چه رسد به بلند شدن و وضو گرفتن.\r\nفقط نگاهش مى كردم\r\n"},{"id":1289,"category_id":9,"category_code":"s9","source_id":126,"title":"نامه","content":"در زدند. پيك بود. نامه آورده بود.\r\nقلبم ريخت. فكر كردم شهيد شده، وصيت نامه اش را آورده اند.\r\nنامه را گرفتم. باز كردم.\r\nيك انگشتر عقيق برايم فرستاده بود; از جبهه.\r\nنوشته بود:\r\n« اين انگشتر را فرستادم به پاس صبرها و تحمل هاى تو. به پاس زحمت هايى كه كشيده اى. اين را به تو هديه كردم.»\r\nآرام شدم.\r\n"},{"id":1290,"category_id":9,"category_code":"s9","source_id":127,"title":"ژیان","content":"اوايل انقلاب ژيان داشت.\r\nبهش مى گفتم: «بابا، اين همه ماشين توى پاركينگ موتوريه، چرا يكيش رو برنمى دارى، سوار شى؟»\r\nمى گفت: «همين هم از سرم زياده.»\r\nاز استاندارى دو تا حواله پيكان فرستادند. هر پيكان، چهل و پنج هزار تومان;يكى براى صياد، يكى براى من.\r\nصدايش را در نياوردم. نود هزار تومان جور كردم و ريختم به حساب ناسيونال.تلخ شد.\r\nگفت: «كى پيكان خواسته بود؟»\r\nماجرا را گفتم.\r\nگفت «پولم كجا بود؟» ژيانش را گرفتم. فروختم بيست هزار تومان. بيست و پنج هزار تومان هم براش وام گرفتم، تا خيالش راحت شد.\r\nچند سال بعد، ستاد مشترك ارتش بهش حواله حج داد.\r\n قبول نكرد با پول ستاد برود.\r\nپيكانش رو فروخت.\r\nخرج مكه اش كرد.\r\n"},{"id":1291,"category_id":9,"category_code":"s9","source_id":128,"title":"اشک","content":"چشماش پر از اشك مى شد، امّا اشكش نمى ريخت; جارى نمى شد.\r\nخودش را خيلى نگه مى داشت.\r\nدر بدترين شرايط اشكش جارى نمى شد.\r\nفقط يك بار گريه اش را ديدم،\r\nوقتى امام را از دست داديم.\r\n"},{"id":1292,"category_id":9,"category_code":"s9","source_id":129,"title":"خادم ملت","content":"مثل كارمندها نمى آمد ستاد كل; كه هفت ونيم يا هشت صبح، كارت ورود بزند و چهار بعد از ظهر، كارت خروج.\r\nزود مى آمد و دير مى رفت.\r\nخيلى  دير.\r\nمى گفت:\r\n«ما توى كشور بقية الّله هستيم. خادم اين ملتيم. مردم ما رو به اين جا رسوندن، مردم. بايد براشون كار كنيم. »\r\n"},{"id":1293,"category_id":9,"category_code":"s9","source_id":130,"title":"رضایت","content":"هرلحظه اين احساس را داشتم; كه هر وقت باشد، شهيد مى شود.  هميشه هم بهش مى گفتم.\r\nمى گفتم كه : «هر وقت باشه، شهيد مى شى. ولى دوست دارم به اين زودى ها شهيد نشى. هنوز پسرام داماد نشدند. مى خوام خودت دامادشون كنى. »\r\nخواب ديده بود.\r\nديده بود كه يكى از دوست هاى شهيدش آمده ببردش. نمى رفت. به ما نگاه مى كرد و نمى رفت.\r\nما خيلى گريه مى كرده ايم. دوستش به زور دستش را كشيده بوده و برده بودش.\r\nبعد از اين خوابش، بهم گفت:\r\n«تو بايد راضى باشى تا من برم. خودت رو آماده كن. »\r\n"},{"id":1294,"category_id":9,"category_code":"s9","source_id":131,"title":"پرواز","content":"لباس آبى تنش بود.  ماسك زده بود و داشت خيابان را جارو مى كرد. تعجب كردم.\r\nرفتگرها كه لباسشون نارنجيه؟درِ حياط را تا آخر باز كردم.\r\nبابا گاز داد و رفت بيرون.\r\nيك لنگه در رابستم. چفت بالا را انداختم.\r\nجارويش را گذاشت كنار و رفت جلو. يك نامه از جيبش درآورد.\r\nپدر تا ديدش، به جاى اين كه شيشه را بكشد پايين، در ماشين را باز كرد. نامه را ازش گرفت كه بخواند.\r\nدولاّ شدم، چفت پايين را ببندم.\r\nصداى تير بلند شد.\r\nديدم يكى دارد مى دود به طرف پايين خيابان; همان كه لباس آبى تنش بود.\r\nشوكه شدم. چسبيده بودم به زمين.\r\nنتوانستم از جام تكان بخورم. كنده شدم، دويدم به طرف بابا. رسيدم بالاى سرش.\r\nهمان طور، مثل هميشه، نشسته بود پشت فرمان. كمربند ايمنيش را هم بسته بود.  سرش افتاده بود پايين;\r\nانگار خوابيده باشد، امّا غرق خون\r\n"},{"id":1295,"category_id":9,"category_code":"s9","source_id":132,"title":"صیاد","content":"سحر بود. نماز را در حرم امام خوانديم و راه افتاديم.\r\nرسممان بود كه صبح روز اوّل برويم سر خاك. رسيديم.\r\nهنوز آفتاب نزده بود، امّا همه جا روشن بود.\r\nيكي زودتر از همه آمده بود; زودتر از بقيّه، زودتر از ما\r\nگفتم: شما چرا اين موقع صبح خودتون روبه زحمت انداختيد؟\r\nآيت الله خامنه اي فرمودند: دلم براى صيادم تنگ شده. مُدَتيه ازش دور شده ام\r\nتازه ديروز به خاك سپرده بوديمش.\r\n"},{"id":1296,"category_id":9,"category_code":"s9","source_id":133,"title":"پابرهنه","content":"گردان پشت میدون مین زمینگیر شد\r\nچند نفر رفتن معبر باز کنن\r\n14 ساله بود\r\nچند قدم دوید سمت میدان ... یکدفعه ایستاد!!\r\nهمه فکر کردند ترسیده\r\nیکی گفت: خب ! طفلک همش 14 سالشه\r\nپوتین هاشو داد به بچه ها و گفت:\r\n\r\n\"تازه از گردان گرفتم ،حیفه! بیت الماله\"\r\nو پا برهنه رفت...\r\n"},{"id":1297,"category_id":9,"category_code":"s9","source_id":134,"title":"اردات","content":"پزشک معالج من در آلمان، یک پروفسر اتریشی بود. میگفت:(( من اهل سیاستم، تئوریسین اک ، برای خودم نظریه دارم.))  با من خیلی صحبت میکرد. از این صحبت ها خوشش می آمد. یک روز سرتا پای من را عکس رنگی گرفتند و بردند پیش پروفسر ژوزخ تا هر چه  شی خارجی در بدم هست ، مشخص شود.\r\nپرسید: چقدر تیر و ترکش خوردی ، در بعضی جاها یکیش هم کافی است که طرف تمام کند، تو چرا هنوز زنده ایی؟\r\nگفتم: دکتر!× حالا این قدر خوش اخلاقی، زود تر همین تیکه پاره ها رو سرهم بندی کن ما بریم به کارمون برسیم. قربون دستت...\r\nپرسید کجا میخوای بری؟\r\nگفتم : جبهه\r\nبا تعجب نگاهی کرد و گفت: (( دوست دارم بیایم و این مرد ( امام خمینی رحمه الله علیه ) را ببینم. ببینم با شما چه کرده که این قدر بهش ارادت دارید.))\r\n"},{"id":1298,"category_id":9,"category_code":"s9","source_id":135,"title":"بابا چرا؟","content":"بردنش بیمارستان . چند روز بعد 12 بهمن 65، شهید شد. آن روز، روز شهادت حضرت زهرا (سلام الله علیها) بود.\r\nحجت الاسلام  عبدالله میثمی به سال 1334 در اصفهان متولد شد و در سال 1365 ، طی عملیات کربلای 5 بال در بال ملائک گشود.\r\nاز ایشان روایت شده است که:\r\nماه های آخر می گفت: از خودم بدم می آید .خسته شدم از بس برای مجلس شهدا سخنرانی کرده ام . از وقتی آمده ام جبهه ، ماه ها را می شمرم که سر سی ماه جواب و مزد کارهایم را از خدا بگیرم.\r\nقبل از عملیات ،خانم و بچه هایش از اصفهان آمدند اهواز دیدنش . هادی کوچولو تا او را دید ، پرید بغلش وگفت : \"بابا!چراصدام هنوز شما را نکشته ؟\" حاجی غش رفت برای هادی.\r\n قبل از رفتن ، زیارت حضرت زهرا (س) خواند. ایام فاطمیه بود. رمز عملیات هم یا زهرا (س)! عملیات که شروع شد ، حاجی گفت: فلانی! من در این عملیات اجر خودم را از خدا می‌گیرم.\r\nشب دوم عملیات بود. حاجی از سنگر رفت بیرون وضو بگیرد،اما دیگر بر نگشت. تركش خورده بود به سرش.  بردنش بیمارستان . چند روز بعد 12 بهمن 65، شهید شد. آن روز، روز شهادت حضرت زهرا (سلام الله علیها) بود.\r\n"},{"id":1299,"category_id":9,"category_code":"s9","source_id":136,"title":"لب تشنه","content":"لب هایش از تشنگی خشک شده بودند. چند تا اسیر گرفته بودیم. با قمقمه اش به یکیشان کمی آب داد. گفت مسلمان هوای اسیر را هم دارد. با قمقمه رفت سراغ اسیر بعدی، اما به ش نرسید. ترکش خمپاره  سرش را پراند!؟"},{"id":1300,"category_id":9,"category_code":"s9","source_id":137,"title":"لیوان نصفه","content":" ته صف بودم. به من آب نرسید. بغل دستیم لیوان آب را  داد دستم. گفت من زیاد تشنه ام نیست. نصفش را تو بخور. فرداش شوخی شوخی به بچّه ها گفتم از فلانی یاد بگیرید. دیروز نصف آب لیوانش را به من داد. یکی گفت لیوان ها همه اش نصفه آب بود!"},{"id":1301,"category_id":9,"category_code":"s9","source_id":138,"title":"سنگر","content":"سنگر عراقی ها را گرفتیم.قرآن باز کردم، سوره ی تبارک آمد و آیه هایی درباره ی مرگ و زندگی. واین که زندگی و مرگ دست خداست. قرآن را نبسته بودم گلوله ای کنارمان منفجر شد. گونی های خاک بود که بر سر و رویمان می ریخت. یکی از برادرها از حرارت موشک کمی سوخت. بقیه هیچ زخمی برنداشتند. موشک دشمن درست خورده بود زیر سنگر؟"},{"id":1302,"category_id":9,"category_code":"s9","source_id":139,"title":"برادر علی","content":"دویدم تا به فرماندهی گردان رسیدم. زیر آن همه آتش، خونسرد نشسته بود و با بی سیم صحبت می کرد. انگار در خانه شان است. گفتم: برادر علی، سمت چپ خیلی شلوغه. چند تا کمکی بدهید.آرام گفت: نداریم، برو. داد زدم: عراقی ها زیادند. نمی توانیم مقاومت کنیم. از در و دیوار می ریزند تو کانال. با خونسردی گفت: خب بکشیدشان. بعد خندید و گفت: برو به همه  همین را که گفتم بگو"},{"id":1303,"category_id":9,"category_code":"s9","source_id":140,"title":"مسافر ملکوت","content":"شب جمعه بود؛ سیزده ساله بودم؛ درس‌هایم را مرور کردم؛ دیر وقت بود که علی به خانه آمد وضو گرفت و بدون خوردن شام به اتاقش رفت؛ با ناراحتی به پدر و مادرم گفتم «شما همیشه به من می‌گویید نماز سر وقت بخوانم، اگر جرأت دارید به علی بگویید، چرا حالا ساعت 11 شب نماز می‌خواند؟» پدر و مادرم با لبخندی همیشگی اعتراضم را جواب دادند و گفتند :تو هنوز نمی‌دونی، این وضوی نماز واجب نیست.\r\nمدام چشم به چراغ اتاق او داشتم، چراغی که تا نیمه شب روشن بود، تنها مونس علی من بودم، تنها کسی که راه به اتاق او داشت، من بودم و تنها کسی که به داستان‌های او گوش می‌کرد، من بودم و تنها کسی که از عظمت روح او خبر نداشت هم من بودم! من هیچگاه شکوه نمازهای نیمه شب او را درک نکردم.\r\nهفته قبل از جبهه بازگشته بود؛ همراه خود سوغات جبهه آورده بود. ترکش، موج انفجار، روماتیسم و … بعد از شهادتش ما داروهای جورواجور را در اتاقش دیدیم؛ آن شب گذشت؛ صبح آماده رفتن به مدرسه بودم، آخرین لقمه‌های صبحانه را می‌خوردم که اطلاعیه مهم رادیو توجه مرا جلب کرد. در آن اطلاعیه مرکز اعزام نیروی بسیج از نیروهای گردان ثارالله خواسته بود تا ساعت 10 صبح خودشان را به مرکز اعزام نیرو معرفی کنند؛ خبر را به خواهرم دادم و به او گفتم که به علی خبر دهد.\r\nساعت 10 صبح علی برای خداحافظی به خانه آمد و 10 روز بعد او را بار دیگر با لبخند همیشگی‌اش در سردخانه خلدبرین یزد ملاقات کردیم.\r\nروز شنبه سیزدهم رجب، روز میلاد مولای متقیان حضرت علی(ع) بود، بعد از نماز صبح از اتاق بیرون آمدم، مادر را دیدم که مدام نماز می‌خواند و دعا می‌کرد؛ پدر را که سماور بزرگ روضه خوانی را آماده می‌کرد، نمی‌دانستم چه خبر است، دنیا دور سرم می‌چرخید. ساعتی بعد زنگ خانه به صدا درآمد، پدر در را باز کرد و با دیدن آن برادر سپاهی دیگر نتوانست، هیچگاه کمرش را راست کند. هنوز چند روزی نگذشت که موهای سر پدر و مادرم سفید شد، آن برادر سپاهی فقط یک جمله گفت : پدر، علی شما چند روز پیش در شلمچه به دیدار امام حسین(ع) رفت.\r\nآن روز تا شب گریه کردم و به سکوت پدر و گریه‌های مادر توجهی نداشتم، لباس‌های عیدمان به سیاهی گرایید و روز تشییع جنازه بود که فهمیدم برادرم چگونه شهید شده است.\r\nدر منطقه عملیاتی «کربلای 5» در شلمچه، علی پس از خواندن نماز مغرب برای تجدید وضو از سنگر بیرون رفت و در هنگام رکوع رکعت اول به نماز رسید؛ تکبیر گویان وارد سنگر شد و به نماز ایستاد و در هنگام رکوع رکعت دوم، یک گلوله توپ فرانسوی در نزدیکی سنگر به زمین نشست و تنها علی را به ملکوت فرستاد.\r\n"},{"id":1304,"category_id":9,"category_code":"s9","source_id":141,"title":"پس‌گردنی","content":"روحانی لشکر سخنرانی می‌کند. حاج همت تازه گرم شنیدن صحبت‌های او شده که بازهم مردی از مقابلش می‌گذرد و مثل همیشه سلام می‌کند. حاج همت هم مثل همیشه جوابش را می‌دهد و مثل همیشه در فکر فرو می‌رود تا او را بشناسد؛ اما هرچه به مغزش فشار می‌آورد، او را به جا نمی‌آورد. چندبار تصمیم گرفته موضوع را از خودش بپرسد، اما نیرویی از درون مانع این کار شده. حاج همت هر وقت آن مرد را می‌بیند، چیزی شبیه به شرم و گناه در خود احساس می‌کند، اما چه شرم و گناهی، خودش هم نمی‌داند.  \r\nروحانی لشکر می‌گوید: «پیامبر اکرم (ص) در روزهای آخر عمر خود به مسجد آمد و فرمود: هرکس حقی به گردن من دارد، برخیزد و طلب کند؛ چرا که قصاص در این دنیا آسان‌تر از قصاص در روز رستاخیز است.   \r\nمردی به نام سواده برخاست و گفت: یا رسول الله، یک روز بر شتری سوار بودی. وقتی تازیانه‌ات را در هوا می‌چرخاندی، تازیانه به شکم من خورد. من حالا می‌خواهم قصاص کنم   \r\nاین روایت، توجه حاج همت را به خود جلب می‌کند. با اشتیاق به ادامه حرفهای روحانی گوش می‌دهد. روحانی ادامه می‌دهد: «پیامبر اکرم (ص) خودش را برای قصاص آماده کرد. سواده گفت: یا رسول الله، آن روز تن من برهنه بود. رسول خدا پیراهنش را بالا زد و گفت: قصاص کن. سواده خودش را به رسول خدا رسانید و او را در آغوش گرفت و عاشقانه شکم و سینه‌اش را بوسید. همه اهل مسجد به گریه افتادند   \r\nحاج همت به گریه می‌افتد. ناگهان چیزی در ذهنش مثل پتک ضربه می‌زند. چهره آن مرد مثل یک تابلو در طاقچه ذهنش ثابت می‌ماند. حاج همت به هر طرف که می‌چرخد آن مرد را می‌بیند. از شرم و عذاب وجدان، سرش را پایین می‌اندازد و از حسینیه خارج می‌شود  \r\nجمله پیامبر (ص) مثل زنگی پی در پی در ذهن حاج همت نواخته می‌شود: هرکس حقی به گردن من دارد، برخیزد و طلب کند؛ چرا که قصاص در این دنیا آسان‌تر از قصاص در روز رستاخیز است.     \r\nتن حاج همت داغ می‌شود و ضربان قلبش شدت می‌گیرد. او بیقرار است. اطرافیان از حالت غیرعادی او تعجب می‌کنند و با نگرانی به هم چیزهایی می‌گویند، اما حاج همت متوجه هیچ کس نیست. او تنها به آن مرد فکر می‌کند. وقتی سخنرانی روحانی تمام می‌شود، بدون اینکه با کسی حرفی بزند، به حسینیه بر می‌گردد و در تاریکی منتظر خروج آن مرد می‌ماند.     \r\nنکته‌ای را از قبل به یاد می‌آورد\r\nچیزی به پیروزی انقلاب نمانده بود. وقتی امام خمینی فرمان راهپیمایی داد، بیشتر مردم به خیابان‌ها ریختند. ساواکی‌ها قدرت خودشان را از دست داده بودند. در عوض، عده‌ای فرصت طلب، قدرت گرفته بودند. آن‌ها خودشان را انقلابی جا می‌زدند. وقتی راهپیمایی می‌شد، به میان جمعیت آمده، شعارهای مردم را عوض می‌کردند. آن‌ها به جای امام، کس دیگری را رهبر معرفی می‌کردند. بعضی وقت‌ها با این کارشان بین مردم تفرقه می‌انداختند و باعث بهم خوردن راهپیمایی می‌شدند.  \r\nحاج همت پی به توطئه آن‌ها برده بود و برای مقابله، شعارهای انقلابی را چاپ کرده و بین مردم پخش کرده بود. آن روز، یک نفر از پشت بلندگو شعار‌ها را می‌خواند و مردم تکرار می‌کردند.     \r\nآن مرد، پیشاپیش حاج همت حرکت می‌کرد و همراه مردم شعار می‌داد. حاج همت مراقب اوضاع بود. ناگهان دستهای آن مرد بالا آمد و شعاری شنیده شد. در یک لحظه، نظم مردم به هم ریخت. چیزی نمانده بود که بی‌نظمی به همه جا سرایت کند. حاج همت در حالی که شعار اصلی راهپیمایی را با صدای بلند تکرار می‌کرد، به سمت آن مرد هجوم برد و یک پس گردنی به او زد. آن مرد از این کار حاج همت جا خورده بود، می‌خواست لب به اعتراض باز کند که با اعتراض دسته جمعی مردم مواجه شد.     \r\nبا این برخورد حاج همت، شعار‌ها دوباره منظم شد و مردم به حرکت خود ادامه دادند.\r\n"},{"id":1305,"category_id":9,"category_code":"s9","source_id":142,"title":" حاج همت","content":"حاج همت بازهم مراقب اوضاع بود. در‌‌ همان لحظه، پیرمردی پیش آمد و درگوشی به او گفت: چرا آن آقا را زدی؟     \r\n_چون شعار انحرافی داد.   \r\n_با چشم خودت دیدی که او شعار داد؟     \r\nعرق، سر و روی حاج همت را فراگرفت و چهره‌اش از ناراحتی کبود شد. او با چشم خودش ندیده بود. پیرمرد ادامه داد: «آن کسی که شعار انحرافی داد، فرار کرد و رفت     \r\nحاج همت دیگر صدای پیرمرد را نمی‌شنید. سراسیمه به دنبال مرد گشت؛ اما هرچه تلاش کرد، او را نیافت.   \r\nچندین سال از آن ماجرا می‌گذرد. ‌ آن مرد حالا یکی از نیروهای لشکر حاج همت است؛‌‌ همان مردی که رو در روی حاج همت ایستاده و با نگاهی معنادار به او خیره شده. حاج همت هنوز از شرم و خجالت بیقرار است. او با صدای بلند از همه می‌خواهد که لحظه‌ای بمانند.    \r\nمی‌گوید: من به این مرد ظلم کرده‌ام. در حضور یک جمعیت ظلم کردم؛ اما حالا از حاضر کردن آن جمعیت عاجزم. از این مرد تقاضا دارم در حضور همین جمع، مرا قصاص کند.   \r\nپیش رفته، سرش را در مقابل مرد فرو می‌آورد. همه از رفتار او تعجب می‌کنند. منتظر عکس العمل مرد می‌مانند. مرد در حالی که بغض در گلو دارد دست می‌اندازد دور گردن حاج همت و گردنش را غرق بوسه می‌کند. حاج همت زانو زده، پاهای مرد را می‌بوسد   \r\nاشک در چشمان همه حلقه می‌زند.\r\n"},{"id":1306,"category_id":9,"category_code":"s9","source_id":143,"title":"شوخی کارساز","content":"در قسمتی از خاکریز خط مقدم جبهه انفجار گلوله ای، سه شهید و دو مجروح بر جای گذاشت. به طرف آنها رفتیم تا کمکشان کنیم. یکی از مجروحان که حالش مناسب تر بود، بسیار آه و ناله می کرد. برادر همراهمان گفت: چه خبره بابا! آنها که شهید شده اند، چیزی نمی گویند; تو که فقط زخمی شده ای، این همه داد و فریاد می کنی!\r\nهمین گفته طنزآمیز باعث سکوت آن برادر مجروح شد.\r\n"},{"id":1307,"category_id":9,"category_code":"s9","source_id":144,"title":"بچه حوری","content":"توی همه آنهایی که مرا بخاطر کم سن‌وسالی اذیت می‌کردند یکی خیلی مرا سوزاند. هیچ وقت یادم نمی‌رود. آمد جلوی همه ،خیلی آرام و ساده و بدون کنایه گفت :\"تو اگر شهید بشوی آن دنیا یک بچه حوری گیرت می‌آید."},{"id":1308,"category_id":9,"category_code":"s9","source_id":145,"title":"اوج ایثار","content":"در عملیات محرم، یکی از برادران بسیجی ترکش خورد و به شدت مجروح شد. او در همان حال نزد ما آمد و گفت: من رفتنی هستم، بگویید چه کاری از دستم بر می آید تا برایتان انجام دهم.\r\nیک تیربار عراقی ما را خیلی اذیت می کرد. نارنجکی به این برادر بسیجی دادیم و گفتیم: اگر توانستی سینه خیز نزدیک دشمن برو و با این نارنجک، تیربار را خاموش کن. او سینه خیز پیش رفت، نزدیک دشمن که رسید، نارنجک را به طرف تیربار عراقی پرتاب کرد و در همان حال سرباز عراقی او را به رگبار بست؛ او شهید شد و تیربار دشمن هم نابود گشت.\r\n"},{"id":1309,"category_id":9,"category_code":"s9","source_id":146,"title":"بوی عطر","content":"بوی عطرعجیبی داشت. هر وقت اسم عطرش را می پرسیدم سر بالا جواب میداد.وقتی شهید شد تو وصیتنامه\r\nاش نوشته بود؛بخدا قسم هیچگاه به خودم عطر نزدم،هر وقت میخواستم معطر بشوم از ته دل می گفتم:\r\n\"یاحسین(ع)\"\r\n"},{"id":1310,"category_id":9,"category_code":"s9","source_id":147,"title":"به خاطر نماز شب","content":"حدود يک ساعت بود كه از نورافشانى خورشيد، مى گذشت و طبق معمول آمارگيرى صبح تمام شده بود. با سوت مسؤول قسمت كه نشانه آزادباش بود، عدّه اى به طرف صفهاى دستشويى كه به ستون پنج در محوّطه تشكيل شده بود، در حركت بودند و تعدادى هم به سوى شير آب - كه در آن گرماى سوزان ماه تير، تنها آب خنكى بود كه مى شد مصرف و گلوى خشكيده خود را تر كرد - مى رفتند.\r\nهمينكه هياهوها و جُنب و جوشها جاى خود را به سكوت و آرامش داد، صورتهاى كبود و ورم كرده تعداد زيادى از بچّه هاى خوب و مؤ من آسايشگاه شش، توجه ديگران را به خود جلب كرد و تعجّب همگان را برانگيخت در اين ميان، چيزى كه باعث تعجّب بيشترمان شده بود، شب گذشته هيچ گونه سروصدا و داد و فريادى نشنيده بوديم! به هر حال، روحيه كنجكاو و جستجوگر اسرا سبب شد تا از واقعيّت قضيّه باخبر شوند.\r\nتعداد زيادى از برادران اين آسايشگاه از بچّه هاى سپاه و جزء كادر لشكرهاى مختلف و يا اينكه از دانشجوهاى انقلابى و مؤمن بودند. اين عزيزان، نيمه هاى شب بيدار مى شدند تا با يگانه معبود خود راز و نياز كنند و قلب خود، اين حرم الهى را با اشك ديده بشويند تا جلا و صفايى يابد، امّا در يكى از همين شبها، چشم ناپاک و نامحرم يكى از نگهبانان عراقى، آنان را مى بيند و فرداى آن روز، جريان را به افسرشان گزارش مى كند.\r\n(نقيب جمال)، مسؤول اردوگاه، نصف شب روز بعد، با تعدادى از سربازانش به داخل آسايشگاه رفته و بعد از آنكه آنان را در انتهاى آسايشگاه جمع مى كند، يكى - يكى به جلو آورده، آنگاه كفشى را در دهان آنان مى گذارد! سپس تهديدشان مى كند به اينكه كفش از دهانشان نيفتد و هيچگونه صدا و ضجّه اى نكنند و با خاموش كردن پنكه ها و بستن پنجره ها در آن هواى گرم، با سيلى و ته كفش، صورتهاى آنان را كبود مى كنند.\r\nاز آن روز به بعد، به هر نحوى، برادران اين آسايشگاه را مورد اذيّت و آزار قرار دادند به طورى كه بچّه هاى قسمت، اين آسايشگاه را (دانشكده افسرى) ناميده بودند؛ زيرا عراقيها با وضع قوانين خشک و بى منطق و ايجاد محدوديتهاى بى مورد، مثل ممنوع كردن وضو در داخل آسايشگاه، تنبيه هاى مكرّر (بشين، برپا، به چپ، چپ، به راست، راست و...) قبل از آمار ظهر يا شب، آسايشگاه را تبديل به يک پادگان نظامى كرده بودند.\r\n"},{"id":1311,"category_id":9,"category_code":"s9","source_id":148,"title":"دژبان","content":"شانزده ساله بود و تازه به جبهه آمده بود. برای او پست دژبانی تعیین کرده بودند و بازرسی عبور و مرور خودروها را بر عهده داشت.\r\nشهید حاج حسین خرازی، فرمانده لشکر، به اتفاق دو نفر از مسئولان در حالی که سوار تویوتا بودند، می خواستند به موقعیت وارد شوند. بسیجی دژبان که آنها را نمی شناخت، گفت: لطفاً کارت شناسایی. حاج حسین گفت: همراهمان نیست. دژبان گفت: پس حق ورود ندارید. یکی از همراهان خواست حاج حسین را معرفی کند، اما حاجی با اشاره، او را به سکوت فرا خواند. اصرار کردند، سودی نداشت. دژبان کارت شناسایی می خواست.\r\nهمراه دیگر حاجی که طاقتش به سر آمده بود، گفت: زود باش طناب را بنداز بریم، حوصله نداریم! دژبان در حالی که اسلحه را به طرف آنها نشانه رفته بود، با لحنی خشن گفت: بلبل زبونی می کنی؟ زود بیایید پایین، دراز بکشید روی زمین و کمی سینه خیز برید تا به مقررات آشنا شوید.\r\nحاج حسین با فروتنی خاصی که داشت، به همراهان خود آهسته گفت: هر کاری می گوید انجام دهید.\r\nاز خودرو پیاده شدند. در این هنگام دژبان متوجه شد که یکی از آنها؛ یعنی حاج حسین، یک دست بیشتر ندارد. به همین دلیل گفت: خیلی خوب تو سینه خیز نرو، اما ده مرتبه بنشین و پا شو!\r\nدر همین حال مسئول دژبانی که در حال عبور از آن جا بود، سراسیمه به طرف دژبان دوید و گفت: برو کنار، بگذار وارد شوند، مگر نمی دانی ایشان فرمانده لشکر است.\r\nبا شنیدن این سخن، حالت بیم و شرم ساری در چهره دژبان هویدا شد. حاج حسین بدون آن که ذره ای ناراحت شود، با تبسمی حق شناسانه، دژبان را در آغوش گرفت و بوسه ای بر چهره او زد و گفت: اتفاقاً وظیفه اش را خیلی خوب انجام داد، و پس از سپاس گزاری از دژبان به دلیل حُسن انجام وظیفه، خداحافظی کرد و رفت.\r\n"},{"id":1312,"category_id":9,"category_code":"s9","source_id":149,"title":"لبخندهای ماندگار...","content":"خیلی شوخ طبع بود\r\nهر وقت بود ، خنده هم بود\r\nهر جایی بود ، در هر حالتی  ، دست بردار نبود\r\nخمپاره که منفجر شد ترکش خورد\r\nگفت: بچه ها ناراحت نباشین ، من میرم عقب تا امام تنها نباشه\r\nامدادگرهایی که میذاشتنش روی برانکارد از خنده روده بر شده بودند...\r\n"},{"id":1313,"category_id":9,"category_code":"s9","source_id":150,"title":"در اوج احتیاط","content":"سردار شهید «علی چیت سازیان» تقوای عجیبی داشت. روزی که از همدان به سمت منطقة یک می آمدم، خانمی دبه ای از شیرة ملایر به من داد و گفت: این را به آنهایی که به خدا نزدیک تر هستند، برسان!.\r\nمطمئناً نظرش تمامی بچه های جنگ بود؛ ولی من که حال و هوای معنوی بچه های اطلاعات و عملیات را دیدم، آن را به تدارکاتِ واحد آنها تحویل دادم و اولین قاشق از آن شیره را به علی آقا دادم.\r\nبعد از آنکه علی آقا و دیگر بچه های اطلاعات خوردند، حرف آن خانم را برای آنها ذکر کردم؛ یک دفعه اشک در چشمان علی آقا نشست. دستهایش را به طرف آسمان برد و گفت: خدایا! چگونه جواب این مردم را بدهیم؟\r\nالبته ایشان به این هم راضی نشد تا آنکه گفت: به آن خانم بگو مرا حلال کند.\r\nزیرا سردار علی چیت سازیان خود را جزء کسانی که به خدا نزدیک تر هستند نمی دانست\r\n"},{"id":1314,"category_id":9,"category_code":"s9","source_id":151,"title":"کریمانه...","content":"حقوقش رو گرفت و از سپاه مریوان اومد بیرون\r\nدید یه زن بچه به بغل کنار خیابون نشسته و گریه میکنه\r\nرفت جلو و پرسید: چرا ناراحتی خواهرم؟\r\nزن گفت: شوهر بی غیرتم من و بچه ی صغیرم رو ول کرده رفته تفنگچی کومله شده\r\nبه خدا خیلی وقته یک شکم سیر غذا نخوردیم\r\nحاج احمد بغضش گرفت\r\nبلافاصله دست کرد جیبش و همه ی حقوقش رو دو دستی گرفت سمت زن و گفت:\r\nبه خدا من شرمنده ام! این پول ناقابل رو بگیرید\r\nهدیه مختصری است. فعلا امور خودتون رو با اون بگذرانید\r\nنشانی تون رو هم بدهید به برادر دستواره\r\nبعد از این مواد خوراکی شما رو خودش میاره درب خانه بهتون تحویل میده\r\n"},{"id":1315,"category_id":9,"category_code":"s9","source_id":152,"title":"حیای محمد علی ...","content":"یازده دوازده ساله بود و داشت با بچه ها بازی می کرد\r\nزن دایی صداش کرد و گفت: بیا ناهار حاضره\r\nاومد سر سفره نشست اما دست به غذا نمیزد\r\nزن دایی با تعجب گفت: مگه گرسنه نیستی ؟ چرا نمی خوری؟\r\nهمونطور که سرش پایین بود گفت: میشه خواهش کنم چادرتون رو سرتون کنین؟\r\nزن دایی وقتی دید با این سن و سال اینقدر مقیده خوشحال شد\r\nرفت چادرش رو سرش کرد تا محمد علی راحت غذا بخوره.\r\n"},{"id":1316,"category_id":9,"category_code":"s9","source_id":153,"title":"آتش شهوت","content":"سوار تاکسی که شد از راننده خواست که نوارش را خاموش کند .راننده که جوان خوش چهره ای بود گفت :(بابا بی خیال ! ما جواینم، بزارید آزاد باشیم) محمود گفت : ( شما اگر جایی آتش باشه بنزین داخلش می ریزید یا مواد منفجره کنارش میزارید ؟)پسر جوان که از سوال تعجب کرده بود ، گفت (نه ، این طوری که آتش شعله ور می شه !)محمود گفت :  خوب، شما جوانید و آتش شهوت درونتون شعله وره ،دیگه نباید با این چیزا بیشترش کنید ، ممکنه به جایی برسه که دیگه نتونید جلوش را بگیرید و دین و دنیاتون را از دست بدید !"},{"id":1317,"category_id":9,"category_code":"s9","source_id":154,"title":"یه قوطی کمپوت","content":"نامه نوشته بود:\r\n«برادر رزمنده سلام، من یک دانش آموز دبستانی هستم. خانم معلم گفته بود که برای کمک به رزمندگان جبهه های حق علیه باطل نفری یک کمپوت هدیه بفرستیم.\r\nبا مادرم رفتم از مغازه بقالی کمپوت بخرم. قیمت هر کدام از کمپوت ها رو پرسیدم، اما قیمت آنها خیلی گران بود، حتی کمپوت گلابی که قیمتش ۲۵ تومان بود و از همه ارزان تر بود را نمی توانستم بخرم.\r\nآخر پول ما به اندازه سیر کردن شکم خانواده هم نیست . در راه برگشت کنار خیابان این قوطی خالی کمپوت را دیدم برداشتم و چند بار با دقت آن را شستم تا تمیز تمیز شد. حالا یک خواهش از شما برادر رزمنده دارم، هر وقت که تشنه شدید با این قوطی آب بخورید تا من هم خوشحال بشوم و فکر کنم که توانستم به جبهه ها کمکی کنم.\r\nبچه ها تو سنگر برای خوردن آب توی این قوطی نوبت می گرفتند، آب خوردنی که همراهش ریختن چند قطره اشک بود...\r\n"},{"id":1318,"category_id":9,"category_code":"s9","source_id":155,"title":"هشت دقیقه","content":"نگاه ها همه بر روی پرده سینما بود...\r\nاکران فیلم شروع شد، شروع فیلم، تصویری از سقف یک اتاق بود.\r\nدو دقیقه بعد همچنان سقف اتاق…سه،چهار، پنج……..،\r\nهشت دقیقه اول فیلم فقط سقف اتاق!\r\nصدای همه در آمد...\r\nاغلب حاضران سینما را ترک کردند!\r\nناگهان دوربین حرکت کرد و آمد پایین و به جانباز قطع نخاع خوابیده روى تخت رسید.\r\nدر آخر زیرنویس شد؛ این تنها ۸ دقیقه از زندگى این جانباز بود...!\r\n"},{"id":1319,"category_id":9,"category_code":"s9","source_id":156,"title":"چقدر میشه؟","content":"ماموریت ما تمام شد، همه آمده بودند جز «بخشی».بچه خیلی شوخی بود.همه پکر بودیم.اگر بود همه مان را الان می خنداند.یهو دیدیم دونفر یه برانکارد دست گرفته و دارن میان.یک غواص روی برانکارد آه و ناله میکرد.شک نکردیم که خودش است.تا به ما رسیدند بخشی سر امدادگر داد زد: نگه دار!\r\nبعد جلوی چشمان بهت زده ی دو امدادگر پرید پایین و گفت:«قربون دستتون! چقدر میشه؟!!» و زد زیر خنده و دوید بین بچه ها گم شد.به زحمت،امدادگرها رو راضی کردیم که بروند!!\r\n"},{"id":1320,"category_id":9,"category_code":"s9","source_id":157,"title":"پنج سال...","content":"وقتی می رفتند پیش حاجی برای مرخصی، میگفت:«من پنج ساله پدر و مادرم رو ندیدم..شما هنوز نیومده کجا میخواین برین؟!»\r\n کلی سرخ و سفید می شدند و از سنگر می آمدند بیرون.ما هم می خندیدیم بهشان.بنده های خدا نمی دانستند پدر و مادر حاجی پنج سال است فوت شده اند!!\r\n"},{"id":1321,"category_id":9,"category_code":"s9","source_id":158,"title":"سر و صدا","content":"بیست نفرهم نمی شدیم که صدای تانک هاشان آمد.حسن رحیمی فرمانده مان دادزد همه از سنگرها بیرون.فکر کردیم میخواهد فرمان حمله یا عقب نشینی بدهد.\r\n-شروع کنید به سرو صدا کردن، هم دیگه رو صدا کنید زود باشید!\r\nتکبیرها و داد و فریادها همان،عقب نشینی آنها همان..فکر کرده بودند خیلی زیادیم!\r\n"},{"id":1322,"category_id":9,"category_code":"s9","source_id":159,"title":"نماز","content":"تو گردان شایعه شد. نماز نمی خونه! گفتن: «تو که رفیق اونی، بهش تذکر بده!» باور نکردم و گفتم: «لابد می خواد ریا نشه، پنهانی می خونه.»\r\nوقتی دو نفری توی سنگر کمین جزیره ی مجنون، بیست و چهار ساعت نگهبان شدیم با چشم خودم دیدم که نماز نمی خواند! توی سنگر کمین، در کمینش بودم تا سر حرف را باز کنم.\r\nـ تو که برای خدا می جنگی، حیف نیس نماز نخونی\r\nلبخندی و گفت: «یادم می دی نماز خوندن رو! \r\nـ بلد نیستی!؟\r\nـ نه، تا حالا نخوندم\r\nهمان وقت داخل سنگر کمین، زیر آتش خمپاره ی شصت دشمن، تا جایی که خستگی اجازه داد، نماز خواندن را یادش دادم. توی تاریک روشنای صبح، اولین نمازش را با من خواند. دو نفر نگهبان بعد با قایق پارویی که آمدند و جای ما را گرفتند. سوار قایق شدیم تا برگردیم.\r\nپارو زدیم و هور را شکافتیم. هنوز مسافتی دور نشده بودیم که خمپاره شصت توی آب هور خورد و پارو از دستش افتاد. آرام که کف قایق خواباندمش، لبخند کم رنگی زد\r\nبا انگشت روی سینه اش صلیبی کشید و چشمش با آسمان یکی شد...\r\n"},{"id":1323,"category_id":9,"category_code":"s9","source_id":160,"title":"بند پوتین","content":"اندازه پسر خودم بود، سیزده، چهارده ساله. وسط عملیات یک دفعه نشست. گفتم: «حالا چه وقت استراحته بچه؟» گفت: «بند پوتینم شل شده، می بندم راه می افتم.»\r\nنشست ولی بلند نشد. هر دو پایش تیر خورده بود. برای روحیه ما چیزی نگفته بود.\r\n"},{"id":1324,"category_id":9,"category_code":"s9","source_id":161,"title":"معلم کلاس","content":"داشتم می رفتم سر کلاس. برعکس همیشه صدایی از کلاس نمی آمد. در را بازکردم دیدم هیچ کس نیست. روی تخته نوشته بود: «بچه های کلاس دوم فرهنگ همگی رفته اند جبهه. کلاس تا اطلاع ثانوی تعطیل است.» من هم دیدم جایز نیست بمانم. شاگرد برود معلم بماند!؟"},{"id":1325,"category_id":9,"category_code":"s9","source_id":162,"title":"یک عمر...","content":"دقيقه قبل از اينكه برم يكي ديگه اومد نشست بغل دستم ، گفت : آقا يه خاطره برات تعريف كنم ؟ گفتم : بفرماييد! \r\nيه عكسي به من نشون داد ، يه پسر مثلاً 19 ، 20 ساله اي بود ، گفت : اين اسمش عبدالمطلب اكبريه ، اين بنده خدا زمان جنگ مكانيك بود ، در ضمن كر و لال هم بود.\r\nيه پسر عموش هم به نام «غلام رضا اكبري» شهيد شده ، غلام رضا که شهيد شد ، عبدالمطلب اومد سر قبر غلام رضا نشست ، بعد هي با اون زبون كر و لالي خودش ، با ما حرف مي زد ، ما هم گفتيم : چي مي گي بابا !؟ محلش نذاشتيم ، هرچي سر و صدا كرد هيچ كس محلش نذاشت . وقتی ديد ما نمي فهميم ، بغل دست قبر اين شهيد با انگشتش يه دونه چارچوب قبر كشيد و روش نوشت : شهيد عبدالمطلب اكبري ، بعد به ما نگاه كرد و گفت: نگاه کنید!\r\nبعدش هم خندید! ما هم خنديدیم. گفتیم حتما شوخیش گرفته، اون طفلك هم هيچي نگفت ، سرش رو انداخت پائين و يه نگاهي به سنگ قبر كرد و با دست، نوشته اش رو پاك كرد ، سرش رو پائين انداخت و آروم رفت . فرداش هم رفت جبهه . 10 روز بعد جنازه اش رو آوردند دقيقاً تو همون جايي كه با انگشت كشيده بود خاكش كردند . وصيت نامه اش خيلي كوتاه بود ، اينجوري نوشته بود:\r\n\r\nبسم الله الرحمن الرحيم\r\nيك عمر هرچي گفتم به من مي خنديدند ، يك عمر هر چي مي خواستم به مردم محبت كنم ، فكر كردند من آدم نيستم ، مسخره ام كردند ، يك عمر هرچي جدي گفتم ، شوخي گرفتند ، يك عمر كسي رو نداشتم باهاش حرف بزنم ، خيلي تنها بودم.\r\nاما مردم ! حالا كه ما رفتيم بدونيد هر روز با آقام حرف مي زدم ، و آقا بهم گفت : تو شهيد مي شي . جاي قبرم رو هم بهم نشون داد ، اين رو هم گفتم اما باور نكرديد!\r\n"},{"id":1326,"category_id":9,"category_code":"s9","source_id":163,"title":"سیبل سوراخ سوراخ","content":"بلندقد و هیکلی. توی مدرسه دروازه بان بود. همیشه وقتی به او می رسیدیم، می گفتم: تو با این هیکلت خیلی تابلویی، آخرش هم سیبل میشی!\r\nگذشت تا عملیات فاو. از رودخانه که گذشتیم خوردیم به سیم خاردارهای حلقوی. دشمن آتش می ریخت. نزدیک بود قتل عام بشویم که دیدم ستون حرکت کرد. جلوتر که رفتیم دیدم یک نفر خودش را انداخته روی سیم خاردار. بلندقد و هیکلی. از عملیات که برگشتیم، روی همان سیم خاردارها تابلو شده بود. مثل یک سیبل سوراخ سوراخ.\r\n"},{"id":1327,"category_id":9,"category_code":"s9","source_id":164,"title":"فدای سرت","content":"بیشتر از بیست سال بود که روی تخت می خوابید . 70 درصد بود. از گردن به پایین قطع نخاع بود. دکترای حقوق داشت.\r\nحتی خانواده اش فراموشش کرده بودن. لبخند می زد. حتی از زخم بستر هم شکایت نمی کرد.\r\nیک بار، ناگهان همه ی بدنش شروع به لرزیدن کرد ، حتی تخت هم می لرزید. منم می لرزیدم.\r\nرفتم عقب، سرمو پایین انداختم. از خودم شرمنده بودم. گریم گرفت.\r\nدعوام کرد گفت:\r\nرفتم جنگیدم تا تو گریه نکنی! فدای سرت.\r\n"},{"id":1328,"category_id":9,"category_code":"s9","source_id":165,"title":"مسافر بی سر","content":"همسرش می گفت او برگشته است برای خاطر مظلومیت و تنهایی رهبر. توی حرف هایش هم اما و اگر نداشت. یک جمله ی خبری کامل بود که اصلا به اینکه غیرت ما ممکن است یک طوری اش بشود اهمیت نمی داد. انگار راست می گفت . اینکه او سرش را هم جا گذاشته و نیاورده با خودش شاید نشانه ای باشد بر شتاب اضطرار ایام.\r\nآن طرف تر هم بانویی از عربستان از رهبرش می گفت. رهبری که یک روزی از خاک های نرم کوشک گفته بود و این شده بود اول قصه آشنایی با عبد الحسین برونسی که حالا رسیده بود به مشهد و این زن هم از عربستان خودش را رسانده بود به مراسم استقبال از مسافر بی سر.\r\n"},{"id":1329,"category_id":9,"category_code":"s9","source_id":166,"title":"تولدت مبارک","content":"میدونی...!\r\n\r\nحالا که روزتولدته من و آبجی می خواستیم قشنگ ترین هدیه رو برات بخریم ولی نمی دونستیم چی بخریم.\r\nدختر خاله می گفت برات یه دست کامل لوازم آرایش بخریم.\r\nمی گفت اگه مامانت آرایش کنه زخم های روی صورتش کمتر معلوم می شه...\r\nمی گفت:\r\nزشته یه معلم با سرو صورت زخمی سر کلاس بره\r\nمی گفت:\r\nشاگردهاش می فهمند شوهرش...\r\nمیدونم تو هیچ وقت برای خودت از این چیزها نمی خری\r\nآخه همش رو می دی پول دارو و بیمارستان بابا\r\nبابا هم که تو رو کتک میزنه\r\nفحش می ده\r\nحرف هایی می زنه که ما نمی فهمیم\r\nفقط می بینیم و گریـــــه می کنیم.من و آبجی خوب می فهمیم که وقتی بابا موجی می شه تو دستای مارو می گیری و می بری تو اتاق دیگه.\r\nبعد می ری تا بابا کتکت بزنه\r\nو موهای قشنگتو بکشه.\r\nمن و اون خوب می دونیم چرا این کارو می کنه.\r\nآخه اگه تو نری جلوی بابا اون خودشو می زنه\r\nفقط تو رو خدا این دفعه بذار بابا ما رو جای تو کتک بزنه... دست خودش نیست...تو هم چون بابا رو خیلی دوست داری نمی خواهی بابا خودشو بزنه...\r\nبه قول خودت یه ذره از سهمت و فداکاری هاش رو میدی\r\nاز ترکش های توی بدنش\r\nاز موجی شدنش\r\nاز...\r\nما می فهمیم که وقتی بابا آروم می شه سرش رو می گیره و چقدر گریه می کنه\r\nوقتی می فهمه چیکار کرده ناراحت می شه\r\nدستت رو می بوسه...تو هم گریه می کنی...\r\nمن و آبجی صدای گریه تو و بابا رو می شنویم.مامان جون!مامان خوب و قهرمانم!\r\nپس سهم ما چی می شه؟\r\nما هم می خوایم مثل تو و بابا قهرمان باشیم\r\nمی خوایم روز تولدت پول هامون رو بدیم به تو تا برای بابا دوا بخری\r\nفقط تو رو خدا این دفعه بذار بابا ما رو جای تو کتک بزنه...\r\nمامان جون، تولدتـــــــــ مبارکـــــــــــــــــ\r\n"},{"id":1330,"category_id":9,"category_code":"s9","source_id":167,"title":"پسر","content":"فرمانده نمی گذاشت بیاید. می گفت کوچک است. می گفت می ترسد و بقیه را لو می دهد. پسر گریه و زاری کرد، بقیه هم پادرمیانی کردند.\r\nفرمانده گفت: من مسئولیت قبول نمی کنم. یکی مسئولیتش را قبول کنه\r\nپسر، فرمانده زخمی را گرفته بود روی دوشش\r\nمی گفت: نترس\r\nمی گفت: می رسانمت\r\nمی گفت: گریه زاری نکن، لو می رویم\r\nمی گفت: من مسئولم شما را برسانم عقب، چاکرت هم هستم\r\n"},{"id":1331,"category_id":9,"category_code":"s9","source_id":168,"title":"کمک","content":"مهمات تمام شده بود. حاجی بی سیم زد ولی بی فایده بود. از شب قبل نه کمکی آمده بود نه مهماتی.\r\n- خدایا! هیچ کس نمی تونه کمک بکنه. یقه کی رو بگیرم جز تو؟\r\nتوی آن تاریکی زد به بیابان و داد می زد.\r\nزیر پایش خالی شد. افتاد داخل حفره ای بزرگ خواست بلند شود، درد پیچید توی پایش.\r\nپایش را دراز کرد. پوتین هایش روی خاک کشیده شد و نرمه خاک روی پلاستیک نشست روی جعبه. بازش کرد. جعبه دوم، جعبه سوم. همه شان پر بود. عراقی ها نتوانسته بودند انبار مهماتشان را قبل از فرار منفجر کنند.\r\n"},{"id":1332,"category_id":9,"category_code":"s9","source_id":169,"title":"خلوتگاه","content":"نزدیک طلوع آفتاب بود. با پا زدم به پهلوی یکی از بچه ها برای نماز صبح. بلند نشد. پتو را زدم کنار دیدم نیست. شک کردم. به بچه ها گفتم.\r\nفردا شب منتظر ماندم. دیدم از سنگر می رود بیرون. جایش را هم طوری درست می کند که کسی نفهمد او نیست. دنبالش رفتم. سنگرهای خودی را دور زد و رفت سمت عراقی ها. شکم بیشتر شد. رسید به خرابه ای، داخل شد و بیرون نیامد. برگشتم. صبح بعد از طلوع آفتاب یواشکی رفتم خرابه. دیدم قبر کوچکی است و سجاده و قرآن و شمعی که تا نصفه آب شده.\r\n"},{"id":1333,"category_id":9,"category_code":"s9","source_id":170,"title":"فردا","content":"رسیدیم دوکوهه. نصفه شب بود. گفتم: «من و حاجی شام نخوردیم ها\r\nرفتند دو بشقاب برنج آوردند و دو تا تن ماهی. حاجی گفت: «بچه ها چی خوردند\r\nگفتند: از همین\r\nگفت: راست بگید\r\nگفتند: همین، فقط تن را فردا می خورند\r\nحاجی قاشق را گذاشت توی بشقاب و گفت ما هم فردا می خوریم.\r\n"},{"id":1334,"category_id":9,"category_code":"s9","source_id":171,"title":"گونی","content":"گونی بزرگی را گذاشته بود روی دوشش و توی سنگرها جیره پخش می کرد.\r\nبچه ها هم با او شوخی می کردند:\r\n- اخوی دیر اومدی\r\n- برادر می خوای بکشیمون از گشنگی؟\r\n- عزیز جان! حالا اول می ری شنگر فرماندهی برای خودشیرینی؟\r\nگونی بزرگی بود و سر آن بنده خدا پایین\r\nکارش که تمام شد. گونی را که زمین گذاشت همه شناختندش. کاوه (محمود کاوه). فرمانده لشکر بود.\r\n"},{"id":1335,"category_id":9,"category_code":"s9","source_id":172,"title":"صدای پا","content":"میگفت نرم قدم بردارید\r\nزمین را نکوبید\r\nمیگفت بالاخره\r\nقرار است با زمین\r\nهم*سر و سایه شویم\r\nاز حالا رعایت کنید\r\nصدای پایش را\r\nهیچ کس نشنیده بود\r\nالا روز آخر\r\nکه همه شنیدند\r\n...\r\nمیدوید\r\nدر میدان مین\r\n"},{"id":1336,"category_id":9,"category_code":"s9","source_id":173,"title":"تک تیرانداز","content":"تک تیراندازمان را صدا زدم. با دست سنگری را نشانش دادم و گفتم: اوناهاش اونجاس.\r\nاسلحه اش را برداشت. از دوربین اسلحه نگاه کرد. نشانه گرفت، نفسش را حبس کرد. انگشت اشاره را گذاشت روی ماشه... یک دفعه انگشتش را برداشت. اسلحه را پایین آورد.\r\nچند لحظه بعد دوباره نشانه گرفت و شلیک کرد. گفتم: چرا دفعه اول نزدی؟\r\nگفت: داشت آب می خورد.\r\n"},{"id":1337,"category_id":9,"category_code":"s9","source_id":174,"title":"چهار دست و پا","content":"وارد شهرهای عراق، حلبچه و خرمال و طویله که شدیم وضع مردم خیلی بد بود. سوارشان می کردیم و می بردیم جای امن. زن ها و بچه ها نمی توانستند سوار کامیون های آیفا شوند. یک نفر چهار دست و پا نشسته بود تا زن ها و بچه ها راحت بتوانند سوار شوند. سرش را بلند کرد شناختمش. راننده بود. آن هم کدام راننده. راننده همیشه شاکی."},{"id":1338,"category_id":9,"category_code":"s9","source_id":175,"title":"آن جوان","content":"ناگهان دیدم جوانی به طرف ما آمد و گفت: \"لا اله الّا الله، محمد رسول الله (صلّی الله علیه و آله و سلّم)\" اول جا خوردیم و روی زمین دراز کشیدیم جلوتر که آمد دیدم از بسیجی های مخلص است. گفتم: برادر چه شده است؟ به کجا می روی؟\r\nگفت: ترکش خورده ام، کمک می خواهم\r\nدرآن تاریکی شب دستش را دراز کرد و گفت: مثل اینکه این دست من در اثر ترکش قطع شده است و به یک پوست بند است. آنرا بگیر و بکش، اگر کنده شود، خودم می توانم به عقب بروم\r\nبه شهید ابوالقاسم معینی گفتم: تو این کار را بکن\r\nگفت: من طاقتش را ندارم، اگر می توانی کمکش کن\r\nدستش را کشیدم و جدا کردم حتی یک تکان هم نخورد. بعد دست قطع شده را از من گرفت و همان طور که از محل قطع شدن خون بیرون می جست، آن را روی خاک گذاشت. با یک دست دیگر سر به سجده نهاد سپس نماز شکر گزارد و گفت: خدایا قبول کن، من این دست را در راه امام حسین (علیه السّلام) دادم\r\nبعد پرسید . از اینجا تا کربلا چقدر راه است شهید معینی آن قدر گریه کرد که نتوانست جوابش را بدهد . او پیشانی معینی را بوسید وگفت : محکم واستوار باشید و رفت\r\nوقتی به سنگر رسیدیم معینی خیلی تحت تاثیر قرار گرفته بود. وضو ساخت و به نماز شب ایستاد وقتی دلیلش را پرسیدم.\r\nگفت: او با یک دست سجده کرد و من که دو دست داشتم بسیار شرمنده ایثار او شدم بنابرین می خواهم هر شب به یاد او نماز شب بخوانم.\r\n"},{"id":1339,"category_id":9,"category_code":"s9","source_id":176,"title":"ای خدا","content":"توی نماز جماعت یکی از بچه ها وسط گریه توی قنوت یک دفعه با صدای بلند گفت: \"ا...ی...خد...ا!\"\r\nبعد از نماز همه برگشتند و نگاهش کردند. تا مدت ها هر وقت می دیدیمش داد می زدیم: چطوری ای خدا!\r\nاو هم می گفت: چه غلطی کردیم ها! بابا ولم کنید، با خدا بودم، با شما که نبودم.\r\n"},{"id":1340,"category_id":9,"category_code":"s9","source_id":177,"title":"مرخصی","content":"سال 65 بود و دخترمان يك سال و خرده اي داشت. رسول از جبهه آمده بود مرخصي، بعد از شش ماه، خانه مادرش بوديم. چند بچه هم سن و سال دخترمان هم آنجا بودند. وارد كه شد، پرسيدم: كدام يكي از اينها دخترمان است؟\r\nچند لحظه نگاهشان كرد؛ خنديد و سكوت كرد.\r\n"},{"id":1341,"category_id":9,"category_code":"s9","source_id":178,"title":"با چه معامله می کنیم؟","content":"و یاد برادرانی افتادم که در والفجر 8 آموزش غواصی می دیدند، آن هم در زمستان، شبی 6 - 7 ساعت در آب سرد بودند و وقتی که از آب بیرون می آمدند، پنجه هایشان از شدت سرما قفل می شد و بعضی که شهید شدند، گاهی با 40 درجه تب، داخل آب می شدند و یکی شان می گفت که در آب هم عرق می کنم؛ ولی وقتی می گفتند امشب استراحت کن، پاسخ می داد که مسئله آزاد کردن کل بشریت و اجرای احکام دین است؛ آنان این گونه بودند. از آب اروند که بچه ها می خواستند عبور کنند، یکی از برادران غواص به دیگری - که هر دو شهید شدند - گفت: جایی که ما آموزش دیده ایم، عرض آب این قدر نبود؛ شدت آب هم این قدر نبود؛ این جا کوسه دارد؛ امشب چه می شود؟ آن دهاتی 19 ساله پاسخ داد: تو ابتدا توحید خود را اصلاح کن؛ چون اگر این طرف اروند دلت آرام است و آن طرف اروند ناراحت هستی، معلوم می شود که خدای این طرف اروند را خدای آن طرف نمی دانی. به او گفت: ما امشب وارد آب می شویم و اگر عراقی ها ما را نزنند، کوسه ها می زنند و اگر کوسه ها نزنند، آنها می زنند. اگر هیچ کدام نزنند، ما لابه لای تله های انفجاری گرفتار می شویم؛ ولی من امشب وارد آب می شوم تا به امام خبر بدهند که بچه ها به آب زدند. امام باید از ما راضی باشد. می گفت: اصلاً برایم مهم نیست که از آب بیرون بیایم؛ برای من مهم است داخل آب بشوم. مگر چند نمونه از این بچه ها در کل تاریخ ایران بوده اند که ما با خون این بچه ها این قدر راحت معامله می کنیم؟"},{"id":1342,"category_id":9,"category_code":"s9","source_id":179,"title":"جلسه ی خانوادگی","content":"توی لشکر امام حسین علیه السلام بودم که خبر آوردند بابام هم آمده. دوهفته بعد هم دو تا داداش ها. فقط مانده بود ننه مان. یک جلسه خانوادگی گذاشتیم. تصمیم گرفتیم او را هم بیاوریم اهواز تنها نباشد. همین هم شد. می گفتند خانوادگی رفته اند جبهه."},{"id":1343,"category_id":9,"category_code":"s9","source_id":180,"title":"هیکل درشتت...","content":"پایش را توی یک کفش کرده بود که برود. دلیل و اما و اگرهای پدر و مادر و فامیل هم افاقه نکرد. روز اعزام پای اتوبوس یکی گفته بود :\r\nفلانی با این هیکل درشتت اگر شهید بشوی نمی شود توی تابوت بلندت کرد. تازه اگر تابوت اندازه ات پیدا شود محض کمر درد ما هم که شده از خیر جبهه بگذر!\r\nخندید و سر بلند کرد به آسمان که خدایا بار ما نیفتد روی دوش مردم ها!\r\nوقتی برگشت روی هیج شانه ای باری نیفتاد . بعد 30 سال چارپاره استخوان وزنی نداشت که. انگار خودش پر درآورده باشد. بی دردسر بال میزد تا مدفنش.\r\n"},{"id":1344,"category_id":9,"category_code":"s9","source_id":181,"title":"زخمی در خاک دشمن","content":"شناسنامه خانقيني داشت! آنقدر در داخل خاك عراق مانده بود كه با انواع و اقسام گروه هاي كومله، دموكرات، معاند حزب بعث و غيره آشنايي كامل داشت. يك بار از او پرسيدم اگر گير دموكرات بيفتي چه كار مي كني؟ كارت شناسايي دموكرات را نشانم داد. گفتم گير كومله بيفتي چه؟ كارت آنها را نيز داشت. يك بار هم همان جا با اشتباه يكي از كردهاي عراقي زخمي شد كه چهار گلوله درست به قسمت رانش خورده بود. فقط خدا مي داند چطور توانست در آن غربت خودش را به عقب بكشاند. رسول در يكي از دست نوشته هايش بهترين توصيف را از اين حالش دارد؛\r\n«زخمي و ۲۰۰ كيلومتر دورتر از خاك جمهوري اسلامي هستم. راديو را گوش دادم، داشت نوحه اي براي امام حسين(ع) پخش مي كرد. خيلي دلم گرفت… زخمي در اعماق خاك دشمن.\r\n"},{"id":1345,"category_id":9,"category_code":"s9","source_id":182,"title":"قناسه چی","content":"یک قناسه چی ایرانی که به زبان عربی مسلط بود اشک عراقی ها را درآورده بود. با سلاح دوربین دار مخصوصش چند ده متری خط عراقی ها کمین کرده بود و شده بود عذاب عراقی ها. چه می کرد؟\r\nبار اول بلند شد و فریاد زد: «ماجد کیه؟» یکی از عراقی ها که اسمش ماجد بود سرش را از پس خاکریز آورد بالا و گفت: منم\r\nترق!\r\nماجد کله پا شد و قل خورد آمد پای خاکریز و قبض جناب عزراییل را امضا کرد! دفعه بعد قناسه چی فریاد زد: «یاسر کجایی؟» و یاسر هم به دست بوسی مالک دوزخ شتافت!\r\nچند بار این کار را کرد تا این که به رگ غیرت یکی از عراقی ها به نام جاسم برخورد. فکری کرد و بعد با خوشحالی بشکن زد و سلاح دوربین داری پیدا کرد و پرید رو خاکریز و فریاد زد: «حسین اسم کیه؟» و نشانه رفت. اما چند لحظه ای صبر کرد و خبری نشد. با دلخوری از خاکریز سرخورد پایین. یک هو صدایی از سوی قناسه چی ایرانی بلند شد: «کی با حسین کار داشت؟» جاسم با خوشحالی، هول و ولا کنان رفت بالای خاکریز و گفت: \"من\"\r\nترق!\r\nجاسم با یک خال هندی بین دو ابرو خودش را در آن دنیا دید!\r\n"},{"id":1346,"category_id":9,"category_code":"s9","source_id":183,"title":"نمازی که ...","content":"تو پایگاه کانی باغ (پسوه) و توی سنگر ی که برای مسجد در نظر گرفته شده بود پشت سر یکی از بچه ها قامت بستیم و نماز مغرب رو شروع به خوندن کردیم که صدای تیر اندازی بی امان نگهبان ها شروع شد . تا اون موقع سابقه نداشت که نگهبانا تو هیچ زمانی تیراندازی کنند . سجده اول رو که به جا آوردیم شدت تیر اندازی هم بیشتر شد فرمانده که صف اول نماز بود نمازش رو شکست و از نمازخونه با عجله بیرون رفت . تو سجده دوم بودیم که صدای یکی از سربازان شنیده شد که داد می زد بچه ها جناب سروان می گه زودتر بیان به پایگاه حمله شده .\r\nرکعت بعدی هم با عجله خونده شد و همه سراسیمه بیرون زدیم . صدای شلیک خمپاره و توپ هم که از مقر توپخانه خودی شلیک می شد و به اطراف پایگاه اصابت می کرد حمله رو خیلی جدی نشون می داد . وقتی خودم رو به حمید تیرانداز کالیبر 50 رسوندم در حالیکه مدام شلیک می کرد گفت : از روی جمیلان یه مسلسل هست که باید اونو خاموش کنم والا تک تک بچه ها رو می زنه . گفتم مشکلی نداری گفت نه فقط بگین فشنگ برسونن .\r\nبا عجله خودمو به سنگر اسلحه خونه و مهمات رسوندم وضعیت شلوغ شده بود از اسلحه دار خواستم یه جعبه فشنگ کالیبر 50 زودتر به سنگر کالیبر ببرند و حمید رو تقویت کنند .\r\nپایگاه صید آباد که سمت چپ ما بود بدتر از ما ، درگیر پاسخ حمله به گروهک ها قرار گرفته بودند و اونا هم حسابی داشتند از پایگاه خودشون دفاع می کردند .\r\nسعی کردم به سنگرهای دور پایگاه سر بزنم تا هم سربازا روحیه بگیرن و هم وضعیت حمله کننده ها رو بدونم .\r\nنیروهای حمله کننده با لباس سیاه از تاریکی شب استفاده کرده بودند و خودشون رو به نزدیکی های پایگاه رسونده بودند ولی هشیاری نگهبانهای پایگاه اونا رو به عقب رونده بود ولی دست بردار نبودند .\r\nبه سنگر یکی از بچه های لر که رسیدم دیدم داره با صدای بلند آواز می خونه و مدام به سمت دشمن شلیک می کنه . دستی به پشتش زدم و گفتم چه خبر ؟! حالا چه وقت خوندنه ؟!\r\nگفت : بخدا روحیه شون رو بردیم زیر صفر اگر کمی شل می جنبیدیم الان پایگاه رو گرفته بودن .\r\nگفتم دستت درد نکنه خدا خیرت بده با این روحیه خوبت .\r\nخلاصه درگیری ها تا ساعت 10 و ربع شب ادامه داشت و بعد از اون ، هم پایگاه صید آباد آروم شد و هم پایگاه ما .\r\nفرمانده پایگاه وقتی کاملا خیالش از درگیری راحت شد بچه ها رو برای خوندن نمازعشاء به نمازخونه دعوت کرد و بعد ازاینکه نماز رو با جماعت با ما خوند نماز شکستش رو هم بجا آورد و گفت : بچه ها امشب خیلی گل کاشتید دست همه تون درد نکنه ولی بازم باید هشیار باشید ممکنه دشمن دوباره حمله کنه . من علاوه بر نظارت پایگاه همش با بیسیم با پادگان در ارتباط بودم هدف اونا گرفتن پایگاه صید آباد بود که بحمد الله موفق نشدند حمله به ما هم برای این بود که نتونیم به پایگاه صید اباد کمک کنیم که با هشیاری خوب شما دشمن با تلفات زیاد مجبور به عقب نشینی شد. وضعیت در پایگاه صید آباد بحرانی تره و چند نفر ازسربازا زخمی شدند . امشب کاملا با هشیاری و مراقبت کامل تو سنگرها باشید تعداد نگهبانها رو دوبرابر کنید .شما چون ایمان دارید مطمئن باشید که همیشه پیروزید .\r\nخلاصه اون شب هم گذشت و دشمن دیگه هیچوقت جرات حمله به پایگاه رو به خودش نداد.\r\n"},{"id":1347,"category_id":9,"category_code":"s9","source_id":184,"title":"پا در شکم جنازه ","content":"همان طور که بین شهدا چرخ می زدم، یکهو احساس کردم پایم در چیزی فرو رفت. موهای تنم سیخ شد. جرأت نداشتم تکان بخورم یا دستم را به طرف پایم ببرم. لیزی و رطوبتی توی پایم حس می کردم که لحظه به لحظه بیشتر می شد. یک دفعه یخ کردم. با این حال دانه های عرق از پیشانی ام می ریخت. آرام دستم را پایین بردم و به پایم کشیدم. وقتی فهمیدم چه اتفاقی افتاده است، تیره پشتم تا سرم تیر کشید و چهار ستون بدنم لرزید. پایم در شکم جنازه ایی که امعاء و احشایش بیرون ریخته بود، فرو رفته بود. به زحمت پایم را بالا آوردم. سنگین و کرخت شده بود. انگار مال خودم نبود. کشان کشان تا دم تکه زمین خاکی آمدم. پایم را از کفش درآوردم و روی زمین کشیدم."},{"id":1348,"category_id":9,"category_code":"s9","source_id":185,"title":"یک شب با او خواهم بود","content":"در سال ۱۳۴۸ وارد نیروی هوایی شدم . در بدو ورود می بایستی یک سری آموزشها را در نیروی هوایی می دیدیم که از آن جمله آموزش زبان انگلیسی بود.این کلاس ها شروع آشنایی چندین ساله ی من با عباس بابایی بود...\r\nایشان شخصیت خاصی داشتند واز همه متمایز بودند. در آن دوران بیشتر استادان زن بودند از جمله استاد کلاس زبان که یک زن آمریکایی بود.\r\nاین استاد زبان برای اینکه فرهنگ مبتذل غرب را رواج دهد،به دانشجویان پیشنهاد شرم آوری داد که، اگر کسی امتحان پایان ترم را ۲۰ بگیرد من یک شب با او خواهم بود. بعد از اعلام نمرات عباس ازهمه نمره اش بیشتر بود او امتحان را ۱۹ گرفته بود. من برگه او را که دیدم تعجب کردم زیرا او یک کلمه ساده را غلط نوشته بود .\r\nو آن استاد هم به عباس گفت: تو عمدأ این کلمه را غلط نوشته ای تا با من نباشی. آنجا بود که من به عظمت روحی عباس پی بردم. ایشان با این کار درس تقوا و عفت و بزرگواری را به دیگران آموخت...\r\n\r\nراوی عظیم دربند سری یکی از دوستان قدیمی شهید بابایی\r\n"},{"id":1349,"category_id":9,"category_code":"s9","source_id":186,"title":"پس گردنی","content":"روحانی لشکر سخنرانی می‌کند. حاج همت تازه گرم شنیدن صحبت‌های او شده که بازهم مردی از مقابلش می‌گذرد و مثل همیشه سلام می‌کند. حاج همت هم مثل همیشه جوابش را می‌دهد و مثل همیشه در فکر فرو می‌رود تا او را بشناسد؛ اما هرچه به مغزش فشار می‌آورد، او را به جا نمی‌آورد. چندبار تصمیم گرفته موضوع را از خودش بپرسد، اما نیرویی از درون مانع این کار شده. حاج همت هر وقت آن مرد را می‌بیند، چیزی شبیه به شرم و گناه در خود احساس می‌کند، اما چه شرم و گناهی، خودش هم نمی‌داند. \r\n\r\nروحانی لشکر می‌گوید: «پیامبر اکرم (ص) در روزهای آخر عمر خود به مسجد آمد و فرمود: هرکس حقی به گردن من دارد، برخیزد و طلب کند؛ چرا که قصاص در این دنیا آسان‌تر از قصاص در روز رستاخیز است. \r\nمردی به نام سواده برخاست و گفت: یا رسول الله، یک روز بر شتری سوار بودی. وقتی تازیانه‌ات را در هوا می‌چرخاندی، تازیانه به شکم من خورد. من حالا می‌خواهم قصاص کنم...» \r\n\r\nاین روایت، توجه حاج همت را به خود جلب می‌کند. با اشتیاق به ادامه حرفهای روحانی گوش می‌دهد. روحانی ادامه می‌دهد: «پیامبر اکرم (ص) خودش را برای قصاص آماده کرد. سواده گفت: یا رسول الله، آن روز تن من برهنه بود. رسول خدا پیراهنش را بالا زد و گفت: قصاص کن. سواده خودش را به رسول خدا رسانید و او را در آغوش گرفت و عاشقانه شکم و سینه‌اش را بوسید. همه اهل مسجد به گریه افتادند...» \r\n\r\nحاج همت به گریه می‌افتد. ناگهان چیزی در ذهنش مثل پتک ضربه می‌زند. چهره آن مرد مثل یک تابلو در طاقچه ذهنش ثابت می‌ماند. حاج همت به هر طرف که می‌چرخد آن مرد را می‌بیند. از شرم و عذاب وجدان، سرش را پایین می‌اندازد و از حسینیه خارج می‌شود. \r\n\r\nجمله پیامبر (ص) مثل زنگی پی در پی در ذهن حاج همت نواخته می‌شود: هرکس حقی به گردن من دارد، برخیزد و طلب کند؛ چرا که قصاص در این دنیا آسان‌تر از قصاص در روز رستاخیز است. \r\n\r\nتن حاج همت داغ می‌شود و ضربان قلبش شدت می‌گیرد. او بیقرار است. اطرافیان از حالت غیرعادی او تعجب می‌کنند و با نگرانی به هم چیزهایی می‌گویند، اما حاج همت متوجه هیچ کس نیست. او تنها به آن مرد فکر می‌کند. وقتی سخنرانی روحانی تمام می‌شود، بدون اینکه با کسی حرفی بزند، به حسینیه بر می‌گردد و در تاریکی منتظر خروج آن مرد می‌ماند. \r\n\r\nنکته‌ای را از قبل به یاد می‌آورد\r\nچیزی به پیروزی انقلاب نمانده بود. وقتی امام خمینی فرمان راهپیمایی داد، بیشتر مردم به خیابان‌ها ریختند. ساواکی‌ها قدرت خودشان را از دست داده بودند. در عوض، عده‌ای فرصت طلب، قدرت گرفته بودند. آن‌ها خودشان را انقلابی جا می‌زدند. وقتی راهپیمایی می‌شد، به میان جمعیت آمده، شعارهای مردم را عوض می‌کردند. آن‌ها به جای امام، کس دیگری را رهبر معرفی می‌کردند. بعضی وقت‌ها با این کارشان بین مردم تفرقه می‌انداختند و باعث بهم خوردن راهپیمایی می‌شدند. \r\n\r\nحاج همت پی به توطئه آن‌ها برده بود و برای مقابله، شعارهای انقلابی را چاپ کرده و بین مردم پخش کرده بود. آن روز، یک نفر از پشت بلندگو شعار‌ها را می‌خواند و مردم تکرار می‌کردند. \r\n\r\nآن مرد، پیشاپیش حاج همت حرکت می‌کرد و همراه مردم شعار می‌داد. حاج همت مراقب اوضاع بود. ناگهان دستهای آن مرد بالا آمد و شعاری شنیده شد. در یک لحظه، نظم مردم به هم ریخت. چیزی نمانده بود که بی‌نظمی به همه جا سرایت کند.\r\n حاج همت در حالی که شعار اصلی راهپیمایی را با صدای بلند تکرار می‌کرد، به سمت آن مرد هجوم برد و یک پس گردنی به او زد. آن مرد از این کار حاج همت جا خورده بود، می‌خواست لب به اعتراض باز کند که با اعتراض دسته جمعی مردم مواجه شد. \r\n\r\nبا این برخورد حاج همت، شعار‌ها دوباره منظم شد و مردم به حرکت خود ادامه دادند. \r\n\r\nحاج همت بازهم مراقب اوضاع بود. در‌‌ همان لحظه، پیرمردی پیش آمد و درگوشی به او گفت: «چرا آن آقا را زدی؟» \r\n\r\n_چون شعار انحرافی داد. \r\n_با چشم خودت دیدی که او شعار داد؟ \r\n\r\nعرق، سر و روی حاج همت را فراگرفت و چهره‌اش از ناراحتی کبود شد. او با چشم خودش ندیده بود. پیرمرد ادامه داد: «آن کسی که شعار انحرافی داد، فرار کرد و رفت.» \r\n\r\nحاج همت دیگر صدای پیرمرد را نمی‌شنید. سراسیمه به دنبال مرد گشت؛ اما هرچه تلاش کرد، او را نیافت. \r\n\r\nچندین سال از آن ماجرا می‌گذرد. ‌ آن مرد حالا یکی از نیروهای لشکر حاج همت است؛‌‌ همان مردی که رو در روی حاج همت ایستاده و با نگاهی معنادار به او خیره شده. حاج همت هنوز از شرم و خجالت بیقرار است. او با صدای بلند از همه می‌خواهد که لحظه‌ای بمانند. \r\n\r\nمی‌گوید: «من به این مرد ظلم کرده‌ام. در حضور یک جمعیت ظلم کردم؛ اما حالا از حاضر کردن آن جمعیت عاجزم. از این مرد تقاضا دارم در حضور همین جمع، مرا قصاص کند.» \r\n\r\nپیش رفته، سرش را در مقابل مرد فرو می‌آورد. همه از رفتار او تعجب می‌کنند. منتظر عکس العمل مرد می‌مانند. مرد در حالی که بغض در گلو دارد دست می‌اندازد دور گردن حاج همت و گردنش را غرق بوسه می‌کند. حاج همت زانو زده، پاهای مرد را می‌بوسد. \r\nاشک در چشمان همه حلقه می‌زند...\r\n"},{"id":1350,"category_id":9,"category_code":"s9","source_id":187,"title":"سکه ی یه پول شدم","content":"حاجی مهیاری از آن پیرمردهای با صفا و سر زنده گردان حبیب بن مظاهر لشکر حضرت رسول بود. لهجه اصفهانی اش چاشنی حرفهای بامزه اش بود و لازم نبود بدانی اهل کجاست. کافی بود به پست ناواردی بخورد و طرف از او بپرسد: «حاجی بچه کجایی؟» آن وقت با حاظر جوابی و تندی بگوید: «بچه خودتی فسقلی، با پنجاه شصت سال سنم موگویی بچه؟»\r\nاز عملیات برگشته بودیم و جای سالم در لباس هایمان نبود. یا ترکش آستینمان را جر داده بود یا موج انفجار لباسمان را پوکانده بود و یا بر اثر گیر کردن به سیم خاردار و موانع ایذایی دشمن جرواجر شده بود. سلیمانی فرمانده گردانمان از آن ناخن خشک های اسکاتلندی بود! هر چی بهش التماس کردیم تا به مسئول تدارکات بگوید تا لباس درست و حسابی بهمان بدهد، زیر بار نرفت.\r\n- لباس هاتون که چیزی نیست. با یک کوک و سه بار سوزن زدن راست و ریس می شود!\r\nآخر سر دست به دامان حاجی مهیاری شدیم که خودش هم وضعیتی مثل ما داشت. به سرکردگی او رفتیم سراغ فرمانده گردانمان. حاجی اول با شوخی و خنده حرفش را زد. اما وقتی به دل سلیمانی اثر نکرد عصبانی شد و گفت: «ببین، اگه تا پنج دقیقه دیگه به کل بچه ها شلوار، پیراهن ندی آبرو واسه ات نمی گذارم!» سلیمانی همچنان می خندید. حاجی سریع خودکار دست من داد و گفت: یالله پسر، آنی پشت پیراهن من بنویس: حاجی مهیاری از نیروهای گردان حبیب بن مظاهر به فرماندهی مختار سلیمانی.»\r\nمن هم نوشتم. یک هو حاجی شلوار زانو جر خورده اش را از پا کند و با یک شورت مامان دوز که تا زانویش بود، ایستاد. همه جا خوردند و بعد زدیم زیر خنده. حاجی گفت: «الان میرم تو لشکر می چرخم و به همه می گویم که من نیروی تو هستم و با همین وضعیت می خواهی مرا بفرستی مرخصی تا پیش سر و همسر آبروم برود و سکه یه پول بشم!» بعد محکم و با اراده راه افتاد. سلیمانی که رنگش پریده بود، افتاد به دست و پا و دوید دست حاجی را گرفت و گفت: «نرو! باشد. می گویم تا به شما لباس بدهند!» حاجی گفت: «نشد. باید به کل گردان لباس نو بدهی. والله می روم. بروم؟» سلیمانی تسلیم شد و ساعتی بعد همه ما نو و نوار شدیم، از تصدق سر حاجی مهیاری!\r\n"},{"id":1351,"category_id":9,"category_code":"s9","source_id":188,"title":"شوخی کارساز","content":"در قسمتی از خاکریز خط مقدم جبهه انفجار گلوله ای، سه شهید و دو مجروح بر جای گذاشت. به طرف آنها رفتیم تا کمکشان کنیم. یکی از مجروحان که حالش مناسب تر بود، بسیار آه و ناله می کرد. برادر همراهمان گفت: چه خبره بابا! آنها که شهید شده اند، چیزی نمی گویند; تو که فقط زخمی شده ای، این همه داد و فریاد می کنی!\r\nهمین گفته طنزآمیز باعث سکوت آن برادر مجروح شد.\r\n"},{"id":1352,"category_id":9,"category_code":"s9","source_id":189,"title":"ایثار","content":"در عملیات محرم، یکی از برادران بسیجی ترکش خورد و به شدت مجروح شد. او در همان حال نزد ما آمد و گفت: من رفتنی هستم، بگویید چه کاری از دستم بر می آید تا برایتان انجام دهم.\r\nیک تیربار عراقی ما را خیلی اذیت می کرد. نارنجکی به این برادر بسیجی دادیم و گفتیم: اگر توانستی سینه خیز نزدیک دشمن برو و با این نارنجک، تیربار را خاموش کن. او سینه خیز پیش رفت، نزدیک دشمن که رسید، نارنجک را به طرف تیربار عراقی پرتاب کرد و در همان حال سرباز عراقی او را به رگبار بست؛ او شهید شد و تیربار دشمن هم نابود گشت.\r\n"},{"id":1353,"category_id":9,"category_code":"s9","source_id":190,"title":"حرف حساب...","content":"می خواست برگرده جبهه\r\nبهش گفتم: پسرم! تو به اندازه ی سنّت خدمت کردی\r\nبذار اونایی برن جبهه که نرفته اند\r\nچیزی نگفت و ساکت یه گوشه نشست...\r\n... وقت نماز که شد ، جانمازم رو انداختم که نماز بخونم\r\nدیدم اومد و جانمازم رو جمع کرد\r\nخواستم بهش اعتراض کنم که گفت:\r\nاین همه بی نماز هست!\r\nاجازه بدید کمی هم بی نمازا ، نماز بخونند\r\nدیگه حرفی برا گفتن نداشتم\r\nخیلی زیبا ، بجا و سنجیده جواب حرف بی منطقی من رو داد.\r\n"},{"id":1354,"category_id":9,"category_code":"s9","source_id":191,"title":"به احترام مادر...","content":"می گفت : احترام به والدین دستور خداست\r\nیه دستش توی عملیات قطع شده بود\r\nیه روز که اومدم خونه دیدم لباسهای کثیف رو شسته\r\nبهش گفتم: مادر برات بمیره! چطور با یه دست اینا رو شستی؟\r\nگفت: مادر! اگه دو تا دستم رو هم نداشتم باز وجدانم راضی نمیشد\r\nکه من خونه باشم و شما زحمت شستن لباس ها رو بکشی...\r\n"},{"id":1355,"category_id":9,"category_code":"s9","source_id":192,"title":"امدادگر","content":"بار اولم بود که مجروح می‌شدم و زیاد بی‌تابی می‌کردم یکی از برادران امدادگر بالاخره آمد بالای سرم و با خونسردی گفت:«چیه، چه خبره؟»تو که چیزیت نشده بابا!\r\nتو الان باید به بچه‌های دیگر هم روحیه بدهی آن وقت داری گریه می‌کنی؟! تو فقط یک پایت قطع شده! ببین بغل دستی است سر نداره هیچی هم نمی‌گه، این را که گفت بی‌اختیار برگشتم و چشمم افتاد به بنده خدایی که شهید شده بود!\r\nبعد توی همان حال که درد مجال نفس‌کشیدن هم نمی‌داد کلی خندیدم و با خودم گفتم عجب عتیقه‌هایی هستند این امدادگرا.\r\n"},{"id":1356,"category_id":9,"category_code":"s9","source_id":193,"title":"جنگ جنگ تا پیروزی","content":"شنیده اید می گویند عدو شود سبب خیر؟ ما تازه دیروز معنی آنرا فهمیدیم.\r\nدیروز عصر که با خمپاره سنگر تدارکات را زدند. نمی دانید تدارکاتچی بیچاره چه حالی داشت، باید بودید و با چشمان خودتان می دیدید. دار و ندارش پخش شده بود روی زمین، کمپوت، کنسرو، هر چه که تصورش را بکنید، همه آنچه احتکار کرده بود! انگار مال بابایش بود. بچه ها مثل مغولها هجوم بردند، هر کس دو تا، چهارتا کمپوت زده بود زیر بغلش و می گریخت و بعضی همانجا نشسته بودند و می خوردند. طاقت اینکه آنرا به سنگر ببرند نداشتند، دو لپی می خوردند و شعار می دادند: جنگ جنگ تا پیروزی، صدام بزن، صدام بزن جای دیروزی!\r\n"},{"id":1357,"category_id":9,"category_code":"s9","source_id":194,"title":"ایرانی گیلانی","content":"هفت - هشت تا مجروح بودیم در یک اتاق بزرگ، از هر ملیتی! اصفهانی، لر، آذری، شیرازی، کرد و بلوچ !\r\nاز هر کدام مان صدایی بلند می‏شد: اصفهانی‏ ناله می‏کرد، لره با یا حسین (علیه‏السلام) گفتن سعی می‏کرد دردش را ساکت کند، بلوچه از شدت درد میله‏های دو طرف تخت را گرفته بود و فشار می‏داد و شرشر عرق می‏ریخت و من هم خجالت و رودربایستی را گذاشته بودم کنار و یک نفس نعره می‏کشیدم و ننه‏‏ام را صدا می‏کردم!\r\nفقط نفر آخر که یک رشتی بود، هم درد می‏کشید و هم میان آه و ناله‏هایش کرکر می‏خندید . کم‏کم ماهایی که ناله می‏کردیم توجهمان به او جلب شد....\r\n"},{"id":1358,"category_id":9,"category_code":"s9","source_id":195,"title":"کیفر دنیوی","content":"تقریباً یک ساعت قبل از شروع عملیات، عده ای از نیروهای شما (ایرانی) به خاکریز ما نزدیک شده بودند، به طوری که در آن تاریکی، ما به راحتی آنها را می دیدیم. تعدادشان به خاطرم نیست، اما بعد از یک درگیری کوتاهی که پیدا کردیم، آنها با به جا گذاشتن فقط یک مجروح، موفق به فرار شدند. آن مجروح پسر جوانی بود که شاید پانزده سال بیشتر نداشت.\r\nوقتی آمدیم او را اسیر کنیم، دست هایش را به علامت اسارت بالا برد. در آن تاریکی شب، من به وضوح چهره اش را می دیدم. جوان خوش قیافه ای بود. در میان ما فقط گروهبان «فیصل» بود که به کشتن این اسیر جوان تمایل نشان می داد، ولی سایر افراد با این عمل مخالف بودند.\r\nمن و تعدادی از سربازان از «فیصل» خواهش کردیم اجازه دهد این جوان را به پشت خط منتقل کنیم، ولی او می خواست این اسیر جوان را بکشد. او با گفتن کلماتی مانند: مجوس، فارس و... به اصرار ما توجه نکرد و با سلاح کلاشینکف، آن جوان مجروح را به رگبار بست و سر تا پای او را سوراخ سوراخ کرد، به طوری که اسلحه اش کاملاً خالی شد.\r\nاز جیب های این جوان، یک قرآن کوچک، یک جانماز و تکه ای پارچه که روی آن «یا مهدی ادرکنی» نوشته شده بود، به دست ما افتاد. تقریباً یک ساعت پس از شهادت آن جوان، حمله ایرانیان شروع شد. ما اصلاً فکر نمی کردیم به اسارت نیروهای شما در آییم، زیرا اطراف ما با میدان های وسیع مین پوشیده شده بود.\r\nدر این عملیات (والفجر 5) در همان دقایق اول، من قبل از این که ساعت شش صبح به اسارت نیروهای شما در آیم، جنازه گروهبان فیصل را شناختم. دیدم از سر تا پا به رگبار بسته شده و بدنش سوراخ سوراخ است.\r\n"},{"id":1359,"category_id":9,"category_code":"s9","source_id":196,"title":"شهیدان زنده اند الله اکبر!","content":"خاطره ای که خواهید خواند مربوط است به خانم «مینا نظامی» که وی در دوران دفاع مقدس از جمله پرستارانی بودند که به مجروحان و رزمندگان رسیدگی می کردند. \r\nخانم نظامی خاطره یکی از آن روزها را این گونه تعریف می کند: « ما مجروحی داشتیم که اهل نهاوند بود. این رزمنده روی مین رفته بود و دچار فراموشی شده بود و گذشته و مشخصاتش را به یاد نمی آورد. از طرفی به خانواده او گفته بودند که فرزندشان شهید شده است. ما با او خیلی صحبت می کردیم، بلکه به حرف آید و از کسالت در بیاید. گاهی که به مجروحان دیگر سر کشی می کردم او را با خودم می بردم تا دیگران هم با او حرف بزنند. من نام «علی» را برایش انتخاب کرده بودم و جالب اینکه بعدا فهمیدم نامش علی است. البته نامش «علی محمد» بود که علی صدایش می کردند. کم کم او یک شماره تلفن یادش آمد و گفت: «شماره مغازه است. بگویید همدم خانم –مادرش- بیاید.» \r\nشیفت عصر و نزدیک اذان مغرب بود که رفتم و شماره را به اپراتور دادم و خواهش کردم بگیرد. به سختی ارتباط برقرار شد و صحبت کردم. فهمیدم چند روز قبل مراسم چهلمش را هم برگزار کرده اند! وقتی گفتم از بیمارستان تهران زنگ می زنم و مریضی با این مشخصات دارم و اسم مادرش همدم است، مغازه دار شوکه شده، با عجله رفت تا مادرش را صدا کند. از پشت گوشی صدای یک خانم با لهجه روستایی به گوش می رسید که می گفت: «می دانم که می خواهند بگویند که پسرت شهید شده.» بعد با عصبانیت شروع به صحبت کرد. هر چه می گفتم، انگار صدایم را نمی شنید. مرتب می گفت:«علی محمد من شهید شده!» \r\nبه او گفتم: «مگر نمی گویند شهیدان زنده اند الله اکبر ... واقعا پسر تو زنده است، می خواهی با او صحبت کنی؟»بعد علی گوشی را گرفت و یکی، دو کلام که حرف زدگوشی را به من داد. گوش دادم. مادرش با خوشحالی فریاد می زد: «شهیدان زنده اند الله اکبر، تلفن می زنند الله اکبر...» و جالب تر اینکه اطرافیان او هم این شعار را تکرار می کردند.»\r\n"},{"id":1360,"category_id":9,"category_code":"s9","source_id":197,"title":"سجده طولانی","content":"سال 1362 چند روزی از آغاز عملیات والفجر چهار می گذشت. اهداف از پیش تعیین شده به تصرف در آمده بود و رزمندگان مواضع خود را تثبیت کرده بودند. فرماندهان عمل کننده، ضمن دیدار از محور عملیاتی تصمیم گرفتند نماز خود را پشت سنگرها به صورت جماعت برگزار نمایند. قرار شد آقا مهدی (شهید مهدی باکری) نیز امام جماعت شوند.\r\nرزمندگان این لحظه را غنیمت شمردند و پشت سر فرمانده خود به جماعت ایستادند. نماز شروع شد. در رکعت اول بعد از سجده اول، آقا مهدی سر از سجده بر نداشت. سجده طولانی تر از حد معمول نماز شد. همه نماز را به فُرادا به پایان رساندند. بعد از نماز همه می خواستیم بدانیم چه شده است. یکی از فرماندهان که خودش را به آقا مهدی رسانده بود، به ما گفت: بگذارید راحت باشد. چند روزی است که آقا مهدی نخوابیده و در سجده نماز از خستگی به خواب رفته است.\r\nبه راستی که شهید مهدی باکری خودش را وقف اسلام کرده بود و جز شهادت، پاداشی نزد خدا نداشت.\r\n"},{"id":1361,"category_id":9,"category_code":"s9","source_id":198,"title":"مهدى به دريا پيوست‏","content":"روز 25 اسفند ماه 1363 در قرارگاه كربلا، فرماندهان ارشد سپاه سعى فراوانى مى‏كنند تا مهدى را راضى كنند به عقب برگردد، اما مهدى به پيام‏هاى بى‏سيم و پيك‏هايى كه دم به ساعت او را به عقب فرا مى‏خواندند، توجهى نمى‏كرد. در لحظات آخر، مهدى با راكت‏انداز آرپى‏جى 7 بر دوش به دشمن حمله مى‏كند. گلوله‏اى به سرش مى‏خورد و به سختى مجروح مى‏شود. بسيجى‏ها فرمانده رشيدشان را به قايق مى‏رسانند. مهدى، غرق در خون، براى آخرين بار به آن‏ها نگاه مى‏كند. قايق را به سرعت به سوى عقب مى‏برد اما در ميان راه ناگهان مهدى و عليرضا، آماج گلوله‏هاى دشمن قرار مى‏گيرند و بعد موشكى زوزه كشان در دل قايق منفجر مى‏شود و پيكر بى‏جان مهدى و عليرضا راهى درياها مى‏شود.\r\nپس از شهادت مهدى باكرى، امام خمينى(ره) در پيامى از او به عنوان شهيد اسلام ياد كرد و آية الله خامنه‏اى نوشت: «درود بر روان پاك مؤمن صادق و انقلابى و فداكار و سردار شجاع كه عهد پايدار خود را با خدا به سر آورد و خون پاك خود را نثار كرد و به فيض بى‏بديل شهادت نايل آمد.»\r\nهنوز كه هنوز است، بسيجيان سوخته‏دل لشكر عاشورا، چشم به آب‏هاى جنوب دارند كه چه زمانى آقا مهدى بر مى‏گردد، اما اين آرزوى مهدى بود كه پيكرش زمين را اشغال نكند.\r\n"},{"id":1362,"category_id":9,"category_code":"s9","source_id":199,"title":"در محراب نماز شب","content":"شب قبل از عملیات محرم, شهید مهدی سامع تا بعد از نیمه شب به شناسایی رفته بود و دیر وقت خسته و بی رمق برگشت و به خواب رفت. چون خسته بود و شب بعد هم باید در عملیات شرکت می کرد, بچه ها که برای نماز شب بیدار شده بودند او را بیدار نکردند.\r\nصبح که برای نماز بیدار شد, با ناراحتی گفت: مگر سفارش نکرده بودم مرا برای نماز شب بیدار کنید؟ وقتی علت را برایش توضیح دادند, آه سردی کشید و گفت: افسوس! شب آخر عمرم نماز شبم قضا شد! فردا شب سامع به خیل شهیدان محرم پیوست.\r\n"},{"id":1363,"category_id":9,"category_code":"s9","source_id":200,"title":"نماز در اتاق ژنرال ","content":"دوره خلبانی من در آمریکا تمام شده بود و بهترین نمرات را در امتحانات پروازی به دست آورده بودم، ولی به دلیل گزارش هایی که در پرونده ام وجود داشت، گواهی نامه خلبانی ام صادر نمی شد. سرانجام روزی به دفتر رئیس دانشگاه که یک ژنرال آمریکایی بود، احضار شدم. به اتاقش رفتم و احترام گذاشتم. او آخرین فردی بود که بایستی در مورد قبولی یا ردّ شدنم در خلبانی، نظر می داد. پرسش هایی کرد که من پاسخ دادم. از سؤال های ژنرال بر می آمد که میانه خوبی با من ندارد. ناگهان دَرِ اتاق به صدا در آمد و منشی ژنرال وارد شد و پس از احترام، از او خواست تا برای کار مهمی از اتاق خارج شود. با رفتن ژنرال، مدتی در اتاق تنها ماندم، به ساعتم نگاه کردم، وقت نماز ظهر بود. با خود گفتم: ای کاش در این جا نبودم و می توانستم نمازم را در اول وقت بخوانم.\r\nانتظارم برای آمدن ژنرال طولانی شد. اندیشیدم که هیچ کاری مهم تر از نماز نیست و با خود گفتم: خوب است نمازم را همین جا بخوانم. به گوشه ای از اتاق ژنرال رفتم و روزنامه ای را برداشتم و روی زمین پهن کردم. مُهرم را از جیبم در آوردم و مشغول خواندن نماز شدم. در همین حال ژنرال وارد اتاق شد. با خود گفتم: چه کنم؟ نمازم را ادامه دهم و یا آن را قطع کنم؟ تصمیم گرفتم نماز را ادامه دهم، هر چه خدا بخواهد همان خواهد شد. نماز را تمام کردم و از ژنرال به دلیل این که معطّل شده بود، عذرخواهی کردم.\r\nژنرال پس از چند لحظه سکوت، از من پرسید: چه می کردی؟! گفتم عبادت می کردم. گفت: بیشتر توضیح بده. گفتم: دین اسلام به ما مسلمانان دستور می دهد که در ساعت های خاصی از شبانه روز، با خداوند مناجات کنیم و نام این عبادت، نماز است.\r\nژنرال نگاه عمیقی به من کرد و گفت: پس این گزارش هایی که در پرونده ات نوشته اند برای همین کارهایت بوده است؟ گفتم: شاید. نمی دانم خداوند با این نماز چه اثری در دل او گذاشت که قلم خودنویسش را برداشت و گواهی نامه خلبانی مرا امضا کرد.\r\nآن روز به اولین جای خلوتی که رسیدم به پاس این نعمت بزرگی که خداوند به من داده بود، دو رکعت نماز شکر خواندم.\r\n"},{"id":1364,"category_id":9,"category_code":"s9","source_id":201,"title":"تسلیم در برابر نماز ","content":"بچه ها داشتند منطقه را پاک سازی می کردند. صبح زود بود و من هنوز نماز نخوانده بودم. وضو گرفتم و کنار یک پاسگاه عراقی که شب قبل تصرف کرده بودیم، مشغول خواندن نماز شدم. هنوز رکعت اول را تمام نکرده بودم که دو نفر عراقی از نهری که کنار پاسگاه جاری بود، بیرون آمدند. نتوانستم باقی نماز را بخوانم و با اسلحه به طرفشان رفتم. لباسهای شان خیس بود و می لرزیدند. اسلحه هم نداشتند. آن ها را داخل سنگر بردم و به عربی پرسیدم: شما زیر آب چه کار می کردید؟ گفتند: دیشب هنگام عملیات قایق های ما را عقب بردند تا نتوانیم فرار کنیم و ما هم از ترس رفتیم توی نیزارها. حالا هم وقتی دیدیم داری نگاهمان می کنی، از ترس خود را تسلیم کردیم. وقتی در جواب آن ها گفتم که من اصلاً به نیزار نگاه نمی کردم و فقط مشغول خواندن نماز بودم، قیافه های دو اسیر عراقی خیلی دیدنی بود ."},{"id":1365,"category_id":9,"category_code":"s9","source_id":202,"title":"معامله با خدا","content":"در ارتفاعات سخت کردستان بودیم که به ما اطلاع دادند شهید محراب آیة الله مدنی (ره) برای بازدید منطقه به محل استقرار ما می آید. هنگام بازدید، رزمنده نوجوانی جلو آمد و با حیایی خاص بعد از سلام و احوال پرسی گفت: الآن 9 روز است که آب پیدا نکرده ایم و نمازهایم را با تیمّم خوانده ام، تکلیف نمازهای من چه می شود؟\r\nشهید مدنی وقتی نگرانی او را دیدند در حالی که اشک در چشمانشان حلقه زده بود، گفتند: حاضری یک معامله با من بکنی؟ آن رزمنده گفت: چه معامله ای؟ شهید مدنی (ره) گفتند: من حاضرم تمام عبادت هایم را به تو بدهم و در عوض تو این 9 روز نمازت را به من بدهی.\r\n"},{"id":1366,"category_id":9,"category_code":"s9","source_id":203,"title":"من پول بلیط کمال را ندارم","content":"ییک بار که آقای رجایی به مشهد می رفت، محافظین ایشان که از سپاه بودند، خواستند به فرزند ایشان محبتی کنند، لذا به کمال (فرزندش) گفتند: شما هم در این سفر همراه ما بیایید. وقتی آقای رجایی کمال را در فرودگاه دید، خیال کرد محافظین او را برای تنوع یا بدر قه به فرودگاه آورده اند. وقتی می خواست از ماشین پیاده شود و سوار هواپیما شود، به محافظین گفت: یادتان باشد کمال را هم با خودتان ببرید و به منزل برسانید. کمال گفت: من هم می خواهم همراه شما به مشهد بیایم. تا محافظین گفتند: آقای رجایی اجازه بدهید کمال همراه ما بیاید. آقای رجایی گفت: من برای کار دولت می روم، نه کار شخصی و زیارت. ان شاءاللّه در وقت مناسب در یک سفر خانوادگی به مشهد می رویم و کمال را هم می بریم. همراهان گفتند: مشکل نیست ما برای ایشان بلیط می گیریم. آقای رجایی پاسخ داد: نه من فعلاً پول ندارم که پول بلیط ایشان را بدهم، هرچه دوستان اصرار کردند قبول نکرد تا این که یکی از همراهان گفت: اگر اجازه دهید من به شما پول قرض می دهم که برای ایشان بلیط بگیرید، هر وقت داشتید به من پس بدهید. پس از این پیش نهاد آقای رجایی گفت باشد به عنوان قرض قبول می کنم که پو ل بلیط کمال را بدهید."},{"id":1367,"category_id":9,"category_code":"s9","source_id":204,"title":"اسیر دوربین شدیم!","content":"در همان اوایل جنگ، یک روز بچه های صدا و سیما داشتند با دوربین خود صحنه های جبهه و جنگ را فیلم برداری می کردند که با یک گروه عراقی مواجه شدند، ولی خودشان متوجه نبودند. وقتی این دوربین در حال فیلم برداری بود، عراقی ها گمان کردند این وسیله، سلاح جدیدی است و چون غروب بود، متوجه نشدند که دوربین است. لذا دست هایشان را بالا بردند و اینها با کادر دوربین، آنها را به پشت خاک ریز آوردند. وقتی به پشت خاک ریز آمدند، ما با اسرا صحبت کردیم؛ خیلی ناراحت بودند و می گفتند: «ما اسیر دوربین شدیم!»"},{"id":1368,"category_id":9,"category_code":"s9","source_id":205,"title":"شهردار شهید(اخلاص)","content":"آقا مهدی باکری کسی نبود که با کت و شلوار شیک بیاید، دستش را به کمر بزند و دستور بدهد. با یک لباس معمولی آمد پیش ما و گفت: «شماها را امروز فرستاده اند؟» فکر کردیم از خودمان است. یکی به او گفت: «آره، آن بیل را بردار و بیا این جا مشغول شو!»\r\nاو هم به روی خودش نیاورد. رفت بیل را برداشت و شروع کرد به کار. دو سه نفر آمدند و گفتند: «آقای شهردار! شما چرا»؟ گفت: «من و آنها نداره، کار نباید روی زمین بماند.»\r\nما که از کارمان خجالت کشیده بودیم رفتیم بیل را از او بگیریم، نگذاشت و گفت: «شماها خیلی زحمت می کشید، من افتخار می کنم بیل دستم بگیرم. این جوری حس می کنم با هم هیچ فرقی نداریم، حس می کنم کار شما، کار من است، شهر شما، شهر من است.»\r\n"},{"id":1369,"category_id":9,"category_code":"s9","source_id":206,"title":"رعایت حق همسایه ","content":"ما در طبقه پایین زندگی می کردیم و آقای کلاهدوز در طبقه بالا. هیچ وقت متوجه ورود و خروج او نشدم. یک شب، اتفاقی در را باز کردم دیدم پوتین هایش را در آورده و به دست گرفته و از پله ها بالا می رود. فهمیدم طوری رفت و آمد می کرده تا مزاحم همسایه ها نشود.\r\nصبح ها چون زود می رفت، ماشین را تا سرِ کوچه هل می داد و سپس آن را روشن می کرد تا مبادا مزاحم کسی شود.\r\n"},{"id":1370,"category_id":9,"category_code":"s9","source_id":207,"title":"هیچ کس او را نمی شناسد(گم نامی)","content":"من و تیسمار بابائی برای بازدید یکی از مناطق جنگی جنوب به جبهه رفته بودیم. آفتاب غروب کرده بود و هوا خیلی سرد بود. از دور آتشی را دیدم که عده ای اطراف آن جمع شده بودند. از تیمسار خواستم تا با هم نزد آنها برویم، اما او نیامد و در گودالی دراز کشید.\r\nآنها درباره موضوعات مختلفی صحبت کردند. وقتی از نیروی هوایی و تیمسار بابائی سخن به میان آمد به شدت از او انتقاد می نمودند. یکی از آنها می گفت: تیمسار بابائی هم مثل سایر فرمانده ها بعضی وقت ها سری به قسمت های آرام جبهه می زند و بعد هم با هواپیمایش بر می گردد... . من که از حرف های آنان ناراحت شده بودم، گفتم: برادران! شما فکر می کنید آن کسی که در آن گودال دراز کشیده، کیست؟ او تیمسار بابائی است و همیشه در جبهه هاست؛ اما هیچ کس او را نمی شناسد!\r\n"},{"id":1371,"category_id":9,"category_code":"s9","source_id":208,"title":"اذان، تلفن خدا (نماز)","content":"حاج عبدالرزاق زین الدین، پدر شهیدان مهدی و مجید زین الدین، می گوید: شهید رجایی ـ رحمة الله علیه ـ می فرمود: چطور وقتی تلفن زنگ می زند، شما مضطربید که زود بروید و جواب دهید تا آقایی که پشت خط هست زیاد معطل نشود، حتی اگر در نماز هستید، نماز را سریع می خوانید تا بیایید جواب تلفن را بدهید! اذان که می گویند، خداوند پشت خط است; وظیفه ما این است که لبیک بگوییم."},{"id":1372,"category_id":9,"category_code":"s9","source_id":209,"title":"گناهان یک شهید...","content":"تیر خورد به سینه اش و شهید شد\r\nتوی دفترچه اش نوشته بود گناهان امروز من :\r\nخدایا منو ببخش! امروز سه چهار ساعت نشستم با رفیقام حرف زدم\r\nاما حاضر نبودم سه چهار دقیقه توی سجده با تو حرف بزنم\r\nخدایا! امروز توی فوتبال گلی زدم ، خوشحال شدم و خندیدم\r\nاما وقتی روضه خوان روضه ی حسین علیه السلام رو خواند اشک نریختم\r\nخدایا! من بد حال شده ام ، منو ببخش ...\r\n"},{"id":1373,"category_id":9,"category_code":"s9","source_id":210,"title":"حوری بهشتی...","content":"مجروح شده بود و وقتی چشم باز کرد دید روی تخت بیمارستانه\r\nهنوز چشماش خوب نمی دید و احساس کرد شهید شده\r\nدر همین حین خانوم پرستار سرنگ به دست وارد شد\r\nمجروح که فکر می کرد توی بهشته ، گفت: تو حوری هستی؟\r\nپرستار به هوای اینکه طرف موجی شده ، گفت: بله! من حوری ام\r\nمجروح با تعجب گفت: پس چرا اینقدر زشتی؟!!!\r\nپرستار هم ترش کرده و سرنگ رو محکم فرو کرد توی بدنش...\r\n"},{"id":1374,"category_id":9,"category_code":"s9","source_id":211,"title":"به بهونه امتحانات بچه های جبهه","content":"بعد از دایر شدن مجتمع های آموزشی رزمندگان در جبهه ، اوقات فراغت از جنگ را به تحصیل می پرداختیم .یكی از روزهای تابستان برای گرفتن امتحان ما را زیر سایه درختی جمع كردند . بعد از توزیع ورقه های امتحانی مشغول نوشتن شدیم .خمپاره اندازهای دشمن همزمان شروع كرده بودند . یك خمپاره در چند متریمان به زمین خورد .همه بدون توجه ، سرگرم جواب دادن به سئوالات بودند . یك تركش افتاد روی ورقه دوست بغل دستیم و چون گرم بود قسمتی از آن را سوزاند . ورقه را گرفت بالا و به ممتحن گفت : برگه من زخمی شده باید تا فردا به او مرخصی بدهی ! همه خندیدند و شیطنت دشمن را به چیزی نگرفتند ."},{"id":1375,"category_id":9,"category_code":"s9","source_id":212,"title":"قابل توجه مسئولین ...","content":"سر سفره ، سرهنگ گفت:\r\n«دكتر(شهید چمران)! به ميمنت ورود شما يه بره زديم زمين.»\r\nشانس آورديم\r\nچيزى از اون بره نخورده بود و اين همه عصبانى شد\r\nاگر يك لقمه ازش خورده بود خدا می دونه چیکارمون می کرد...\r\n"},{"id":1376,"category_id":9,"category_code":"s9","source_id":213,"title":"مهر پدر و فرزندی...","content":"نزدیک عملیات بود\r\nمی دونستم تازه دخترش بدنیا اومده\r\nدیدم سر یه پاکت از جیبش زده بیرون\r\nگفتم: چیه؟\r\nگفت:عکس دخترمه\r\nگفتم:بده ببینم\r\nگفت:خودم هنوز ندیدمش\r\nگفتم:چرا؟\r\nگفت:الان موقع عملیاته ،می ترسم مهر پدر و فرزندی کار دستم بده\r\nبذار بعد از عملیات می بینم.\r\n"},{"id":1377,"category_id":9,"category_code":"s9","source_id":214,"title":"به بهانه ی شهادت مادر شیعه ...","content":"یه مدت علیرغم تلاش زیاد بچه ها شهیدی پیدا نمیشد\r\nیکی از بچه ها نوار روضه ی ایام فاطمیه رو گذاشت\r\nناخودآگاه اشک بچه ها جاری شد و تفحص رو شروع کردیم\r\nهمون روز دو تا شهید پیدا کردیم که کنار هم بودند\r\nصورت هاشون رو به روی همدیگه بود\r\nدر کمال تعجب دیدیم پشت پیراهن هر دو تاشون نوشته شده:\r\nمیروم تا انتقام سیلی زهرا سلام الله علیها بگیرم\r\n"},{"id":1378,"category_id":9,"category_code":"s9","source_id":215,"title":"تربیت هوشمندانه","content":"بعد از کفش خودش ، کفش پسر بزرگمون رو هم واکس زد\r\nعلت این کارش رو که پرسیدم ، گفت:\r\nپسرمون جوونه\r\nممکنه اگه مستقیم بهش بگم کفشت رو واکس بزن جواب نده\r\nمی خوام به طور عملی واکس زدن رو بهش یاد بدم...\r\n"},{"id":1379,"category_id":9,"category_code":"s9","source_id":216,"title":"سنت حسنه ...","content":"از همه زودتر می یومد جلسه\r\nتا بقیه برسند دو رکعت نماز می خوند\r\nیکبار بعد از جلسه کشیدمش کنار و پرسیدم :\r\nنماز قضا می خونی؟\r\nگفت: نه! نماز می خونم که جلسه به یه جایی برسه\r\nهمینطور حرف روی حرف تلنبار نشه.\r\n"},{"id":1380,"category_id":9,"category_code":"s9","source_id":217,"title":"چهله ی عاشورا...","content":"یکی از بچه های با صفای گردان ما هر روز بعد از نماز صبح زیارت عاشورا می خواند\r\nنیت اش هم این بود که خدا دعاش رو مستجاب کنه و شهید بشه\r\nمی گفت: نذر کردم چهل روز زیارت عاشورا بخونم تا شهید بشم\r\nاگه توی چهله ی اول شهید نشدم ، دوباره می خونم\r\nاونقدر چهله می گیرم تا شهید بشم\r\nروز چهلم کار فیصله پیدا کرد و دعاش مستجاب شد\r\nشهید شد و کار به دور دوم هم نرسید\r\n"},{"id":1381,"category_id":9,"category_code":"s9","source_id":218,"title":"شلمچه؛قطعه ای از بهشت ...","content":"پروفسور ادون روزو رئیس موزه جنگ فرانسه رو بردیم شلمچه\r\nهمینطور که توی شلمچه راه می رفت نفس عمیق می کشید و می گفت:\r\nاینجا کجاست؟ این زمین با آدم حرف میزنه\r\nما اگه یه وجب از خاک این زمین رو توی فرانسه داشتیم\r\nنشونتون می دادم مردم چه زیارتگاهی درست می کردند\r\nبعدها می گفت: آرزومه یه هفته بتونم پای پیاده توی شلمچه قدم بزنم\r\nموقع رفتن به کشورش هم گفت:همه بیست سال مطالعه و تحقیقاتی که روی جنگ های دنیا داشته ام به یک طرف،این سه روزی که در ایرن بودم ودرباره جنگ شما شنیدم،یک طرف.\r\n"},{"id":1382,"category_id":9,"category_code":"s9","source_id":219,"title":"فرمانده ی خاکی...","content":"برای تهیه ی مهمات عملیات باید حاج احمد متوسلیان رو می دیدیم\r\nرفته بودیم اتاق فرماندهی ، اما نبود\r\nیکی از بچه ها گفت: فکر کنم بدونم کجاست. \r\nما رو برد سمت دستشوئی ها و دیدم حاج احمد اونجاست \r\nداشت در نهایت تواضع دستشویی ها رو تمیز می کرد\r\nرفتم سطل آب رو ازش بگیرم اما نداد. \r\nگفتم: « شما چرا حاجی؟!» \r\nهمین طور که کار می کرد،گفت: \r\n« یادت باشه ! فرمانده موقع جنگ برادر بزرگتر همه حساب میشه و در بقیه ی مواقع ، کوچک ترین و حقیرترین برادر اون ها »\r\n"},{"id":1383,"category_id":9,"category_code":"s9","source_id":220,"title":"از همدلی تا همراهی ...","content":"درست وقتی همه سر سفره بودند غیبش میزد\r\nظرف غذاش رو بر می داشت و از خونه میزد بیرون\r\nمی رفت و با بچه های همسایه غذاش رو می خورد\r\nآخه اونا اوضاع مالی شون مناسب نبود ...\r\n"},{"id":1384,"category_id":9,"category_code":"s9","source_id":221,"title":"رنگ و بوی فاطمه سلام الله علیها","content":"توی عملیات محرم مجروح شد و دکترا ازش قطع امید کردند\r\nحضرت زهرا سلام الله علیها اومده بودند به خوابش و فرموده بودند:\r\nپسرم! تو شفا گرفتی ؛ فقط قول بده جبهه رو ترک نکنی\r\nبعد از این خواب سر از پا نمی شناخت\r\nتوی عملیات خیبر شد فرمانده ی گردان علی اکبر علیه السلام\r\nاز بس که حضرت زهرایی بود اسم گردانش رو به یا زهرا سلام الله علیها تغییر داد\r\nشهید که شد ایام فاطمیه بود و ترکش خورده بود به پهلوش\r\n"},{"id":1385,"category_id":9,"category_code":"s9","source_id":222,"title":"مردان تکلیف گرا...","content":"بهش گفتم فرزندت به دنیا اومده.\r\nچند روز بعد اومد مرخصی تا بچه اش رو ببینه.\r\nاما احساس کردم زیاد به بچه اش توجه نمی کنه.\r\nکم بغلش می کرد ... کم نوازشش می کرد.\r\nبهش گفتم: « چرا اینقدر به بچه بی توجهی؟\r\nمگه از به دنیا اومدنش خوشحال نیستی؟ »\r\nگفت: چرا! ولی نمی خوام زیاد بهش وابسته بشم.\r\nاگه باهاش انس بگیرم ، دیگه نمی تونم برم جبهه »\r\n"},{"id":1386,"category_id":9,"category_code":"s9","source_id":223,"title":"پرسپولیس هورا - استقلال ...","content":"«اوائل فتح فاو من و بهترین دوستم، علی ناهیدی، به دلیل عجیبی به مدت یک هفته با هم قهر کردیم. ما دو تا سر تیم های استقلال و پرسپولیس با هم دعوامون شد. من استقلالی بودم و علی پرسپولیسی. یک هفته قبل از عملیات، طبق معمول ما داشتیم برای هم کرکری می خوندیم و از تیمهای مورد علاقمون حمایت می کردیم که بحث کم کم جدی شد.\r\nعلی زد به پروین و یک نفس گفت: شیش شیش شیشتایی هاش. من هم کم آوردم و شروع کردم به بد و بیراه گفتن. بعدهم بیخیال هم ششل و پس از شروع عملیات دیگر علی را ندیده بودم. دلم هزار راه رفت. هی با خودم می گفتم نکنه علی شهید یا اسیر شده باشه. نکند بد جوری مجروح شده باشه.\r\nای خدا اگه چیزیش شده باشه، من جواب ننه باباشو چی بدم. دیگه داشتم رسما گریه می کردم که دیدم بچه دارند می خندند و هیاهو می کنند.\r\nیکهو شنیدم عده ای با لهجه ای فارسی شعار می دهند که: « پرسپولیس هورا - استقلال سوراخ!!!» با تعجب سرم را به طرف صدا گرداندم و صحنه ای عجیب و باورنکردنی را دیدم. دهها اسیر عراقی پابرهنه و شعارگویان به طرف ما می آمدند.\r\nپیشاپیش آنها علی، سوار بر شانه های یکی از درجه دار های سبیل کلفت عراقی بود و یک پرچم سرخ را تکان می داد و عراقی ها با دستور او شعار می دادند:\r\nپرسپولیس هورا - استقلال سوراخ\r\nاین اولین و آخرین بار بود که به این شعار حسابی و از ته دل خندیدم و شاد شدم. دویدم به سمت علی و او هم با دیدن من از شانه های آن بدبخت اومد پایین و همدیگر را بغل کردیم و صورت همدیگه را ماچیدیم (بوس کردیم). علی با خنده به من گفت: می بینی اکبر، حتی عراقیها هم طرفدار پرسپولیس اند. هر دو غش غش خندیدیم. عراقی ها هم که نمی دانستند دارند چه شعاری می دهند با ترس و لرز فریاد می زدند: پرسپولیس هورا - استقلال سوراخ\r\n"},{"id":1387,"category_id":9,"category_code":"s9","source_id":224,"title":"خر و پف","content":"وقتی به خط پدافندی پاسگاه زید رسیدیم، شب بود. یکی از بچه های اطلاعات عملیات گفت: برویم تو سنگر اطلاعات بخوابیم تا صبح بشود و ببینیم تکلیف چیست.\r\nوسط سنگر یک نفر خوابیده بود و پتو را روی سرش کشیده بود. چه خر و پفی هم می کرد. کنارش دراز کشیدیم، ولی مگر خوابمان می برد. خسته بودیم، کلافه شدیم. من با لگد به پایش زدم، گفتم: برادر، برو آن طرف تر بخواب، ما هم جایمان بشود بخوابیم. بیشتر منظورم این بود که بیدار شود و از صدای خر و پفش راحت شویم. او هم خودش را کشید آن طرف تر و هر سه خوابیدیم.\r\nمی دانستم زین الدین هم به خط پدافندی آمده اما نمی دانستم همان کسی است که من به او لگد زده ام. تا این که یکی آمد و صدایش کرد: آقا مهدی، برادر زین الدین!\r\nتمام تنم یخ کرد، پتو را روی سرم کشیدم تا شناخته نشوم. حسابی خجالت کشیدم ولی شهید زین الدین بلند شد و بدون این که به روی خودش بیاورد، رفت.\r\nبعد از نیم ساعت آمد و دوباره سرجایش خوابید، انگار نه انگار. اگر من به جایش بودم، لااقل آن لگد را یک جوری تلافی می کردم.\r\n"},{"id":1388,"category_id":9,"category_code":"s9","source_id":225,"title":"داستان نماز شهید صیاد شیرازی","content":"در يكى از روستاهاى فيروزكوه ، جلسه بزرگداشت شهدا برپا بود و شهيد امير سپهبد صياد شيرازى به عنوان سخنران دعوت شده بود.پس از مداحى و چند برنامه مرسوم ديگر از شهيد صياد خواستند سخنرانى بكند. ايشان پشت تريبون قرار گرفت و پس از شروع به صحبت با نام خداوند تبارك و تعالى و درود و صلوات بر پيامبر و آلش (عليهم السّلام) فرمود: روزى جلسه مهمى در مورد جنگ خدمت حضرت امام بوديم ، وقت نماز شد ، امام وضو گرفت و به نماز ايستاد و ما هم به تبع امام فهميديم وقت نماز است و نماز بر همه چيز ترجيح دارد. بعد شهيد صياد شيرازى با اشاره به وقت نماز به حضار فرمود: الان هم وقت نماز هست اگر خواستيد بعد از نماز براى شما سخنرانى مى كنم. صحبت را تمام كرد و صفهاى نماز تشكيل شد و همانجا در اول وقت نماز جماعت برپا شد."},{"id":1389,"category_id":9,"category_code":"s9","source_id":226,"title":"عروج آسمانی...","content":"همسر شهید: «هر روز صبح تا جلوی در می رفتم و بدرقه اش می کردم و راهش می انداختم.آن روز صبح سرگرم کاری بودم. علی [شهید صیاد] آمده و من را صدا کرده بود که : \"حاج خانم، من دارم می روم\"، ولی من نشنیده بودم.\r\nسرگرم کار خودم بودم که دیدم صدایی آمد، نه خیلی بلند. فکر کردم باز هم بچه ها توی کوچه ترقه انداخته اند. محل نگذاشتم. یکدفعه دیدم مهدی بدو آمد توی خانه. توی سرش می کوبد و گریه می کند. با گریه و التماس گفت: «مامان، تو را به خدا بیا. بابا را کشتند.» \r\nتا برسم جلوی در، دو بار خوردم زمین. آمدم دیدم خیلی آرام پشت فرمان نشسته، سرش افتاده روی شانه اش. انگار خواب باشد، سرو صورت و لباس هایش غرق خون بود، شیشه ماشین هم خرد شده بود. خواستم جیغ بکشم، ولی صدایم در نیامد. \r\nدویدم در خانه همسایه طبقه بالایمان. آنها رفتند علی را برداشتند و بردند بیمارستان. من هم آمدم نشستم پای تلفن. اصلاً نمی فهمیدم کجا را باید بگیرم. به هر که و هر کجا که میشناختم، زنگ زدم، ولی کسی گوشی را بر نمی داشت، انگار همه خواب بودند. دوباره دویدم دم در. کسی نبود. علی را برده بودند.فقط جلوی در خانه روی زمین خون ریخته بود، خون علی.\r\nقبل از شهادتش بارها و بارها به من گفته بود برای شهادت من دعا کن، ولی آن روزهای آخر خیلی جدی تر این حرف را می زد. من ناراحت می شدم. می گفتم: \"حرف دیگری پیدا نمی کنید بگویید؟\"\r\nآخرین بار گفت: \"نه خانم، من می دانم همین روزها شهید می شوم. خواب دیده ام که یکی از دوستان شهیدم آمده و دست مرا گرفته که با خودش ببرد. من همه اش به تو نگاه می کردم، به بچه ها. شماها گریه می کردید و من نمی توانستم بروم. خانم، شما باید راضی باشید که من شهید بشوم.\"\r\nانگار داشتند جانم را از توی بدنم می کشیدند بیرون. مستأصل نگاهش کردم. گفت: \"خانم! شما را به خدا رضایت بدهید.\" ساکت بودم. گفت: \"خانم شما را به فاطمه زهرا (س) قسم، بگویید که راضی هستید.\" \r\nساکت بودم. اشک تا پشت پلک هایم آمده بود، اما نمی ریخت. گفت: \"عفت؟\" یکدفعه قلبم آرام شد. گفتم: \"باشد.من راضی ام.\"\r\nیک هفته بعد علی شهید شد.»\r\n"},{"id":1390,"category_id":9,"category_code":"s9","source_id":227,"title":"اسلام...","content":"فرمانده مون یه دفترچه نوحه داشت\r\nهر وقت دلش می گرفت نوحه هاش رو زمزمه می کرد\r\nبچه ها هم از صدای دلنشینش استفاده می کردند\r\nشب عملیات فتح المبین دیدم چیزی توی دفترچه اش نوشت\r\nبعد از شهادتش دفترچه اش رو باز کردیم\r\nنوشته بود: ما می رویم تا اسلام بماند ...\r\n"},{"id":1391,"category_id":9,"category_code":"s9","source_id":228,"title":"سردار زهرایی ...","content":"چشمش آسیب دید و دکترا گفتند بینایی اش رو از دست داده\r\nمی گفتند دیگه نمیشه کاری کرد و جراحی هم بی فایده است\r\nمحمد اصرار می کرد که شما عمل کنید و کاری به نتیجه اش نداشته باشید\r\nبه دکترا می گفت: فقط با ذکر یا زهرا علیها سلام عمل رو شروع کنید\r\nبعد از عمل دکترا از نتیجه ی جراحی حیرت زده شدند\r\nعمل جراحی موفقیت آمیز بود با رمز یا زهرا علیها سلام\r\n"},{"id":1392,"category_id":9,"category_code":"s9","source_id":229,"title":"مقصد کربلا","content":"برادر، برادر! محمدرضا از حرکت ایستاد، نگاهی به عقب انداخت و به دنبال صدا گشت. مجروحی را دید که دو پایش با گلوله توپ قطع شده بود و خون ریزی زیادی داشت. با عجله به طرفش دوید و سرش را به دامن گرفت و زمزمه آب آب جگرش را سوزاند، دستی بر قمقمه اش کشید، اما به علت اصابت ترکش همه آب ها ریخته بود. با عجله به سمت خاک ریز مقابل رفت و مقداری آب آورد و بر لب های آن مجروح نزدیک کرد، چشمانش را گشود و به زحمت پرسید: این جا خاک عراق است یا ایران؟\r\nگفت: خاک عراق. اشکی از گونه مجروح سُر خورد و میان خون ها محو شد. نه، روا نیست من این آب را بنوشم در حالی که مولایم حسین (ع) را در همین خاک با لب تشنه شهید کردند. سرم را به طرف قبله بچرخان. \r\nبه طرف قبله که چرخید، به آرامی گفت: «اشهد ان لا اله الا اللّه». بعد نگاهی به کربلا کرد و گفت: «السلام علیک یا ابا عبداللّه». لبخندی زد و لب تشنه پر کشید.\r\n"},{"id":1393,"category_id":9,"category_code":"s9","source_id":230,"title":"سنگینی آن راز","content":"هنگام دیدن آموزش در بندرعباس، در یکی از ساختمانهای نیروی هوایی ارتش به سر می بریم. حدود 170 نفر آنجا استقرار داشتند. برای همین به سرعت سرویسهای بهداشتی کثیف می شد؛ اما صبح که از خواب برمی خاستیم، سرویسها تمیز بود؛ از تمیزی برق می زد. هیچ کس نمی دانست آنها را چه کسی نظافت می کند. اواسط دوره، «قباد شمس الدینی» پیرمردی 67 ساله که در آن سن و سال همراه ما شنا یاد گرفته بود، نزد من آمد و با چشمانی گریان گفت: حاج احمد دارد من را می کشد.\r\nبا تعجب پرسیدم: چرا؟ اشک ریزان گفت: همیشه می خواستم بدانم چه کسی دستشوییها را می شوید. یک شب بیدار ماندم و کشیک دادم. وقتی صدای آب از دستشویی شنیدم، آهسته به طرف صدا رفتم. چشمم به حاج احمد افتاد. جارو و شیلنگ به دست داشت و در حال نظافت بود. سعی کردم جارو و شیلنگ را از او بگیرم؛ ولی به من گفت که چرا بیدار مانده ام و بعد قول گرفت که آن موضوع را به کسی بازگو نکنم. گفتم: پس چرا به من گفتی؟ گفت: این راز داشت مرا می کشت.\r\n"},{"id":1394,"category_id":9,"category_code":"s9","source_id":231,"title":"نماز اول وقت","content":"یكی از دوستان شهید رجایی می‌گوید: در سال 52 یا 53، روزی به اتفاق شهید رجایی برای خوردن نهار قرار گذاشتیم. وقتی به خیابان ولی عصر، سه راهی شهید بهشتی رسیدیم، ناگهان رجایی گفت: «ماشین را نگهدار!» ماشین را متوقف كردم و گفتم: چه شده است؟ گفت: برویم مسجد و نماز بخوانیم.\r\nگفتم: رفقا منتظرند. گفت: واللّه من با خدای خود عهد كرده‌ام كه همیشه قبل از نهار، نماز ظهر و عصر را بخوانم، قبل از شام، نماز مغرب و عشاء را، و قبل از صبحانه نماز صبح را بخوانم و اگر یك روز این برنامه را ترك كردم، به عنوان جریمه یك روز روزه بگیرم. شما كه راضی به جریمه شدن من نیستید؟\r\n"},{"id":1395,"category_id":9,"category_code":"s9","source_id":232,"title":"پدر موشکی ایران","content":"رفته بودیم برای بازدید از موشک های فوق پیشرفته ی روسی. وقتی بازدیدمون تموم شد،حسن رو کرد به کارشناس موشکی روسیه و گفت:\"اگه می شه فن آوری این موشک رو در اختیار ما قرار بدید!\"ژنرال ها و کارشناسان روسی خندیدند و گفتند:\"امکان نداره این فن آوری فقط در اختیار کشور ماست.\"حسن خیلی جدی و محکم گقت:\"ولی ما خودمون این موشک رو می سازیم\"و دوباره صدای خنده ی اونا بلند شد.وقتی برگشتیم ایران،خیلی تلاش کردیم نمونه شو بسازیم،ولی نشد.وقتی از ساخت موشک ناامید شدیم ،حسن راهی مشهد الرضا شد.خودش تعریف می کرد،\"به امام رضا متوسل شد و سه روز توی حرم موندم.روز سوم بود که عنایت امام رضا رو حس کردم وحلقه ی مفقوده کار به ذهنم خطور کرد .وقتی زیارتم تموم شد دفترچه نقاشی دخترم رو برداشتم و طرحی رو که به ذهنم رسیده بود کشیدم تا وقتی رسیدم تهران عملی ش کنم.\"وقتی حسن از مشهد برگشت،سریع دست به کار شدیم و موشک رو ساختیم که به مراتب از مدل روسی،بهتر و پیشرفته تر بود."},{"id":1396,"category_id":9,"category_code":"s9","source_id":233,"title":"ظهر عاشورا . . . ","content":"همراه مادر شدم تا برسم به خانه. توی راه کلی حرف زدم و مقدمه چینی کردم تا خبر شهادت محمود را به اوبدهم .از مادر پرسیدم: مادر اگه محمود شهید بشه شما چه کار می کنین؟\r\nمادر گفت: این آروزی همه است . محمود خودش می خواست شهید بشه.\r\nهنوز به خانه نرسیده بودیم که به مادر گفتم: محمود شهید شده.\r\nمادر بدون هیچ تغییری در رفتار و کلامش پرسید: کِی؟ چه روزی؟ من ختم برداشتم که محمود روز عاشورا شهید بشه.\r\nوقتی گفتم محمود بعد از ظهر عاشورا شهید شده، مادر از جلوی خانه برگشت و رفت به طرف مسجد جامع.\r\nگفتم: مادر ، محمود شهید شده؛ شما دارین کجا می رین؟\r\nمادر برگشت به طرفم و گفت: بچه ام برای نماز شهید شد، منم می رم مسجد تا نماز بخونم.\r\n"},{"id":1397,"category_id":9,"category_code":"s9","source_id":234,"title":"تخت تا عرش ...","content":"سیزده سالش بود که رفت جبهه\r\nتوی عملیات بدر از ناحیه گردن قطع نخاع شد\r\nهفده سال روی تخت ولی همواره خندان بود\r\nبالای سرش این بیت شعر چشم نوازی می کرد:\r\nچرا پای کوبم ، چرا دست بازم\r\nمرا خواجه بی دست و پا می پسندد\r\nهمسرش میگه: نیم ساعت قبل از شهادتش بهم گفت:\r\nنگران نباش! جای من رو توی بهشت بهم نشون دادند\r\n"},{"id":1398,"category_id":9,"category_code":"s9","source_id":235,"title":"همرنگ همرزمان ...","content":"اهواز که بودیم مصطفی (چمران)زخمی شد\r\nهوا خیلی گرم بود و پای ایشون توی گچ\r\nپوستش به خاطر گرما خورده شده بود و خون می یومد\r\nبا این حال حاضر نبود کولر روشن کنند و می گفت:\r\nچطور کولر روشن کنم وقتی بچه ها توی گرما می جنگند؟\r\nمصطفی همون غذایی رو می خورد که همه می خوردند.\r\n"},{"id":1399,"category_id":9,"category_code":"s9","source_id":236,"title":"چادر...","content":"رگ هایش پاره پاره شده بود و خونریزی شدیدی داشت.\r\nوقتی دکتر این مجروح را دید به من گفت:\r\nبیارش داخل اتاق عمل...\r\nدکتر اشاره کرد که چادرم را در بیاورم تا راحت تر بتوانم مجروح را جابه جا کنم\r\nمجروح به سختی گوشه چادرم را گرفت و بریده بریده و به سختی گفت: \r\nمن دارم می روم تا تو چادرت را در نیاوری\r\nما برای این چادر داریم می رویم\r\nچادرم در مشتش بود که شهید شد...\r\n"},{"id":1400,"category_id":9,"category_code":"s9","source_id":237,"title":"یا حضرت عباس علیه السلام","content":"یه روز از یک سرهنگ ارتشی خواستند که پیشنماز بشه\r\nاما ایشون چون پاهاش آسیب دیده بود ، رد کرد\r\nبالاخره بچه ها اونقدر اصرار کردند که مجبور شد قبول کنه\r\nرکعت اول رو خوندیم\r\nوقتی می خواست برای رکعت دوم از جا بلند بشه ، گفت: یا حضرت عباس علیه السلام!\r\nهمه زدند زیر خنده و نماز به هم خورد.\r\nاو برگشت و گفت:بابا من که گفتم من رو جلو نفرستید.\r\nوقتی خواستم برا رکعت دوم بلند بشم پاهام درد گرفت \r\nناخواسته گفتم : یا حضرت عباس علیه السلام\r\n"},{"id":1401,"category_id":9,"category_code":"s9","source_id":238,"title":"ایستگاه صلواتی ...","content":"دو تا از بچه ها اسیری را همراه خودشون آورده بودند و های های می خندیدند\r\nگفتم : این کیه؟\r\nگفتند : عراقیه\r\nگفتم: چطوری اسیرش کردید؟\r\nمی خندیدند !!!\r\nگفتند: از شب عملیات پنهان شده بود\r\nتشنگی فشار آورده بهش\r\nبا لباس بسیجی های خودمان اومده بود ایستگاه صلواتی \r\nمی خواسته شربت بگیره ، پول داده و این طوری لو رفته \r\nو هنوز می خندیدند....\r\n"},{"id":1402,"category_id":9,"category_code":"s9","source_id":239,"title":"مصاحبه","content":"در کنار هیلکوپتر جنگی اش ایستاده بود و خبرنگاران هر کدام به نوبت از او سوال می‌کردند.\r\nخبرنگاران آمده اند تا از خلباني كه ركورددار بالاترین ساعت پرواز در جنگ را در جهان دارد، مصاحبه كنند\r\nخبرنگار ژاپنی پرسید: شما تا چه هنگام حاضرید بجنگید؟ \r\nخلبان خندید. سرش را بالا گرفت و گفت: ما برای خاک نمی جنگیم ما برای اسلام می جنگیم. تا هر زمان که اسلام در خطر باشد ، این را گفت و به راه افتاد.\r\nخبرنگاران حیران ایستادند. چند نفر به زبانهای مختلف از هم پرسیدند: کجا؟ خلبان شیرودی کجا می‌رود؟ هنوز مصاحبه تمام نشده \r\nاو همانطور که آستینهایش را بالا مي داد و می رفت، برگشت. لبخندی زد و بلند گفت: نماز! صدای اذان می آید وقت نماز است.\r\n"},{"id":1403,"category_id":9,"category_code":"s9","source_id":240,"title":"جهزیه","content":"جهيزيه ی فاطمه حاضر شده بود. يک عکس قاب گرفته از باباي شهيدش را هم آوردم. دادم دست فاطمه. گفتم: بيا مادر! اينو بگذار روي وسايلت.\r\nبه شوخي ادامه دادم: \r\nبالاخره پدرت هم بايد وسايلت رو ببينه که اگر چيزي کم و کسري داري برات بياره.\r\nشب عبدالحسين را خواب ديدم. گويي از آسمان آمده بود؛ با ظاهري آراسته و چهره ی روشن و نوراني. يک پارچ خالي تو دستش بود. داد بهم. با خنده گفت:\r\nاين رو هم بگذار روي جهيزيه ی فاطمه \r\nفردا رفتيم سراغ جهيزيه. ديديم همه چيز خريده‌ايم، غيراز پارچ\r\n"},{"id":1404,"category_id":9,"category_code":"s9","source_id":241,"title":"عملیاتی","content":"تا دو، سه‌ي‌ نصفه‌ شب‌ هي‌ وضو مي‌گرفت‌ و مي‌آمد سراغ‌ نقشه‌ها و به‌دقت‌ وارسيشان‌ مي‌كرد. يك‌وقت‌ مي‌ديدي‌ همان‌جا روي‌ نقشه‌هاافتاده‌ و خوابش‌ برده‌.\r\nخودش‌ مي‌گفت‌ «من‌ كيلومتري‌ مي‌خوابم‌.»\r\nواقعاً همين‌طور بود. فقط‌ وقتي‌ راحت‌ مي‌خوابيد كه‌ توي‌ جاده‌ باماشين‌ مي‌رفتيم‌.\r\nعمليات‌ خيبر، وقتي‌ كار ضروري‌ داشتند، رو دست‌ نگهش‌ مي‌داشتند. تا رهاش‌ مي‌كردند، بي‌هوش‌ مي‌شد.\r\nاين‌قدر كه‌ بي‌خوابي‌ كشيده‌ بود.\r\n"},{"id":1405,"category_id":9,"category_code":"s9","source_id":242,"title":"راز","content":"شهیدی بود كه همیشه ذکرش این بود:\r\nیابن الزهرا \r\nیا بیا یک نگاهی به من کن\r\nیا به دستت ما در کفن کن .\r\nاز بس این شهید به امام زمان (عجل الله تعالي فرجه) علاقه داشته است. \r\nبعد به دوست روحانی خود وصیت می کند. اگر من شهید شدم دوست دارم در مجلس ختم من تو سخنرانی کنی \r\nآن روحاني می گوید ما از جبهه برگشتیم وقتی آمدیم دیدیم عکس شهید را زده اند پیش پدر و مادر آمدم گفتم این شهید چنین وصیتی کرده است آيا من مي توانم در مجلس ختم او سخنرانی کنم؟\r\nآنان اجازه دادند\r\nدر مجلس سخنرانی کردم بعد گفتم ذکر شهید این بوده است\r\nیا بن الزهرا \r\nیا بیا یک نگاهی به من کن\r\nیا به دستت مرا در کفن کن\r\nوقتی این جمله را گفتم ، یک نفر بلند شد و شروع كرد فرياد زدن . وقتي آرام شد گفت: من غسال هستم دیشب آخرهاي شب به من گفتند يكي از شهدا فردا بايد تشييع شود و چون پشت جبهه شهيد شده است بايد او را غسل دهي \r\nوقتی که می خواستم این شهید را کفن کنم دیدم یک شخص بزرگواری وارد شد گفت: برو بیرون من خودم باید این شهید را کفن کنم. \r\nمن رفتم . در وسط راه با خود گفتم اين شخص كه بود و چرا مرا بيرون كرد . \r\nبا عجله برگشتم و ديدم اين شهيد كفن شده و تمام فضای این ساختمان غسال خانه بوی عطر گرفته بود.\r\nاز ديشب نمي دانستم رمز اين جريان چه بود و آن آقا كه بود ؛ اما حالا فهميدم \r\n"},{"id":1406,"category_id":9,"category_code":"s9","source_id":243,"title":"مادرم...","content":"مادرم زمانی که خبر شهادتم را شنیدی گریه نکن\r\nزمان تشیيع و تدفینم گریه نکن \r\nزمان خواندن وصیت نامه ام گریه نکن \r\nفقط زمانی گریه کن که مردان ما غیرت را فراموش می کنند \r\nو زنان ما عفت را وقتی جامعه ما را بی غیرتی و بی حجابی گرفت \r\nمادرم گریه کن...!!! که اسلام در خطر است .....\r\n"},{"id":1407,"category_id":9,"category_code":"s9","source_id":244,"title":"مصطفی کچل است؟!","content":"غاده ؛همسر شهيد چمران مي گويد \r\nروزي دوستم به من گفت :\r\n\"غاده! در ازدواج تو یك چیز بالاخره برای من روشن نشد. تو از خواستگارهایت خیلی ایراد می گرفتی، این بلند است، این كوتاه است... مثل این كه می خواستی یك نفر باشد كه سر و شكلش نقص نداشته باشد. حالا من تعجبم چه طور دكتر را كه سرش مو ندارد قبول كردی؟\"\r\nمن گفتم: «مصطفی كچل نیست. تو اشتباه می كنی.» \r\n...\r\nآن روز همین كه رسیدم به خانه، در را باز كردم و چشمم افتاد به مصطفی، شروع كردم به خندیدن. \r\nمصطفی پرسید «چرا می خندی؟» و من كه چشم هایم از خنده به اشك نشسته بود گفتم «مصطفی، تو كچلی؟ من نمی دانستم!» \r\nو آن وقت مصطفی هم شروع كرد به خندیدن ...\r\nاينقدر شهيد چمران داراي كمالات بوده كه همسرش حتي توجه به ظاهر او هم نمي كند .\r\n"},{"id":1408,"category_id":9,"category_code":"s9","source_id":245,"title":"کمپوت","content":"داشتم تو جبهه مصاحبه می گرفتم کنارم ایستاده بود که یه هو یه خمپاره اومد و بومممممم..... نگاه کردم دیدم ترکش بهش خورده و افتاده زمین دوربینو برداشتم رفتم سراغش. بهش گفتم تو این لحاظات آخر زندگی اگه حرفی صحبتی داری بگو...\r\nدر حالی که داشت اشهد و شهادتینش رو زیر لب زمزمه می کرد گفت : من از امت شهید پرور ایران یه خواهش دارم. اونم اینکه وقتی کمپوت می فرستید جبهه خواهشا پوستشو اون کاغذ روشو نکَنید!\r\nبهش گفتم: بابا این چه جمله ایه قراره از تلویزیون پخش شه ها یه جمله بهتر بگو برادر...\r\nبا همون لهجه اصفهونیش گفت: اخوی آخه نمی دونی تا حالا سه دفعه به من رب گوجه افتاده...!\r\n"},{"id":1409,"category_id":9,"category_code":"s9","source_id":246,"title":"مسافر کربلا","content":"چهار ساله بود ، مریضی سختی گرفت . پزشکان جوابش کردند . گفتند : این بچه زنده نمی ماند ! پدرش او را نذر آقا اباالفضل (ع) کرد . به نیت آقا به فقرا غذا می داد . تا اینکه به طرز معجزه آسایی این فرزند شفا یافت !هر چه بزرگتر میشد ارادت قلبی این پسر به قمر بنی هاشم بیشتر میشد . تاریخ تولد شناسنامه را تغییر داد و به جبهه رفت !در جبهه انقدر شجاعت از خود نشان داد که مسئول دسته گروهان اباالفضل (ع) از لشگر امام حسین (ع) شد . خوشحال بود که به عاشقان اربابش خدمت می کند .علیرضا کریمی شانزده سال بیشتر نداشت .آخرین باری که به جبهه می رفت گفت : راه کربــــــــــــــلا که باز شد برمیـــــگردم !شانزده سال بعد پیکرش بازگشت . همان روزی که اولین کاروان به طور رســــمی به سوی کربـــــــــــــــلا می رفت !!!آمده بود به خواب مسئول تفحص ، گفته بود :زمانشرسیده که من برگـــردم !!! مــــــحل حضورپیکرش را گفته بود !!عجیب بود .\r\n\r\nپیکرش به شهردیگری منتقل شد . مدتی بعد او را آوردند ، روزی که تشییع شد روز تاســوعا بود . روز اباالـــفضل(ع)در پایان آخرین نامه اش برای من و شما نوشته بود : به امید دیدار در کربلا_ برادر شما علیرضا .حالا هرکس مشکلی برای سفر کربلا داره به سراغ علیرضا میره ...\r\n"},{"id":1410,"category_id":9,"category_code":"s9","source_id":247,"title":"شفاعت","content":"\r\nبرای ماموریت اعزام شدند اهواز.باهم رفتند کنار پل کارون.\r\n\r\nچهره ی محمد حسین درهم رفت.وضعیت نامناسب پوشـــــش خانواده ای نظر او را جلـــــــب کرد.دست دوستش را گرفت و گفت:«بریم عملیات با زبان».\r\n\r\nکشان کشان دوستش را برد طرف آن خانواده.با چهره ی گشاده رفت سراغ پیــــرمردی که سرپرست خانـــــواده بودو گفت:\r\n\r\n«آقای محترم هیچ میدانید این جا بوی باروت به مشام میرسه؟میدانید اهواز از شهر های مقاوم خط مقدم جنگه؟می دانید شما میزبان خوب رزمندگان هستید؟»\r\n\r\nپیرمرد گفت :«خوب حالا که چی؟باید چکار کنم؟»\r\n\r\nمحمد گفت:«ما که از شما چیزی نمیخواهیم فقط پایبندی شما مردم محترم را به ارزش ها و آرمان های اسلامی میخواهیم»\r\n\r\n\r\nپیرمرد فهمید .صورت محمد را بوسید و گفت:«به شرطی که ما را هم شفاعت کنی!!!!».\r\n"},{"id":1411,"category_id":9,"category_code":"s9","source_id":248,"title":"قمقمه","content":"یک شهید پیدا کردیم، طرف های سه راه شهادت.\r\nهیچی هم راهش نبود. نه پلاک، نه کارت شناسایی. فقط یک قمقمه هم راهش بود؛ پر آب.\r\nروی قمقمه چیزی نوشته بود. قمقمه را شستیم تا بتوانیم بخوانیمش. نوشته بود « قربان لب تشنه ات یا حسین(ع).»\r\n"},{"id":1412,"category_id":9,"category_code":"s9","source_id":249,"title":"یکی برای همه...","content":"آخرین مسئولیت شهید پلارک ، فرمانده دسته بود . در ولفجر8 از ناحیه شکم و دست مجروح شد ، اما کمتر کسی می دانست که او مجروح شده است .\r\nروزی در جبهه خواستیم از یک رودخانه رد شویم ؛ زمستان بود و هوا به شدت سرد بود ، شهید پلارک رو به بقیه کرد و گفت:\"اگر یک نفر مریض بشه ، بهتر ازاینه که همه مریض بشن\" یکی یکی بچه ها را به دوش کشید و به طرف دیگر رودخانه برد. آخر کار متوجه شلوارش شدیم که یخ زده بود و پاهایش خونی شده بود.\r\n"},{"id":1413,"category_id":9,"category_code":"s9","source_id":250,"title":"بوسه باران","content":"در گردان ما برادری بود که همیشه عادت داشت پیشانی شهدا را ببوسد... \r\nوقتی شهید شد بچه ها تصمیم گرفتند پیشانی او را غرق بوسه کنند.....\r\nپارچه را که کنار زدیم نعش بی سر او دل ما را آتش زد...\r\n"},{"id":1414,"category_id":9,"category_code":"s9","source_id":251,"title":"نیمه‏ هاى شب بود كه شهید حسین علم الهدی نهج البلاغه می‏خواند.","content":"\"1."},{"id":1415,"category_id":9,"category_code":"s9","source_id":252,"title":null,"content":"نگاه كردم به ایشان، دیدم چهره ‏اش برافروخته شده و دارد اشك می‏ریزد. "},{"id":1416,"category_id":9,"category_code":"s9","source_id":253,"title":null,"content":"با زیر چشم، شماره صفحه نهج البلاغه را نگاه كردم و به ذهن سپردم پس از مدتى، "},{"id":1417,"category_id":9,"category_code":"s9","source_id":254,"title":null,"content":"سید حسین نهج البلاغه را بست و براى استراحت به بیرون رفت. من صفحه نهج البلاغه را باز كردم، "},{"id":1418,"category_id":9,"category_code":"s9","source_id":255,"title":null,"content":"دیدم همان خطبه‏اى است كه حضرت على (ع) در فراق یاران باوفایش ناله می‏كند و میفرماید: "},{"id":1419,"category_id":9,"category_code":"s9","source_id":256,"title":null,"content":"أین َ عمار؟ أین َ ذوالشهادتین؟ كجاست عمار؟ كجاست..."},{"id":1420,"category_id":9,"category_code":"s9","source_id":257,"title":"نیمه های شب","content":"\""},{"id":1421,"category_id":9,"category_code":"s9","source_id":258,"title":"نوشته ی روی دست","content":"اسیر شده بودیم ما رو بردند « اردوگاه العماره » داخل اردوگاه تعدادی از شهدای ایرانی رو دیدم معلوم بود .\r\nبعد از اسارت به شهادت رسیده بودند جمله ای که روی دست یکی از شهدای اونجا نوشته شده بود با \r\nخوندنش مو به بدنم راست شد و به شدت گریه کردم اون جمله رو هیچ وقت فراموش نمی کنم .\r\nشما هم بخونید و فراموش نکنید روی دست آن شهید با خودکار نوشته شده بود: مادر! من از تشنگی شهید شدم ...\r\n"},{"id":1422,"category_id":9,"category_code":"s9","source_id":259,"title":"2 بامداد","content":"بعد از ٦ ساعت درگيري بالاخره عملياتمون تموم شد..دستم تير خورده بود ولي انقدر مجروح هاي وخيم زياد بود كه روي رفتن سمت بهداري رو نداشتم...\r\nهمگي خسته و گرسنه بوديم..فرمانده گف استراحت كنيد تا فردا برنامه رو اعلام ميكنم\r\nهر كي رفت يه گوشه خوابيد...\r\nوقت واسه سنگر درست كردن نداشتيم\r\nمن يه جاي خواب خوب واسه خودم اماده كردم\r\nدراز كشيدم نيم ساعت چشمام بسته بود ولي خوابم نميبرد\r\nيكي صدام زد رضا رضا نامرديه ت اينجا بخوابي من جايي واسه خواب نداشته باشم\r\nپاشو يكم جارو بزرگتر كنيم منم بتونم بخوابم\r\nنگاش كردم و گفتم ت بيا اينجا بخواب من ميرم يه جا ديگه\r\nاونم از خدا خواسته اومد خوابيد \r\nرفتم يه گوشه رو زمين خوابيدم\r\nپاشيد پاشيد\r\nپناه بگيريد پناه بگيريد\r\nتا اومدم به خودم بنجبم يه تركش خمپاره خورد ت گردنم \r\nچشمام سياهي ميرفت\r\nدنبال علي ميگشتم\r\nبيهوش شدم\r\nبعد چند ماه بهوش اومدم \r\nهمه بدنم از كار افتاده بود\r\nحرف نميتونستم بزنم\r\nفقط ميشنيدم دكتر ميگفت اين رفتنيه منم خودمو اسير اين جنازه نميكنم\r\nهر روز به اين فك ميكردم اگه جا رو بزرگتر ميكردم و كنار علي ميخوابيدم اينطور نميشدم\r\nحالم روحيمم خراب بود\r\nت ذهنم ميگفتم اصلا علي چرا به من سر نميزنه؟؟؟\r\nمثلا رفيق بوديم همشهري بوديم وصيتنامه هامون دست همديگه بود...\r\nچند ماهي گذشت تا يكم بدنم بكار افتاد و زبونم واشد\r\nيكي از بچه ها كه اونشب با ما بود اومد پيشم\r\nتا سلام كرد گفتم علي كجاس؟؟نكنه درجه گرفته ما رو يادش رفته..\r\nاخماش رفت تو هم\r\nچند ثانيه اي سكوت كرد\r\nگفت:علي رو ت جاي خواب ت خاكش كردن\r\n(خمپاره دقيقا پاي همون جاي خواب من خورده بود زمين)\r\nموندم بگم خدايا شكرت كه زندم يا خدايا چرا من لياقت شهيد شدن نداشتم؟؟؟.......\r\n"},{"id":1423,"category_id":9,"category_code":"s9","source_id":260,"title":"فرمانده ی تیپ","content":"نگاهش می کردم. یک تَرکه دستش بود، روی خاک نقشه ی منطقه را توجیه می کرد.\r\nبِهِم برخورده بود. فرمانده گردان نشسته، یکی دیگر دارد توجیه میکند. فکر می کردم فرمانده گروهان است یا دسته. ندیده بودمش تا آن موقع. بلند شدیم.می خواست برود، دستش را گرفتم. گفتم : \" شما فرمانده گروهانی ؟\" خندید... \r\nگفت: \" نه یه کم بالاتر\" دستم را فشار داد و رفت.\r\nحاج حسن گفت: \"تو اینو نمی شناسی ؟\"\r\nگفتم: \" نه. کیه ؟\" \r\nگفت: \" یه ساله جبهه ای، هنوز فرمانده تیپت رو نمی شناسی؟\"\r\n"},{"id":1424,"category_id":9,"category_code":"s9","source_id":261,"title":"پسر پدر","content":"به نام خدا، من می‌خواهم در آینده شهید بشوم. برای این که...\r\nمعلم که خنده اش گرفته بود، پرید وسط حرف علی و گفت:\r\nببین علی جان! موضوع انشاء این بود که «در آینده می‌خواهید چه کاره بشوید.»\r\nباید در مورد یک شغل، یا یک کار توضیح می دادی.\r\nمثلاً، پدر خودت چه کاره است؟\r\nآقا اجازه؟...شهید...\r\n"},{"id":1425,"category_id":9,"category_code":"s9","source_id":262,"title":"کوچیک و بزرگ","content":"گفتند:\" حسین خرازی را آورده اند بیمارستان.\" \r\nرفتم عیادت. از تخت آمد پایین، بغلم کرد. \r\nگفت:\" دستت چی شده؟ \" دستم شکسته بود. گچ گرفته بودمش. \r\nگفتم: \" هیچی حاج آقا ! یه ترکش کوچیک خرده، شکسته.\"\r\nخندید... \r\nگفت: \" چه خوب! دست من یه ترکش بزرگ خورده، قطع شده\r\n"},{"id":1426,"category_id":9,"category_code":"s9","source_id":263,"title":"سوغاتی حج","content":"رفته بود مکه؛ وقتی برگشت با همسرم رفتیم دیدنش؛ خانه‌شان آن موقع در کوی طلاب بود؛ قبل از اینکه وارد اتاق بشویم، چشمم در راهرو افتاد به یک تلویزیون رنگی با کارت و بند و بساط دیگرش.\r\nبعد از احوال‌پرسی و چاق‌سلامتی صحبت کشید به حج او و اینکه چه کارهایی کرده و چه آورده و نیاورده. می‌خواستم از تلویزیون رنگی بپرسم، خودش گفت: «از وسایلی که حق خریدنش را داشتم، فقط یک تلویزیون رنگی آوردم». گفتم: «ان شاءالله که مبارک باشد و سال‌های سال برای شما عمر کند». خنده معنا داری کرد و گفت: «برای استفاده شخصی نیاوردم؛ آوردم که بفروشم و فکر می‌کنم شما مشتری خوبی باشی آقا صادق!».\r\nگفتم: «چرا بفروشید، حاج آقا؟»؛ گفت: «راستش من برای زیارت این حجی که رفتم، یک حساب دقیقی کردم و دیدم کل خرجی که سپاه برای من کرده، 16 هزار تومان شده است؛ می‌خواهم این تلویزیون را هم به همان قیمت بفروشم تا مدیون بیت‌المال نباشم».\r\nگفتم: «من تلویزیون را می‌خواهم اما از بازار خبر ندارم، اگر بیشتر بود چی؟» گفت: «اگر بیشتر بود، نوش جانت و اگر کمتر بود که دیگر از ما راضی باشید». تلویزیون را به همان قیمت 16 هزار تومان از حاج آقا خریدم و او هم پول را را دو دستی تقدیم سپاه کرد.\r\n"},{"id":1427,"category_id":9,"category_code":"s9","source_id":264,"title":"پارتی","content":"من یکی وقتی سر چند شماره از مجله سوره نامه تندی به سید(شهید آوینی) نوشتم که یعنی من رفتم و راهی خانه شدم. حالم خیلی خراب بود. حسابی شاکی بودم.\r\nپلک که روی هم گذاشتم «بی بی فاطمه» (صلوات الله علیها) را به خواب دیدم و شروع کردم به عرض حال و نالیدن از مجله، که «بی بی» فرمود با بچه‌ من چه کار داری؟ من باز از دست حوزه و سید نالیدم، باز «بی بی» فرمود: با بچه من چه کار داری؟ برای بار سوم که این جمله را از زبان مبارک «بی بی» شنیدم، از خواب پریدم. وحشت سراپای وجودم را فرا گرفته بود و اصلا به خود نبودم تا اینکه نامه ای از سید دریافت کردم. سید نوشته بود: «یوسف جان ! دوستت دارم. هر جا می خواهی بروی، برو! هر کاری که می خواهی بکنی، بکن! ولی بدان برای من پارتی بازی شده و اجدادم هوایم را دارند» دیگر طاقت نیاوردم و راه افتادم به سمت حوزه و عرض کردم سید پیش از رسیدن نامه ات خبر پارتی ات را داشتم و گفتم آنچه را آن شب در خواب دیده بودم.\r\n"},{"id":1428,"category_id":9,"category_code":"s9","source_id":265,"title":"رفاقتهای جنگ","content":"رفاقت‌های زمان جنگ عجیب بود؛ یک فرمانده گردان به نام «ماشاءالله رشیدی» داشتیم، او شب عملیات «کربلای 5» می‌خواست وارد عملیات شود؛ دم خط به سنگر من آمد؛ گردان هنوز نرسیده بود، او موضوعی تعریف کرد.\r\nرشیدی فرمانده گروهانی به نام ذکی‌زاده داشت که دو روز پیش شهید شده بود؛ رشیدی می‌گفت: من و ذکی‌زاده باهم عهد بستیم که هر کدام از ما زودتر شهید شد، وارد بهشت نشود، تا دیگری بیاید، دیشب ذکی‌زاده را خواب دیدم که به من می‌گفت: «ماشاءالله مرا دم در نگه داشتی چرا نمی‌آیی؟!».\r\nوقتی رشیدی این موضوع را تعریف کرد، فهمیدم که به زودی شهید می‌شود؛ او را نگه داشتم اما رفت و درگیر خط شد؛ بلافاصله هم شهید شد.\r\n"},{"id":1429,"category_id":9,"category_code":"s9","source_id":266,"title":"حکایت سرخ","content":"شب عملیات «والفجر ۸» شهید «محمد شمسی» در حاشیه اروند رود به مانعی برخورد و به شدت مجروح شد؛ هر چه اصرار کردیم که به عقب برگردد، قبول نکرد و گفت: «شما به عملیات ادامه دهید و نگذارید عملیات لو برود».\r\nوضع عجیبی بود، خون مثل جوی آب از بدنش جاری بود، به هر زحمتی بود بچه‌ها را متقاعد کرد تا به پیشروی ادامه دهند، من از فاصله نه چندان دور او را زیر نظر داشتم؛ زخم‌هایش عمیق بود و خونریزی شدیدی داشت. برای آنکه سر و صدا نکند و عملیات لو نرود، سرش را داخل رود فرو کرد و در همان حال مظلومانه به شهادت رسید.\r\n"},{"id":1430,"category_id":9,"category_code":"s9","source_id":267,"title":"بلند نشید!","content":"\r\nآمد تو، همه مان بلند شدیم. سرخ شد. \r\nگفت: \" بلند نشید جلوی پای من.\" \r\nگفتیم: \" حاجی ! خواهش می کنیم. اختیار داری. بفرمایید بالا.\" \r\nباز جلسه بود. ایستاده بود بیرون سنگر، \r\nمی گفت: \" نمی آم. شماها بلند می شید.\" \r\nقول دادیم بلند نشویم\r\n"},{"id":1431,"category_id":9,"category_code":"s9","source_id":268,"title":"امداد الهی","content":"درسنگرهای به جا مانده از بعثی ها مستقر شدیم، فرصت را غنیمت شمرده و از یکی از برادران، قرآنی را گرفتم و به آن تفأل زدم. \r\nسوره ی مبارکه ی فرقان آمد، آیه ی راجع به مرگ زندگی بود و از اینکه مردن و حیات به دست خداوند است. \r\nدر این موقع موشک یکی از هلی کوپترهای دشمن به سمت سنگر ما شلیک و منفجر شد. تمام گونی های پر از خاک سنگر به سر و روی ما ریخته شد. با اینکه موشک زیر سنگر ما عمل کرده بود، اما به هیچ یک از از ما آسیبی نرسید.\r\nیکی از مشکلات عملیات در هور این بود که دشمن با کمین هایی که در هور ایجاد کرده بود، با کوچک ترین حرکتی که از طرف بچه ها صورت می گرفت، مانند اثر رفت و آمد قایق ها و یا حرکت غواص ها که نی ها را به صدا در می آورد، دشمن پی به حرکت ما می برد. این مشکل در شب های عملیات صد برابر می شد، چون حرکت و رفت و آمد آن همه غواص و قایق قطعاً در هور برای دشمن ایجاد حساسیت می کرد. اما در شب عملیات «عاشورای 4» امداد الهی عجیبی اتفاق افتاد. و آن این بود که همزمان با حرکت غواصان و موج اول (اولین گروه عمل کننده) ناگهان تمامی قورباغه ها و موجودات هور با همدیگر شروع به سر و صدا کرده و حساسیت ها را خنثی کردند!\r\nاین امداد عجیب طوری بچه ها را دلگرم کرد که غواص ها – که در مواقع عادی آرام فین می زدند تا در جریان آب تغییر ایجاد نشود – در آب شیرجه می رفتند!\r\n"},{"id":1432,"category_id":9,"category_code":"s9","source_id":269,"title":"عقد آسمانی","content":"در سپاه، علاوه بر برادران، سه خواهر ایثارگر و شجاع نیز خدمت می کردند که به غیر از فعالیت در امور آموزش و پرورش و بخش جهاد سازندگی شهر بانه، قسمتی از وقت خود را صرف کمک به برادران سپاه می کردند و بازجویی و مراقبت از زندانیان زن را بر عهده داشتند. متأسفانه یک روز، در اثر حادثه ی دلخراشی یکی از این خواهران به شدت زخمی شد و پیکر نیمه جان او توسط «محمود خادمی»(فرمانده سپاه) به بیمارستان انتقال یافت. حدود یک سال از فعالیت این خواهر در شهر بانه می گذشت – اهل تهران بود و نسبت به خواهران دیگر کوشاتر. پس از چند ساعت محمود با چهره ای برافروخته و غمگین به سپاه بازگشت و باحالتی خاص خبر شهادت آن خواهر را علام کرد. البته من در آن روز برای انجام مأموریتی به باختران رفته بودم اما از بچه هایی که در آن صحنه حضور داشتند شنیدم که محمود بعد از اعلام خبر اضافه کرده بود که: «بچه ها من هم دیگر عمری نخواهم داشت، شاید خواست خدا بود که عقد ما در دنیای دیگری بسته شود.» چندی پس از شهادت آن خواهر، محمود نیز در حادثه ی دلخراشی به شهادت رسید."},{"id":1433,"category_id":9,"category_code":"s9","source_id":270,"title":"هرچی رهبرمون بگه","content":"عراقی ها آورده بودنش جلوی دوربین برای مصاحبه.\r\nقد و قواره اش، صورت بدون مویش، صدای بچه گانه اش، همه چیز جور بود؛\r\nهمان طور که عراقی ها می خواستند. \r\nازش پرسیدند: قبل از اینکه بیایی جنگ چیکار می کردی؟\r\nگفت: درس می خوندم.\r\nگفتند: کی تو رو به زور فرستاده جبهه؟\r\nگفت: چی دارید میگید؟! قبول نمی کردند بیام جبهه؛ خودم به زور اومدم؛ با گریه و التماس.\r\nگفتند: اگر صدام آزادت کنه، چیکار می کنی؟\r\nگفت: ما رهبر داریم؛ هر چی رهبرمون بگه.\r\nفقط همین دو تا سؤال را پرسیده بودند که یک نفر گفت:کات!\r\nبا جواب هایش نقشه ی عراقی ها را به آب داد.\r\n"},{"id":1434,"category_id":9,"category_code":"s9","source_id":271,"title":"احترام به والدین","content":"یک بار هم نشد حرمت موی سفید ما را بشکند یا بی سوادی ما را به رخمان بکشد. هر وقت وارد اتاق می شدم، نیم خیز هم که شده، از جاش بلند می شد. اگر بیست بار هم می رفتم و می آمدم، بلند می شد. می گفتم: علی جان، مگه من غریبه هستم؟ چرا به خودت زحمت می دی؟ می گفت: « احترام به والدین، دستور خداست».\r\nیک روز که خانه نبودم، از جبهه آمده بود. دیده بود یک مشت لباس نشسته گوشه ی حیاطه، همه را شسته بود و انداخته بود روی بند. وقتی رسیدم، بهش گفتم: الهی بمیرم برات مادر، تو با یک دست، چطوری این همه لباس رو شستی؟ گفت: « اگه دو دست هم نداشتم، باز وجدانم قبول نمی کرد من اینجا باشم و شما، زحمتِ شستنِ لباس ها را بکشی! »\r\n"},{"id":1435,"category_id":9,"category_code":"s9","source_id":272,"title":"مهمان عزیز","content":"وقتی رسیدیم، دیدیم عده زیادی برای استقبال آمده‌اند.\r\nـ چه کسی این جمعیت را مطلع کرده است؟ قرار نبود مزاحمت برای کسی فراهم شود.\r\nآقا خیلی ناراحت شده بودند. پدر شهید که متوجه ناراحتی آقا شده بود، کنار آقا نشست و گفت:\r\nنگران نباشید، از دفتر شما کسی ما را مطلع نکرده است. من دیشب خواب دیدم. خواب امام و علی‌رضا فرزند شهیدم را. هر دو خبر آمدن شما را به من دادند. گفتند: فردا شب میهمان عزیزی داری! خوب از میهمانت پذیرایی کن! پرسیدم آن میهمان کیست؟ امام فرمودند: \" رهبر شما\"\r\n"},{"id":1436,"category_id":9,"category_code":"s9","source_id":273,"title":"شهید گمنام","content":"زنجیر پلاک بود؛اما ار پلاک خبری نبود.حدود شش ماه بود توی معراج روی کفنش نوشته بودیم:«شهید گمنام».بار ها شده بود.میخوایستم برای تشییع به تهران بفرستمش؛اما دلم نمی آمد.توی دلم یکی میگفت دست نگهدار تا زمانش برسد.گل محمدی می گفت:«به خودم گفتم:همتی،مکانیک تفحص،وقتی دنبال یک آچار میگرده صلوات میفرسته؛ چرا من با ذکر صلوات دنبال پلاک این شهید نگردم؟»همین کار را کردم و دوباره سراغ پیکر رفتم،کفنش را بازکردم،توی جمجمه شهید یک تکه گل بود.درآوردم،دیدم پلاک شهید است.اللهم صل علی محمد و آل محمد."},{"id":1437,"category_id":9,"category_code":"s9","source_id":274,"title":"شهید کباب شده","content":"یه پتو سربازی را مچاله کرده بود زیر سرش و یه پتو دیگه را دور خودش پیچید، شاید هوا سرد نبود، اما همیشه وقتی گرم میشد خوابش میبرد. تازه داشت چشماش گرم میشد که صدای به زمین خوردن یه خمپاره ، مثل فنر از جاش پرید. اومد بیرون دید مصطفی جوکار مثل ذغال سیاه شده و داد میزنه: سوختم...سوختم.... آتیش گرفتم.... بوی عجیبی میداد، بویی که خیلی وقت بود به مشامش نخورده بود. \r\nبوی کباب...\r\nبر خلاف همیشه از شنیدن بوی کباب آب از دهانش راه نیفتاد، آخه مطمئنا گوشت بدن مصطفی خوردن نداشت.\r\nهمون بدنی که یه عمر برا خدا جنگید. بدنی که به خاطر فقر، به اندازه انگشتان یک دست مزه کباب رو نچشیده بود.\r\nسالهای سال از اون جریان گذشت، دیگه هیچ وقت با شنیدن بوی کباب، یاد خوبی نمی افتاد، یاد بدن سوخته و سیاه شده مصطفی میافتاد.\r\nدیگه هیچ وقت کباب نخورد.\r\n"},{"id":1438,"category_id":9,"category_code":"s9","source_id":275,"title":"به یاد شهدای گمنام","content":"خیلی گشته بودیم،نه پلاکی،نه کارتی،چیزی همراهش نبود.\r\nلباس فرم سپاه به تنش بود.چیزی شبیه دکمه پیراهن در جیبش نظرم را جلب کرد.\r\nخوب که دقت کردم،دیدم یک نگین عقیق است که انگار جمله ای رویش حک شده. خاک و گل ها را پاک کردم.\r\nدیگر نیازی نبود دنبال پلاکش بگردیم.روی عقیق نوشته شده بود\": \"به یاد شهدای گمنام\r\n"}];
